import { useState } from 'react';
import type { ReactNode } from 'react';
import './styles.css';

type IconName =
  | 'plus'
  | 'inbox'
  | 'note'
  | 'star'
  | 'archive'
  | 'settings'
  | 'sliders'
  | 'keyboard'
  | 'help'
  | 'search'
  | 'chevron'
  | 'user'
  | 'sparkles'
  | 'check'
  | 'cloud'
  | 'bolt'
  | 'paint'
  | 'lock'
  | 'link'
  | 'eye'
  | 'moon'
  | 'sun'
  | 'monitor'
  | 'external'
  | 'arrowRight';

type Appearance = 'light' | 'dim' | 'dark';

type IconProps = {
  name: IconName;
  size?: number;
  className?: string;
};

function Icon({ name, size = 18, className }: IconProps) {
  let glyph: ReactNode;

  switch (name) {
    case 'plus':
      glyph = <><path d='M12 5v14' /><path d='M5 12h14' /></>;
      break;
    case 'inbox':
      glyph = <><path d='M4 5.5h16v13H4z' /><path d='M4 14h4l1.5 2h5L16 14h4' /></>;
      break;
    case 'note':
      glyph = <><path d='M6 3.75h8l4 4v12.5H6z' /><path d='M14 3.75v4h4M9 12h6M9 15.5h4' /></>;
      break;
    case 'star':
      glyph = <path d='m12 4 2.45 4.96 5.47.8-3.96 3.86.94 5.45L12 16.5l-4.9 2.57.94-5.45-3.96-3.86 5.47-.8L12 4Z' />;
      break;
    case 'archive':
      glyph = <><path d='M4 7h16v12H4zM3 4h18v3H3z' /><path d='M9 11h6' /></>;
      break;
    case 'settings':
      glyph = <><circle cx='12' cy='12' r='3' /><path d='M19.4 15a1.7 1.7 0 0 0 .34 1.88l.06.06-1.7 1.7-.06-.06a1.7 1.7 0 0 0-1.88-.34 1.7 1.7 0 0 0-1.03 1.56v.08h-2.4v-.08a1.7 1.7 0 0 0-1.03-1.56 1.7 1.7 0 0 0-1.88.34l-.06.06-1.7-1.7.06-.06A1.7 1.7 0 0 0 8.46 15a1.7 1.7 0 0 0-1.56-1.03h-.08v-2.4h.08A1.7 1.7 0 0 0 8.46 10a1.7 1.7 0 0 0-.34-1.88l-.06-.06 1.7-1.7.06.06a1.7 1.7 0 0 0 1.88.34 1.7 1.7 0 0 0 1.03-1.56v-.08h2.4v.08a1.7 1.7 0 0 0 1.03 1.56 1.7 1.7 0 0 0 1.88-.34l.06-.06 1.7 1.7-.06.06A1.7 1.7 0 0 0 19.4 10a1.7 1.7 0 0 0 1.56 1.03h.08v2.4h-.08A1.7 1.7 0 0 0 19.4 15Z' /></>;
      break;
    case 'sliders':
      glyph = <><path d='M4 6h16M4 12h16M4 18h16' /><circle cx='9' cy='6' r='2' fill='currentColor' stroke='none' /><circle cx='15' cy='12' r='2' fill='currentColor' stroke='none' /><circle cx='10' cy='18' r='2' fill='currentColor' stroke='none' /></>;
      break;
    case 'keyboard':
      glyph = <><rect x='3.5' y='6' width='17' height='12' rx='2' /><path d='M7 10h.01M10 10h.01M13 10h.01M16 10h.01M7 14h.01M10 14h7' /></>;
      break;
    case 'help':
      glyph = <><circle cx='12' cy='12' r='9' /><path d='M9.6 9a2.5 2.5 0 1 1 4.15 1.88c-.92.75-1.75 1.15-1.75 2.62' /><path d='M12 16.7h.01' /></>;
      break;
    case 'search':
      glyph = <><circle cx='10.8' cy='10.8' r='6.3' /><path d='m16 16 4.2 4.2' /></>;
      break;
    case 'chevron':
      glyph = <path d='m9 18 6-6-6-6' />;
      break;
    case 'user':
      glyph = <><circle cx='12' cy='8' r='3.2' /><path d='M5.5 20a6.5 6.5 0 0 1 13 0' /></>;
      break;
    case 'sparkles':
      glyph = <><path d='m12 3 1.15 4.3L17.5 8.5l-4.35 1.2L12 14l-1.15-4.3L6.5 8.5l4.35-1.2L12 3Z' /><path d='m19 14 .65 2.35L22 17l-2.35.65L19 20l-.65-2.35L16 17l2.35-.65L19 14ZM5 14l.55 1.95L7.5 16.5l-1.95.55L5 19l-.55-1.95-1.95-.55 1.95-.55L5 14Z' /></>;
      break;
    case 'check':
      glyph = <path d='m5 12.5 4.2 4.2L19.5 6.8' />;
      break;
    case 'cloud':
      glyph = <path d='M7.2 18.2h9.4a3.4 3.4 0 0 0 .5-6.8A5.6 5.6 0 0 0 6.5 9a4.6 4.6 0 0 0 .7 9.2Z' />;
      break;
    case 'bolt':
      glyph = <path d='m13.5 2.8-8 11h6.1l-1.1 7.4 8-11h-6.1l1.1-7.4Z' />;
      break;
    case 'paint':
      glyph = <><path d='m14.7 4.3 5 5M13.2 5.8 4.6 14.4a2.1 2.1 0 0 0 0 3l2 2a2.1 2.1 0 0 0 3 0l8.6-8.6' /><path d='M4.2 20.2c1.7.5 3.2.2 4.2-.8M8.6 16.4l2 2' /></>;
      break;
    case 'lock':
      glyph = <><rect x='5' y='10' width='14' height='10' rx='2' /><path d='M8 10V7.5a4 4 0 0 1 8 0V10M12 14v2' /></>;
      break;
    case 'link':
      glyph = <><path d='M9.5 14.5 14.5 9.5' /><path d='M7.7 17.8H6.5a4.3 4.3 0 0 1 0-8.6h3' /><path d='M16.3 6.2h1.2a4.3 4.3 0 0 1 0 8.6h-3' /></>;
      break;
    case 'eye':
      glyph = <><path d='M3.5 12s3.1-5 8.5-5 8.5 5 8.5 5-3.1 5-8.5 5-8.5-5-8.5-5Z' /><circle cx='12' cy='12' r='2' /></>;
      break;
    case 'moon':
      glyph = <path d='M19.7 14.2A7.8 7.8 0 0 1 9.8 4.3 8.2 8.2 0 1 0 19.7 14.2Z' />;
      break;
    case 'sun':
      glyph = <><circle cx='12' cy='12' r='3.5' /><path d='M12 2.5v2M12 19.5v2M21.5 12h-2M4.5 12h-2M18.7 5.3l-1.4 1.4M6.7 17.3l-1.4 1.4M18.7 18.7l-1.4-1.4M6.7 6.7 5.3 5.3' /></>;
      break;
    case 'monitor':
      glyph = <><rect x='3.5' y='4.5' width='17' height='12' rx='2' /><path d='M8.5 20h7M12 16.5V20' /></>;
      break;
    case 'external':
      glyph = <><path d='M14 4h6v6M20 4l-8 8' /><path d='M18 13v5a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h5' /></>;
      break;
    case 'arrowRight':
      glyph = <><path d='M5 12h13' /><path d='m13 6 6 6-6 6' /></>;
      break;
    default:
      glyph = null;
  }

  return (
    <svg
      width={size}
      height={size}
      viewBox='0 0 24 24'
      fill='none'
      stroke='currentColor'
      strokeWidth={1.8}
      strokeLinecap='round'
      strokeLinejoin='round'
      className={className}
      aria-hidden='true'
    >
      {glyph}
    </svg>
  );
}

function Toggle({ checked, onChange }: { checked: boolean; onChange: () => void }) {
  return (
    <button
      type='button'
      className={`toggle ${checked ? 'is-on' : ''}`}
      role='switch'
      aria-checked={checked}
      onClick={onChange}
    >
      <span className='toggle-thumb' />
    </button>
  );
}

const workspaceNav: Array<{ label: string; icon: IconName; count?: string }> = [
  { label: 'Inbox', icon: 'inbox', count: '12' },
  { label: 'All notes', icon: 'note' },
  { label: 'Favorites', icon: 'star', count: '4' },
  { label: 'Archive', icon: 'archive' },
];

const settingsNav: Array<{ label: string; icon: IconName }> = [
  { label: 'General', icon: 'sliders' },
  { label: 'Appearance', icon: 'paint' },
  { label: 'Shortcuts', icon: 'keyboard' },
  { label: 'Connections', icon: 'link' },
  { label: 'Privacy', icon: 'lock' },
];

const themes: Array<{ id: Appearance; label: string; caption: string; icon: IconName }> = [
  { id: 'light', label: 'Light', caption: 'For daylight', icon: 'sun' },
  { id: 'dim', label: 'Dim', caption: 'Balanced contrast', icon: 'monitor' },
  { id: 'dark', label: 'Dark', caption: 'For late sessions', icon: 'moon' },
];

function App() {
  const [activeSection, setActiveSection] = useState('General');
  const [appearance, setAppearance] = useState<Appearance>('dim');
  const [fontFamily, setFontFamily] = useState('Inter');
  const [noteWidth, setNoteWidth] = useState('Comfortable');
  const [autoSave, setAutoSave] = useState(true);
  const [livePreview, setLivePreview] = useState(true);
  const [spellcheck, setSpellcheck] = useState(true);
  const [backlinks, setBacklinks] = useState(false);
  const [saveState, setSaveState] = useState('All changes saved');

  const handleSave = () => {
    setSaveState('Saved just now');
  };

  return (
    <div className='app-shell'>
      <aside className='workspace-sidebar'>
        <div className='brand'>
          <span className='brand-mark'>n</span>
          <span className='brand-name'>noted<span>.</span></span>
        </div>

        <button type='button' className='new-note-button'>
          <span className='new-note-icon'><Icon name='plus' size={16} /></span>
          <span>New note</span>
          <kbd>N</kbd>
        </button>

        <nav className='workspace-nav' aria-label='Main navigation'>
          <div className='sidebar-label'>Workspace</div>
          {workspaceNav.map((item) => (
            <button
              type='button'
              className={`workspace-link ${item.label === 'Inbox' ? 'is-active' : ''}`}
              key={item.label}
            >
              <span className='workspace-link-icon'><Icon name={item.icon} size={17} /></span>
              <span className='workspace-link-label'>{item.label}</span>
              {item.count && <span className='nav-count'>{item.count}</span>}
            </button>
          ))}
        </nav>

        <div className='sidebar-lower'>
          <button type='button' className='sidebar-settings-link is-active' onClick={() => setActiveSection('General')}>
            <span className='workspace-link-icon'><Icon name='settings' size={17} /></span>
            <span className='workspace-link-label'>Settings</span>
          </button>
          <div className='workspace-switcher'>
            <span className='workspace-avatar'>J</span>
            <span className='workspace-switcher-copy'>
              <strong>Jules' space</strong>
              <span>Personal workspace</span>
            </span>
            <Icon name='chevron' size={15} className='workspace-chevron' />
          </div>
        </div>
      </aside>

      <main className='main-area'>
        <header className='topbar'>
          <div className='breadcrumbs'>
            <span className='breadcrumb-muted'>Workspace</span>
            <Icon name='chevron' size={14} />
            <strong>Settings</strong>
          </div>
          <div className='topbar-actions'>
            <button type='button' className='topbar-search'>
              <Icon name='search' size={16} />
              <span>Search notes</span>
              <kbd>⌘ K</kbd>
            </button>
            <button type='button' className='topbar-icon-button' aria-label='Keyboard shortcuts'>
              <Icon name='keyboard' size={17} />
            </button>
            <button type='button' className='topbar-icon-button' aria-label='Help'>
              <Icon name='help' size={17} />
            </button>
            <span className='user-avatar' title='Signed in as Jules'>JS</span>
          </div>
        </header>

        <div className='page-wrap'>
          <section className='page-header'>
            <div>
              <div className='page-eyebrow'>
                <span className='eyebrow-icon'><Icon name='sparkles' size={14} /></span>
                Your preferences
              </div>
              <h1>Settings</h1>
              <p>Make your note space feel like home.</p>
            </div>
            <div className='header-meta'>
              <span className='sync-pill'><Icon name='cloud' size={15} /> Synced a moment ago</span>
            </div>
          </section>

          <div className='settings-layout'>
            <aside className='settings-nav-panel'>
              <div className='settings-nav-heading'>
                <span className='settings-nav-title'>Settings</span>
                <span className='settings-nav-subtitle'>Customize your workspace</span>
              </div>

              <nav className='settings-links' aria-label='Settings sections'>
                {settingsNav.map((item) => (
                  <button
                    type='button'
                    className={`settings-link ${activeSection === item.label ? 'is-active' : ''}`}
                    key={item.label}
                    onClick={() => setActiveSection(item.label)}
                    aria-current={activeSection === item.label ? 'page' : undefined}
                  >
                    <span className='settings-link-icon'><Icon name={item.icon} size={17} /></span>
                    <span>{item.label}</span>
                    {activeSection === item.label && <Icon name='chevron' size={14} className='settings-link-chevron' />}
                  </button>
                ))}
              </nav>

              <div className='help-card'>
                <span className='help-card-icon'><Icon name='help' size={18} /></span>
                <div>
                  <strong>Need a hand?</strong>
                  <p>Find answers in the help center.</p>
                  <button type='button' className='help-card-button'>
                    Visit help center <Icon name='external' size={13} />
                  </button>
                </div>
              </div>
            </aside>

            <section className='settings-card' aria-labelledby='settings-title'>
              <div className='settings-card-heading'>
                <div>
                  <span className='section-label'>Workspace</span>
                  <h2 id='settings-title'>{activeSection} preferences</h2>
                  <p>Manage the details that shape your writing flow.</p>
                </div>
                <div className={`save-indicator ${saveState === 'Saved just now' ? 'is-fresh' : ''}`}>
                  <span className='status-dot' />
                  {saveState}
                </div>
              </div>

              <div className='form-section'>
                <div className='form-block-heading'>
                  <div>
                    <h3>Appearance</h3>
                    <p>Choose a look that keeps you in the flow.</p>
                  </div>
                </div>

                <div className='theme-options'>
                  {themes.map((theme) => {
                    const selected = appearance === theme.id;
                    return (
                      <button
                        type='button'
                        className={`theme-option ${selected ? 'is-selected' : ''}`}
                        key={theme.id}
                        onClick={() => setAppearance(theme.id)}
                        aria-pressed={selected}
                      >
                        <div className={`theme-visual visual-${theme.id}`}>
                          <div className='mini-topline'><span /><span /></div>
                          <div className='mini-lines'><span /><span /><span /></div>
                        </div>
                        <div className='theme-option-footer'>
                          <span className='theme-name'><Icon name={theme.icon} size={15} />{theme.label}</span>
                          <span className='theme-radio'>{selected && <Icon name='check' size={12} />}</span>
                        </div>
                        <span className='theme-caption'>{theme.caption}</span>
                      </button>
                    );
                  })}
                </div>
              </div>

              <div className='section-divider' />

              <div className='form-section editor-section'>
                <div className='form-block-heading section-heading-row'>
                  <div>
                    <span className='section-label'>Editor</span>
                    <h3>Writing defaults</h3>
                    <p>Keep your favorite tools close at hand.</p>
                  </div>
                  <span className='shortcut-chip'><Icon name='bolt' size={14} /> Quick setup</span>
                </div>

                <div className='setting-row'>
                  <div className='setting-leading'>
                    <span className='setting-row-icon'><Icon name='cloud' size={16} /></span>
                    <div className='setting-copy'>
                      <strong>Auto-save notes</strong>
                      <p>Save edits as you work, every few seconds.</p>
                    </div>
                  </div>
                  <Toggle checked={autoSave} onChange={() => setAutoSave((value) => !value)} />
                </div>

                <div className='setting-row'>
                  <div className='setting-leading'>
                    <span className='setting-row-icon'><Icon name='eye' size={16} /></span>
                    <div className='setting-copy'>
                      <strong>Live markdown preview</strong>
                      <p>See formatting while you write.</p>
                    </div>
                  </div>
                  <Toggle checked={livePreview} onChange={() => setLivePreview((value) => !value)} />
                </div>

                <div className='setting-row'>
                  <div className='setting-leading'>
                    <span className='setting-row-icon'><Icon name='check' size={16} /></span>
                    <div className='setting-copy'>
                      <strong>Check spelling as you type</strong>
                      <p>Underline words that may need a second look.</p>
                    </div>
                  </div>
                  <Toggle checked={spellcheck} onChange={() => setSpellcheck((value) => !value)} />
                </div>

                <div className='setting-row'>
                  <div className='setting-leading'>
                    <span className='setting-row-icon'><Icon name='link' size={16} /></span>
                    <div className='setting-copy'>
                      <strong>Show backlinks in editor</strong>
                      <p>Keep connected notes visible as you write.</p>
                    </div>
                  </div>
                  <Toggle checked={backlinks} onChange={() => setBacklinks((value) => !value)} />
                </div>

                <div className='select-grid'>
                  <label className='select-field'>
                    <span>Typeface</span>
                    <div className='select-wrap'>
                      <select value={fontFamily} onChange={(event) => setFontFamily(event.target.value)}>
                        <option>Inter</option>
                        <option>System Sans</option>
                        <option>Source Serif</option>
                        <option>Mono Space</option>
                      </select>
                      <Icon name='chevron' size={15} />
                    </div>
                  </label>
                  <label className='select-field'>
                    <span>Note width</span>
                    <div className='select-wrap'>
                      <select value={noteWidth} onChange={(event) => setNoteWidth(event.target.value)}>
                        <option>Compact</option>
                        <option>Comfortable</option>
                        <option>Wide</option>
                      </select>
                      <Icon name='chevron' size={15} />
                    </div>
                  </label>
                </div>
              </div>

              <div className='settings-footer'>
                <div className='footer-sync'><span className='footer-sync-icon'><Icon name='cloud' size={15} /></span> Synced across your devices</div>
                <button type='button' className='save-button' onClick={handleSave}>
                  <Icon name='check' size={16} />
                  Save changes
                </button>
              </div>
            </section>
          </div>
        </div>
      </main>
    </div>
  );
}

export default App;

