:root {
  --ink: #28233f;
  --muted: #77718d;
  --quiet: #9b95ac;
  --border: #e8e4f0;
  --panel: #ffffff;
  --page: #f7f6fb;
  --purple: #6756c6;
  --purple-dark: #51409f;
  --sidebar: #292345;
  --sidebar-soft: #3b335d;
  --coral: #f58a7c;
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  min-height: 100%;
  margin: 0;
}

body {
  background: var(--page);
  color: var(--ink);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  -webkit-font-smoothing: antialiased;
}

button,
select {
  font: inherit;
}

button {
  border: 0;
  cursor: pointer;
}

button:focus-visible,
select:focus-visible {
  outline: 3px solid rgba(103, 86, 198, 0.28);
  outline-offset: 2px;
}

.app-shell {
  display: flex;
  min-height: 100vh;
  background: var(--page);
}

.workspace-sidebar {
  position: sticky;
  top: 0;
  display: flex;
  flex: 0 0 246px;
  flex-direction: column;
  height: 100vh;
  padding: 25px 16px 18px;
  overflow: hidden;
  color: #f8f6ff;
  background: linear-gradient(180deg, #2c254a 0%, #211d3a 100%);
}

.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 3px 11px 31px;
}

.brand-mark {
  display: grid;
  width: 31px;
  height: 31px;
  place-items: center;
  color: #fff;
  font-size: 20px;
  font-weight: 800;
  letter-spacing: -0.08em;
  background: linear-gradient(145deg, #ff9f91 0%, #dd6daf 100%);
  border-radius: 10px;
  box-shadow: 0 7px 18px rgba(14, 9, 37, 0.25);
}

.brand-name {
  color: #fff;
  font-size: 19px;
  font-weight: 700;
  letter-spacing: -0.04em;
}

.brand-name span {
  color: #f58a7c;
}

.new-note-button {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  min-height: 44px;
  padding: 0 12px;
  color: #fff;
  font-size: 13px;
  font-weight: 700;
  text-align: left;
  background: linear-gradient(120deg, #ed827c, #d66ea9);
  border-radius: 11px;
  box-shadow: 0 10px 22px rgba(17, 12, 39, 0.22);
  transition: transform 160ms ease, box-shadow 160ms ease;
}

.new-note-button:hover {
  transform: translateY(-1px);
  box-shadow: 0 13px 25px rgba(17, 12, 39, 0.3);
}

.new-note-icon {
  display: grid;
  width: 22px;
  height: 22px;
  place-items: center;
  background: rgba(255, 255, 255, 0.18);
  border-radius: 7px;
}

.new-note-button kbd,
.topbar-search kbd {
  margin-left: auto;
  padding: 3px 6px;
  color: rgba(255, 255, 255, 0.65);
  font-size: 10px;
  font-weight: 700;
  line-height: 1;
  background: rgba(34, 23, 65, 0.28);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 5px;
}

.workspace-nav {
  margin-top: 30px;
}

.sidebar-label {
  padding: 0 11px 10px;
  color: #9289b4;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.workspace-link,
.sidebar-settings-link {
  display: flex;
  align-items: center;
  gap: 11px;
  width: 100%;
  min-height: 42px;
  padding: 0 11px;
  color: #b7afd0;
  font-size: 13px;
  text-align: left;
  background: transparent;
  border-radius: 9px;
  transition: color 160ms ease, background 160ms ease;
}

.workspace-link:hover,
.sidebar-settings-link:hover {
  color: #fff;
  background: rgba(255, 255, 255, 0.07);
}

.workspace-link.is-active,
.sidebar-settings-link.is-active {
  color: #fff;
  background: rgba(146, 126, 221, 0.2);
}

.workspace-link-icon {
  display: grid;
  flex: 0 0 20px;
  place-items: center;
  color: currentColor;
}

.workspace-link-label {
  flex: 1;
}

.nav-count {
  color: #9f96bb;
  font-size: 11px;
  font-weight: 700;
}

.sidebar-lower {
  margin-top: auto;
}

.sidebar-settings-link {
  margin-bottom: 16px;
  border-top: 1px solid rgba(255, 255, 255, 0.09);
  border-radius: 0 0 9px 9px;
}

.workspace-switcher {
