function Toggle({ checked, label, onChange }: { checked: boolean; label: string; onChange: (value: boolean) => void }) {
  return (
    <button
      className={`toggle ${checked ? 'is-on' : ''}`}
      type='button'
      role='switch'
      aria-checked={checked}
      aria-label={label}
      onClick={() => onChange(!checked)}
    >
      <span />
    </button>
  );
}

function SettingRow({ title, description, children }: { title: string; description: string; children: ReactNode }) {
  return (
    <div className='setting-row'>
      <div className='setting-copy'>
        <h3>{title}</h3>
        <p>{description}</p>
      </div>
      <div className='row-control'>{children}</div>
    </div>
  );
}

function ThemePicker({ theme, onChange }: { theme: Theme; onChange: (value: Theme) => void }) {
  const choices: Array<{ label: Theme; icon: IconName }> = [
    { label: 'Light', icon: 'sun' },
    { label: 'Dark', icon: 'moon' },
    { label: 'System', icon: 'monitor' },
  ];

  return (
    <div className='theme-picker' role='group' aria-label='Theme'>
      {choices.map((choice) => (
        <button
          className={`theme-choice ${theme === choice.label ? 'is-selected' : ''}`}
          key={choice.label}
          type='button'
          aria-pressed={theme === choice.label}
          onClick={() => onChange(choice.label)}
        >
          <Icon name={choice.icon} size={15} />
          <span>{choice.label}</span>
        </button>
      ))}
    </div>
  );
}

