      case 'globe':
        return <><circle cx='12' cy='12' r='8.5' /><path d='M3.8 12h16.4M12 3.5c2.1 2.3 3.2 5.1 3.2 8.5s-1.1 6.2-3.2 8.5c-2.1-2.3-3.2-5.1-3.2-8.5S9.9 5.8 12 3.5Z' /></>;
      case 'sparkle':
        return <><path d='m12 3 1.2 5.8L19 10l-5.8 1.2L12 17l-1.2-5.8L5 10l5.8-1.2L12 3Z' /><path d='m19 16 .5 2.5L22 19l-2.5.5L19 22l-.5-2.5L16 19l2.5-.5L19 16Z' /></>;
      case 'layout':
        return <><rect x='4' y='4' width='16' height='16' rx='2' /><path d='M4 9h16M10 9v11' /></>;
      case 'lock':
        return <><rect x='5' y='10' width='14' height='10' rx='2' /><path d='M8 10V7.5a4 4 0 0 1 8 0V10M12 14v2' /></>;
      case 'arrow-up-right':
        return <><path d='M7 17 17 7M8 7h9v9' /></>;
      default:
        return null;
    }
  })();

  return (
    <svg width={size} height={size} viewBox='0 0 24 24' fill='none' stroke='currentColor' strokeWidth={strokeWidth} strokeLinecap='round' strokeLinejoin='round' aria-hidden='true' focusable='false'>
      {icon}
    </svg>
  );
}

function SidebarItem({ icon, label, count, active }: { icon: IconName; label: string; count?: string; active?: boolean }) {
  return (
    <button className={`sidebar-item${active ? ' active' : ''}`} type='button'>
      <span className='sidebar-item-icon'><Icon name={icon} size={17} /></span>
      <span className='sidebar-item-label'>{label}</span>
      {count && <span className='item-count'>{count}</span>}
    </button>
  );
}

function ToggleControl({ checked, onToggle, label }: { checked: boolean; onToggle: () => void; label: string }) {
  return (
    <button className={`toggle-control${checked ? ' is-on' : ''}`} type='button' role='switch' aria-checked={checked} aria-label={label} onClick={onToggle}>
      <span className='toggle-knob' />
    </button>
  );
}

function SectionHeader({ icon, overline, title, description }: { icon: IconName; overline: string; title: string; description: string }) {
  return (
    <div className='section-header'>
      <span className='section-header-icon'><Icon name={icon} size={18} /></span>
      <div className='section-heading-group'>
        <span className='section-overline'>{overline}</span>
        <h2 className='section-title'>{title}</h2>
        <p className='section-description'>{description}</p>
      </div>
    </div>
  );
}

type Theme = 'light' | 'dim' | 'dark';

const workspaceItems: Array<{ icon: IconName; label: string; count?: string }> = [
  { icon: 'note', label: 'All notes', count: '128' },
