  { icon: 'star', label: 'Favorites' },
  { icon: 'trash', label: 'Trash' },
  { icon: 'settings', label: 'Settings' },
];

const settingsItems: Array<{ id: string; icon: IconName; label: string; detail: string }> = [
  { id: 'general', icon: 'settings', label: 'General', detail: 'Workspace' },
  { id: 'editor', icon: 'type', label: 'Editor', detail: 'Writing tools' },
  { id: 'notifications', icon: 'bell', label: 'Notifications', detail: 'Stay in the loop' },
  { id: 'keyboard', icon: 'keyboard', label: 'Shortcuts', detail: 'Move faster' },
];

const themes: Array<{ key: Theme; label: string; description: string }> = [
  { key: 'light', label: 'Light', description: 'Bright and focused' },
  { key: 'dim', label: 'Dim', description: 'Soft on the eyes' },
  { key: 'dark', label: 'Dark', description: 'Low-light friendly' },
