              <SidebarItem key={item.label} icon={item.icon} label={item.label} count={item.count} active={item.label === 'Settings'} />
            ))}
          </nav>
        </div>

        <div className='sidebar-footer'>
          <div className='storage-card'>
            <div className='storage-head'>
              <span className='storage-label'>Storage</span>
              <strong>1.8 GB <span>of 5 GB</span></strong>
            </div>
            <div className='progress-track'><span className='progress-value' /></div>
            <span className='storage-footnote'>Notes are safely synced</span>
          </div>
          <button className='profile-card' type='button'>
            <span className='avatar'>AS</span>
            <span className='profile-copy'><strong>Avery Stone</strong><small>Personal workspace</small></span>
            <Icon name='chevron-right' size={15} />
          </button>
        </div>
      </aside>

      <main className='main-content'>
        <header className='topbar'>
          <div className='topbar-inner'>
            <div className='breadcrumbs'><span>Workspace</span><Icon name='chevron-right' size={14} /><strong>Settings</strong></div>
            <div className='topbar-tools'>
              <button className='search-trigger' type='button'><Icon name='search' size={16} /><span>Search notes</span><kbd>⌘ K</kbd></button>
              <button className='round-button' type='button' aria-label='Open help'><Icon name='help' size={18} /></button>
              <span className='online-dot' title='Synced' />
            </div>
          </div>
        </header>

        <div className='settings-page'>
          <div className='page-heading'>
            <div className='title-area'>
              <div className='eyebrow'><span className='eyebrow-mark' /> Workspace preferences</div>
              <h1>Settings</h1>
              <p>Shape your space for thinking, writing, and keeping track of what matters.</p>
            </div>
            <div className='heading-actions'>
              <div className='save-state'><span className={`save-status-dot${saved ? ' fresh' : ''}`} />{saved ? 'Changes saved' : 'Synced just now'}</div>
              <button className='save-button' type='button' onClick={saveChanges}>
                {saved ? 'Saved' : 'Save changes'}
                <Icon name={saved ? 'check' : 'arrow-up-right'} size={16} strokeWidth={2} />
              </button>
            </div>
          </div>

          <div className='settings-layout'>
            <aside className='settings-menu'>
              <div className='settings-menu-header'>
                <span className='menu-kicker'>Manage</span>
                <h2>Preferences</h2>
              </div>
              <div className='settings-menu-list'>
                {settingsItems.map((item) => (
                  <button className={`settings-menu-button${activeSection === item.label ? ' active' : ''}`} type='button' key={item.id} onClick={() => jumpTo(item.id, item.label)} aria-current={activeSection === item.label ? 'page' : undefined}>
                    <span className='settings-menu-icon'><Icon name={item.icon} size={17} /></span>
                    <span className='settings-menu-copy'><strong>{item.label}</strong><small>{item.detail}</small></span>
                    {activeSection === item.label && <span className='menu-active-dot' />}
                  </button>
                ))}
              </div>
              <div className='menu-help'>
                <span className='menu-help-icon'><Icon name='sparkle' size={16} /></span>
                <span><strong>Need a hand?</strong><small>Visit the help center</small></span>
              </div>
            </aside>

            <div className='settings-sections'>
              <section className='setting-card' id='general'>
                <SectionHeader icon='settings' overline='Workspace' title='General' description='The basics that make this space yours.' />
                <div className='section-divider' />
                <div className='setting-list'>
                  <div className='setting-row'>
                    <div className='setting-copy'><strong>Workspace name</strong><span>A recognizable name for your notes.</span></div>
                    <label className='input-control'><input value={workspaceName} maxLength={32} onChange={(event) => setWorkspaceName(event.target.value)} aria-label='Workspace name' /><span>{workspaceName.length}/32</span></label>
                  </div>
                  <div className='setting-row'>
                    <div className='setting-copy'><strong>Default notebook</strong><span>New notes will start here.</span></div>
                    <label className='select-control'><select value={defaultNotebook} onChange={(event) => setDefaultNotebook(event.target.value)} aria-label='Default notebook'><option>Personal</option><option>Work</option><option>Ideas</option></select><Icon name='chevron-down' size={16} /></label>
