                    <label className='select-control'><select value={language} onChange={(event) => setLanguage(event.target.value)} aria-label='Language'><option>English (US)</option><option>English (UK)</option><option>French</option><option>Spanish</option></select><Icon name='chevron-down' size={16} /></label>
