              </section>

              <section className='setting-card' id='editor'>
                <SectionHeader icon='type' overline='Writing tools' title='Editor' description='Tune the page until writing feels effortless.' />
                <div className='section-divider' />
                <div className='subsection'>
                  <span className='subsection-label'>Interface theme</span>
                  <div className='theme-grid'>
                    {themes.map((option) => (
                      <button className={`theme-option ${option.key}${theme === option.key ? ' selected' : ''}`} type='button' key={option.key} onClick={() => setTheme(option.key)} aria-pressed={theme === option.key}>
                        <div className={`theme-preview ${option.key}`}>
                          <div className='preview-toolbar'><span /><span /><span /></div>
