                </div>
                <div className='subsection writing-subsection'>
                  <span className='subsection-label'>Writing tools</span>
                  <div className='toggle-list'>
                    <div className='toggle-row'><div className='toggle-main'><span className='toggle-symbol'><Icon name='sparkle' size={16} /></span><span className='toggle-copy'><strong>Auto-save notes</strong><small>Save each edit as you type.</small></span></div><ToggleControl checked={autoSave} onToggle={() => setAutoSave((value) => !value)} label='Toggle auto-save notes' /></div>
                    <div className='toggle-row'><div className='toggle-main'><span className='toggle-symbol'><Icon name='link' size={16} /></span><span className='toggle-copy'><strong>Smart links</strong><small>Turn URLs into tidy previews.</small></span></div><ToggleControl checked={smartLinks} onToggle={() => setSmartLinks((value) => !value)} label='Toggle smart links' /></div>
                    <div className='toggle-row'><div className='toggle-main'><span className='toggle-symbol'><Icon name='type' size={16} /></span><span className='toggle-copy'><strong>Spellcheck</strong><small>Underline possible spelling mistakes.</small></span></div><ToggleControl checked={spellcheck} onToggle={() => setSpellcheck((value) => !value)} label='Toggle spellcheck' /></div>
                  </div>
                </div>
              </section>

              <section className='setting-card' id='notifications'>
                <SectionHeader icon='bell' overline='Stay in the loop' title='Notifications' description='Choose what deserves a gentle nudge.' />
                <div className='section-divider' />
                <div className='notification-list'>
                  <div className='notification-row'><div className='notification-copy'><span className='notification-icon'><Icon name='note' size={16} /></span><span><strong>Weekly digest</strong><small>A calm Monday recap of your notes.</small></span></div><ToggleControl checked={weeklyDigest} onToggle={() => setWeeklyDigest((value) => !value)} label='Toggle weekly digest' /></div>
                  <div className='notification-row'><div className='notification-copy'><span className='notification-icon'><Icon name='inbox' size={16} /></span><span><strong>Mentions and shares</strong><small>Know when someone responds to your notes.</small></span></div><ToggleControl checked={mentionAlerts} onToggle={() => setMentionAlerts((value) => !value)} label='Toggle mention and share alerts' /></div>
                  <div className='notification-row'><div className='notification-copy'><span className='notification-icon'><Icon name='monitor' size={16} /></span><span><strong>Desktop notifications</strong><small>Show alerts while the app is open.</small></span></div><ToggleControl checked={desktopNotifications} onToggle={() => setDesktopNotifications((value) => !value)} label='Toggle desktop notifications' /></div>
                </div>
                <div className='notification-note'><Icon name='bell' size={15} /><span>Quiet hours are set from 10:00 PM to 8:00 AM.</span><button type='button'>Change</button></div>
              </section>

              <section className='setting-card compact-card' id='keyboard'>
                <SectionHeader icon='keyboard' overline='Move faster' title='Shortcuts' description='A few useful keys for your everyday flow.' />
                <div className='section-divider' />
                <div className='shortcut-grid'>
                  <div className='shortcut-item'><span>New note</span><kbd>⌘ N</kbd></div>
