              <div className='settings-footer'><div className='footer-tip'><span><Icon name='check' size={15} strokeWidth={2.2} /></span><span>Preferences sync across your devices</span></div><button className='save-button' type='button' onClick={saveChanges}>{saved ? 'Saved' : 'Save changes'}<Icon name={saved ? 'check' : 'arrow-up-right'} size={16} strokeWidth={2} /></button></div>
            </div>
          </div>
        </div>
      </main>
    </div>
  );
