  align-items: center;
  justify-content: space-between;
  max-width: 1300px;
  height: 100%;
  margin: 0 auto;
  padding: 0 44px;
}

.breadcrumbs,
.topbar-tools,
.search-trigger,
.heading-actions,
.save-state,
.settings-footer,
.footer-tip,
.notification-note {
  display: flex;
  align-items: center;
}

.breadcrumbs {
  gap: 9px;
  color: #9aa1b1;
  font-size: 12px;
}

.breadcrumbs svg {
  color: #c3c7d2;
}

.breadcrumbs strong {
  color: #555d71;
  font-weight: 700;
}

.topbar-tools {
  gap: 14px;
}

.search-trigger {
  gap: 9px;
  min-width: 190px;
  height: 35px;
  padding: 0 9px 0 11px;
  color: #99a0b2;
  text-align: left;
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 9px;
  box-shadow: 0 2px 4px rgba(35, 43, 69, .025);
}

.search-trigger span {
  flex: 1;
  font-size: 11px;
}

.search-trigger:hover {
  color: var(--muted-dark);
  border-color: #d9dbe6;
}

.round-button {
  display: grid;
  width: 35px;
  height: 35px;
  place-items: center;
  color: #7d8598;
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 50%;
}

.round-button:hover {
  color: var(--accent);
  border-color: #d9d8fb;
  background: #fbfbff;
}

.online-dot {
  width: 8px;
  height: 8px;
  margin-left: 1px;
  background: var(--green);
  border: 2px solid #dff4ec;
  border-radius: 50%;
  box-sizing: content-box;
}

.settings-page {
  max-width: 1300px;
  margin: 0 auto;
  padding: 43px 44px 68px;
}

.page-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 32px;
  margin-bottom: 36px;
}

.eyebrow {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 12px;
  color: var(--accent);
  font-size: 10px;
  font-weight: 800;
}

.eyebrow-mark {
  width: 7px;
  height: 7px;
  background: var(--coral);
  border-radius: 50%;
  box-shadow: 0 0 0 4px #fce9e3;
}

.title-area h1 {
  margin: 0;
  color: var(--ink);
  font-size: clamp(30px, 3.1vw, 39px);
  font-weight: 760;
  letter-spacing: -.045em;
  line-height: 1.08;
}

.title-area p {
  max-width: 510px;
  margin: 10px 0 0;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.65;
}

.heading-actions {
  gap: 19px;
  padding-bottom: 3px;
}

.save-state {
  gap: 8px;
  color: #8b92a3;
  font-size: 11px;
  font-weight: 600;
  white-space: nowrap;
}

.save-status-dot {
  width: 7px;
  height: 7px;
  background: #b9c1ce;
  border-radius: 50%;
  transition: background .2s ease, box-shadow .2s ease;
}

.save-status-dot.fresh {
  background: var(--green);
  box-shadow: 0 0 0 4px #e0f5ee;
}

.save-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  min-width: 137px;
  height: 41px;
  padding: 0 15px;
  color: #fff;
  font-size: 12px;
  font-weight: 750;
  background: var(--accent);
  border-radius: 10px;
  box-shadow: 0 8px 18px rgba(104, 98, 233, .2);
  transition: background .18s ease, box-shadow .18s ease, transform .18s ease;
}

.save-button:hover {
  background: var(--accent-dark);
  box-shadow: 0 11px 23px rgba(104, 98, 233, .28);
  transform: translateY(-1px);
}

.settings-layout {
  display: grid;
  grid-template-columns: 202px minmax(0, 1fr);
  align-items: start;
  gap: 36px;
}

.settings-menu {
  position: sticky;
  top: 25px;
  padding: 7px 0;
}

.settings-menu-header {
  padding: 0 12px 15px;
}

.menu-kicker {
  color: #a1a8b8;
  font-size: 10px;
  font-weight: 800;
}

.settings-menu-header h2 {
  margin: 6px 0 0;
  color: #374054;
  font-size: 15px;
  font-weight: 750;
  letter-spacing: -.02em;
}

.settings-menu-list {
  display: grid;
  gap: 4px;
}

.settings-menu-button {
  position: relative;
  display: flex;
  align-items: center;
  width: 100%;
  min-height: 56px;
  padding: 8px 10px;
  color: #8a92a3;
  text-align: left;
  background: transparent;
  border-radius: 11px;
  transition: color .18s ease, background .18s ease;
}

.settings-menu-button:hover {
  color: #565e73;
  background: rgba(255, 255, 255, .7);
}

.settings-menu-button.active {
  color: var(--accent);
  background: #fff;
  box-shadow: 0 6px 20px rgba(41, 48, 82, .055), 0 0 0 1px rgba(104, 98, 233, .07);
}

.settings-menu-icon {
  display: grid;
  flex: 0 0 32px;
  width: 32px;
  height: 32px;
  margin-right: 9px;
  place-items: center;
  color: #a2a9b8;
  background: #f0f1f6;
  border-radius: 9px;
}

.settings-menu-button.active .settings-menu-icon {
  color: var(--accent);
  background: var(--accent-soft);
}

.settings-menu-copy {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}

.settings-menu-copy strong {
  color: inherit;
  font-size: 11px;
  font-weight: 750;
}

.settings-menu-copy small {
  overflow: hidden;
  color: #a3a9b7;
  font-size: 10px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.settings-menu-button.active .settings-menu-copy small {
  color: #9995d7;
}

.menu-active-dot {
  width: 5px;
  height: 5px;
  margin-left: 5px;
  background: var(--accent);
  border-radius: 50%;
}

.menu-help {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  margin: 26px 8px 0;
  padding: 13px 11px;
  color: #858da1;
  background: #eeeff8;
  border: 1px solid #e4e5f1;
  border-radius: 12px;
}

.menu-help-icon {
  display: grid;
  flex: 0 0 25px;
  width: 25px;
  height: 25px;
  place-items: center;
  color: #8079e8;
  background: #e2e1ff;
  border-radius: 8px;
}

.menu-help > span:last-child {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}

.menu-help strong {
  color: #5c6377;
  font-size: 10px;
  font-weight: 750;
}

.menu-help small {
  color: #969cad;
  font-size: 9px;
  white-space: nowrap;
}

.settings-sections {
  display: grid;
  gap: 20px;
  min-width: 0;
}

.setting-card {
  padding: 25px 27px 23px;
  background: var(--surface);
  border: 1px solid rgba(227, 229, 238, .94);
  border-radius: 17px;
  box-shadow: 0 10px 28px rgba(31, 42, 73, .035);
  scroll-margin-top: 25px;
}

.section-header {
  display: flex;
  align-items: flex-start;
  gap: 13px;
}

.section-header-icon {
  display: grid;
  flex: 0 0 37px;
  width: 37px;
  height: 37px;
  place-items: center;
  color: var(--accent);
  background: var(--accent-soft);
  border-radius: 11px;
}

.section-heading-group {
  min-width: 0;
}

.section-overline {
  color: #a1a7b7;
  font-size: 9px;
  font-weight: 800;
}

.section-title {
  margin: 4px 0 4px;
  color: #2c3447;
  font-size: 18px;
  font-weight: 760;
  letter-spacing: -.03em;
}

.section-description {
  margin: 0;
  color: #9299a9;
  font-size: 11px;
  line-height: 1.5;
}

.section-divider {
  height: 1px;
  margin: 22px 0 3px;
  background: var(--line);
}

.setting-list {
  display: grid;
}

.setting-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(220px, 38%);
  align-items: center;
  gap: 22px;
  min-height: 72px;
  padding: 14px 0;
  border-bottom: 1px solid #f0f1f5;
}

.setting-row:last-child {
  border-bottom: 0;
}

.setting-copy,
.toggle-copy,
.notification-copy > span:last-child {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.setting-copy strong,
.toggle-copy strong,
.notification-copy strong {
  color: #3e4658;
  font-size: 12px;
  font-weight: 720;
}

.setting-copy span,
.toggle-copy small,
.notification-copy small {
  color: #9aa1b0;
  font-size: 10px;
  line-height: 1.45;
}

.input-control,
.select-control {
  position: relative;
  display: flex;
  align-items: center;
  width: 100%;
  min-height: 38px;
  color: #5c6477;
  background: #fbfbfd;
  border: 1px solid #e5e6ee;
  border-radius: 9px;
  transition: border-color .18s ease, box-shadow .18s ease, background .18s ease;
}

.input-control:focus-within,
.select-control:focus-within {
  background: #fff;
  border-color: #b8b4f5;
  box-shadow: 0 0 0 3px rgba(104, 98, 233, .09);
}

.input-control input,
.select-control select {
  width: 100%;
  min-width: 0;
  color: #4c5569;
  font-size: 11px;
  background: transparent;
  border: 0;
  outline: 0;
}

.input-control input {
  height: 36px;
  padding: 0 46px 0 12px;
}

.input-control > span {
  position: absolute;
  right: 11px;
  color: #b1b6c1;
  font-size: 9px;
}

.select-control {
  padding-right: 31px;
}

.select-control select {
  height: 36px;
  padding: 0 10px 0 12px;
  cursor: pointer;
  appearance: none;
}

.select-control > svg {
  position: absolute;
  right: 11px;
  color: #9da4b4;
  pointer-events: none;
}

.setting-row-toggle {
  min-height: 65px;
}

.card-note {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  margin-top: 12px;
  padding: 11px 12px;
  color: #8d94a7;
  font-size: 10px;
  line-height: 1.5;
  background: #fafaff;
  border: 1px solid #ececff;
  border-radius: 9px;
}

.card-note-icon {
  display: grid;
  flex: 0 0 22px;
  width: 22px;
  height: 22px;
  margin-top: -1px;
  place-items: center;
  color: #6f69df;
  background: #edecff;
  border-radius: 7px;
}

.subsection {
  padding-top: 19px;
}

.writing-subsection {
  padding-top: 24px;
}

.subsection-label {
  display: block;
  margin-bottom: 12px;
  color: #a0a6b5;
  font-size: 9px;
  font-weight: 800;
}

.theme-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 11px;
}

.theme-option {
  position: relative;
  padding: 8px 8px 11px;
  text-align: left;
  background: #fff;
  border: 1px solid #e7e8ef;
  border-radius: 11px;
  transition: border-color .18s ease, box-shadow .18s ease, transform .18s ease;
}

.theme-option:hover {
  border-color: #c8c6f7;
  box-shadow: 0 7px 17px rgba(59, 65, 111, .08);
  transform: translateY(-1px);
}

.theme-option.selected {
  border-color: #9892ef;
  box-shadow: 0 0 0 3px rgba(104, 98, 233, .09);
}

.theme-preview {
  height: 70px;
  padding: 8px;
  overflow: hidden;
  border-radius: 7px;
}

.theme-preview.light {
  background: #f9f9fc;
  border: 1px solid #ececf1;
}

.theme-preview.dim {
  background: #e8eaf0;
  border: 1px solid #dfe1e9;
}

.theme-preview.dark {
  background: #24293a;
  border: 1px solid #343b50;
}

.preview-toolbar {
  display: flex;
  gap: 3px;
  height: 8px;
}

.preview-toolbar span {
  width: 4px;
  height: 4px;
  background: #d0d2dc;
  border-radius: 50%;
}

.theme-preview.dark .preview-toolbar span {
  background: #5d667d;
}

.preview-content {
  display: flex;
  gap: 8px;
  margin-top: 5px;
}

.preview-rail {
  display: grid;
  flex: 0 0 20px;
  gap: 4px;
  align-content: start;
}

.preview-rail span {
  display: block;
  width: 100%;
  height: 3px;
  background: #d6d8e1;
  border-radius: 3px;
}

.preview-rail span:first-child {
  width: 14px;
  background: #aaa5f0;
}

.theme-preview.dark .preview-rail span {
  background: #4f576b;
}

.theme-preview.dark .preview-rail span:first-child {
  background: #7c75e5;
}

.preview-sheet {
  display: grid;
  flex: 1;
  gap: 5px;
  padding-top: 1px;
}

.preview-sheet i,
.preview-sheet b,
.preview-sheet em {
  display: block;
  height: 4px;
  background: #c9cbd5;
  border-radius: 3px;
}

.preview-sheet i {
  width: 72%;
  height: 7px;
  background: #9da0b1;
}

.preview-sheet b {
  width: 94%;
}

.preview-sheet em {
  width: 57%;
}

.theme-preview.dark .preview-sheet i {
  background: #a6aec2;
}

.theme-preview.dark .preview-sheet b,
.theme-preview.dark .preview-sheet em {
  background: #626b80;
}

.theme-option-meta {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin: 10px 3px 0;
  padding-right: 21px;
}

.theme-label {
  color: #50586b;
  font-size: 11px;
  font-weight: 750;
}

.theme-option-meta small {
  color: #9da3b0;
  font-size: 9px;
}

.theme-radio {
  position: absolute;
  right: 10px;
  bottom: 12px;
  display: grid;
  width: 15px;
  height: 15px;
  place-items: center;
  color: #fff;
  border: 1px solid #d6d8e2;
  border-radius: 50%;
}

.theme-option.selected .theme-radio {
  background: var(--accent);
  border-color: var(--accent);
}

.toggle-list,
.notification-list {
  display: grid;
  border: 1px solid #ececf2;
  border-radius: 11px;
}

.toggle-row,
.notification-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  min-height: 59px;
  padding: 9px 13px;
  border-bottom: 1px solid #f0f1f5;
}

.toggle-row:last-child,
.notification-row:last-child {
  border-bottom: 0;
}

.toggle-main,
.notification-copy {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.toggle-symbol,
.notification-icon {
  display: grid;
  flex: 0 0 29px;
  width: 29px;
  height: 29px;
  place-items: center;
  color: #817bea;
  background: #f1f0ff;
  border-radius: 8px;
}

.notification-icon {
  color: #7e9cc6;
  background: #eef5fc;
}

.toggle-control {
  position: relative;
  flex: 0 0 37px;
  width: 37px;
  height: 21px;
  padding: 0;
  background: #d9dce5;
  border-radius: 999px;
  transition: background .2s ease, box-shadow .2s ease;
}

.toggle-control.is-on {
  background: var(--accent);
  box-shadow: 0 3px 8px rgba(104, 98, 233, .25);
}

.toggle-knob {
  position: absolute;
  top: 3px;
  left: 3px;
  width: 15px;
  height: 15px;
  background: #fff;
  border-radius: 50%;
  box-shadow: 0 1px 3px rgba(26, 32, 51, .2);
  transition: transform .2s ease;
}

.toggle-control.is-on .toggle-knob {
  transform: translateX(16px);
}

.notification-note {
  gap: 7px;
  margin-top: 13px;
  color: #9ba1b0;
  font-size: 10px;
}

.notification-note svg {
  color: #a5a9b8;
}

.notification-note button {
  margin-left: auto;
  padding: 0;
  color: var(--accent);
  font-size: 10px;
  font-weight: 700;
  background: transparent;
}

.notification-note button:hover {
  color: var(--accent-dark);
  text-decoration: underline;
}

.compact-card {
  padding-bottom: 25px;
}

.shortcut-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 9px;
}

.shortcut-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  min-height: 43px;
  padding: 0 12px;
  color: #656d7e;
  font-size: 10px;
  background: #fafafd;
  border: 1px solid #ececf2;
  border-radius: 8px;
}

.shortcut-item kbd {
  padding: 4px 7px;
  color: #737b8c;
  font-family: inherit;
  font-size: 9px;
  font-weight: 750;
  white-space: nowrap;
  background: #fff;
  border: 1px solid #e2e3eb;
  border-bottom-width: 2px;
  border-radius: 5px;
}

.settings-footer {
  justify-content: space-between;
  gap: 20px;
  min-height: 50px;
  padding: 7px 4px 0;
}

.footer-tip {
  gap: 8px;
  color: #9ba2b1;
  font-size: 10px;
}

.footer-tip > span:first-child {
  display: grid;
  width: 22px;
  height: 22px;
  place-items: center;
  color: var(--green);
  background: #e4f6ef;
  border-radius: 7px;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@media (max-width: 1040px) {
  .topbar-inner,
  .settings-page {
    padding-right: 28px;
    padding-left: 28px;
  }

  .settings-layout {
    grid-template-columns: 184px minmax(0, 1fr);
    gap: 25px;
  }

  .setting-card {
    padding-right: 22px;
    padding-left: 22px;
  }

  .setting-row {
    grid-template-columns: minmax(0, 1fr) minmax(185px, 40%);
  }
}

@media (max-width: 840px) {
  .sidebar {
    flex-basis: 220px;
    width: 220px;
  }

  .settings-layout {
    grid-template-columns: 1fr;
  }

  .settings-menu {
    position: static;
    display: flex;
    align-items: center;
    gap: 16px;
    padding: 0;
    overflow: hidden;
  }

  .settings-menu-header {
    flex: 0 0 125px;
    padding: 0;
  }

  .settings-menu-list {
    display: flex;
    flex: 1;
    gap: 6px;
    min-width: 0;
    padding: 3px 3px 8px 0;
    overflow-x: auto;
  }

  .settings-menu-button {
    flex: 0 0 145px;
    min-height: 52px;
  }

  .menu-help {
    display: none;
  }
}

@media (max-width: 680px) {
  .sidebar {
    display: none;
  }

  .topbar {
    height: 64px;
  }

  .topbar-inner,
  .settings-page {
    padding-right: 18px;
    padding-left: 18px;
  }

  .topbar-tools {
    gap: 8px;
  }

  .search-trigger {
    min-width: 36px;
    width: 36px;
    padding: 0;
    justify-content: center;
  }

  .search-trigger span,
  .search-trigger kbd,
  .online-dot {
    display: none;
  }

  .settings-page {
    padding-top: 31px;
  }

  .page-heading {
    align-items: flex-start;
    flex-direction: column;
    gap: 21px;
    margin-bottom: 27px;
  }

  .heading-actions {
    width: 100%;
    justify-content: space-between;
  }

  .setting-card {
    padding: 22px 17px 20px;
    border-radius: 15px;
  }

  .setting-row {
    grid-template-columns: 1fr;
    gap: 13px;
    padding: 15px 0;
  }

  .setting-row-toggle {
    grid-template-columns: minmax(0, 1fr) auto;
  }

  .theme-grid {
    grid-template-columns: repeat(3, minmax(115px, 1fr));
    overflow-x: auto;
    padding-bottom: 3px;
  }

  .theme-option {
    min-width: 115px;
  }
}

@media (max-width: 470px) {
  .breadcrumbs span,
  .breadcrumbs svg {
    display: none;
  }

  .breadcrumbs strong::before {
    margin-right: 5px;
    color: #b3b8c6;
    content: '‹';
    font-size: 17px;
    font-weight: 400;
    vertical-align: -1px;
  }

  .heading-actions {
    align-items: flex-start;
    flex-direction: column;
    gap: 13px;
  }

  .heading-actions .save-button {
    width: 100%;
  }

  .settings-menu {
    display: block;
  }

  .settings-menu-header {
    margin-bottom: 11px;
  }

  .settings-menu-list {
    margin-right: -18px;
    padding-right: 18px;
  }

  .theme-grid {
    grid-template-columns: 1fr;
    overflow: visible;
  }

  .theme-option {
    display: grid;
    grid-template-columns: 108px 1fr auto;
    align-items: center;
    gap: 10px;
    min-width: 0;
    padding: 8px;
  }

  .theme-preview {
    height: 52px;
  }

  .theme-option-meta {
    margin: 0;
  }

  .theme-radio {
