                <button key={item.id} type='button' className={`nav-item ${activeSection === item.id ? 'is-active' : ''}`} onClick={() => setActiveSection(item.id)}>
                  <span className='nav-icon'><Icon name={item.icon} size={17} /></span>
                  <span className='nav-text'>{item.label}</span>
                </button>
              ))}
            </nav>
          </div>

          <div className='sidebar-lower'>
            <button className='nav-item sidebar-help' type='button'><span className='nav-icon'><Icon name='help' size={17} /></span><span className='nav-text'>Help center</span></button>
            <div className='sidebar-divider' />
            <button className='profile-switcher' type='button'>
              <span className='profile-avatar'>M</span>
              <span className='account-copy'><strong>Maya Chen</strong><small>Personal account</small></span>
              <Icon name='more' size={16} />
            </button>
          </div>
        </aside>

        <section className='settings-content'>
          <header className='topbar'>
            <div className='breadcrumbs'><span className='crumb-muted'>Morrow Notes</span><Icon name='chevronRight' size={14} /><span>Settings</span></div>
            <div className='topbar-actions'>
              <div className='sync-indicator'><span className='sync-dot' />All changes saved</div>
              <button className='search-trigger' type='button'><Icon name='search' size={15} /><span>Search</span><kbd>⌘ K</kbd></button>
              <button className='icon-button close-button' type='button' aria-label='Close settings'><Icon name='close' size={18} /></button>
            </div>
          </header>

          <div className='content-scroll'>
            <div className='page-body'>
              <div className='page-heading'>
                <div>
                  <div className='eyebrow'><span className='eyebrow-dot' />{activeMeta.eyebrow}</div>
                  <h1>{activeMeta.title}</h1>
                  <p>{activeMeta.description}</p>
                </div>
                <div className='heading-meta'><span className='collaborator-stack'><i>M</i><i>+</i></span><span>Private workspace</span></div>
              </div>

              {activeSection === 'general' && <GeneralSection toggles={toggles} onToggle={onToggle} />}
              {activeSection === 'appearance' && <AppearanceSection theme={theme} onThemeChange={setTheme} density={density} onDensityChange={setDensity} />}
              {activeSection === 'editor' && <EditorSection toggles={toggles} onToggle={onToggle} editorWidth={editorWidth} onWidthChange={setEditorWidth} />}
              {activeSection === 'shortcuts' && <ShortcutsSection />}
              {activeSection === 'account' && <AccountSection />}

              <div className='page-footnote'><Icon name='lock' size={14} />Preferences sync automatically across your devices.</div>
            </div>
          </div>
        </section>
      </div>
    </main>
  );
}

