  left: 12px;
  right: auto;
}

.input-shell input,
.select-shell select {
  width: 100%;
  height: 43px;
  padding: 0 37px 0 37px;
  color: var(--ink-strong);
  font-size: 12px;
  background: var(--input);
  border: 1px solid var(--line);
  border-radius: 11px;
  transition: border-color 160ms ease, box-shadow 160ms ease;
}

.select-shell select {
  padding-left: 13px;
  appearance: none;
}

.input-shell input:hover,
.select-shell select:hover {
  border-color: var(--muted-2);
}

.input-shell input:focus,
.select-shell select:focus {
  outline: 0;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 14%, transparent);
}

.input-shell input::placeholder {
  color: var(--muted-2);
}

.quick-card {
  display: flex;
  flex-direction: column;
}

.capture-surface {
  padding: 13px;
  background: var(--surface-alt);
  border: 1px solid var(--line);
  border-radius: 14px;
}

.capture-main,
.capture-shortcut,
.quick-row {
  display: flex;
  align-items: center;
}

.capture-main {
  gap: 10px;
}

.capture-icon {
  display: grid;
  place-items: center;
  width: 31px;
  height: 31px;
  flex: 0 0 auto;
  color: var(--accent-strong);
  background: var(--surface);
  border-radius: 9px;
}

.capture-copy {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.capture-copy strong {
  color: var(--ink-strong);
  font-size: 12px;
}

.capture-copy span,
.key-label {
  color: var(--muted-2);
  font-size: 10px;
}

.capture-main > svg {
  margin-left: auto;
  color: var(--muted-2);
}

.capture-shortcut {
  justify-content: space-between;
  margin-top: 13px;
  padding-top: 12px;
  border-top: 1px solid var(--line);
}

.key-combo {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

kbd {
  display: inline-grid;
  place-items: center;
  min-width: 23px;
  height: 22px;
  padding: 0 6px;
  color: var(--muted);
  font-family: inherit;
  font-size: 10px;
  font-weight: 650;
  background: var(--surface);
  border: 1px solid var(--line);
  border-bottom-width: 2px;
  border-radius: 6px;
}

.search-trigger kbd {
  min-width: 33px;
  height: 20px;
  padding: 0 5px;
  font-size: 9px;
  border-bottom-width: 1px;
}

.quick-row {
  justify-content: space-between;
  margin-top: 16px;
  color: var(--muted);
  font-size: 11px;
}

.select-like {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--ink-strong);
  font-size: 11px;
  font-weight: 650;
  background: transparent;
}

.select-like svg {
  color: var(--muted-2);
}

.quick-card .text-button {
  align-self: flex-start;
  margin-top: 17px;
}

.writing-card {
  grid-column: 1 / -1;
}

.writing-header {
  align-items: flex-start;
  margin-bottom: 9px;
}

.status-count,
.preview-status,
.account-badge {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  white-space: nowrap;
}

.status-count {
  padding: 6px 9px;
  color: var(--muted);
  font-size: 10px;
  background: var(--surface-alt);
  border-radius: 999px;
}

.setting-list {
  border-top: 1px solid var(--line);
}

.setting-row {
  display: flex;
  align-items: center;
  gap: 12px;
  min-height: 65px;
  padding: 11px 0;
}

.setting-row + .setting-row {
  border-top: 1px solid var(--line);
}

.setting-icon,
.security-row-icon {
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  color: var(--muted);
  background: var(--surface-alt);
  border-radius: 9px;
}

.setting-icon {
  width: 31px;
  height: 31px;
}

.setting-copy {
  min-width: 0;
  flex: 1;
}

.setting-title {
  color: var(--ink-strong);
  font-size: 12px;
  font-weight: 650;
}

.setting-description {
  margin-top: 4px;
  overflow: hidden;
  color: var(--muted);
  font-size: 10px;
  line-height: 1.4;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.setting-control {
  flex: 0 0 auto;
  margin-left: 12px;
}

.toggle {
  position: relative;
  width: 40px;
  height: 23px;
  padding: 3px;
  background: var(--line);
  border-radius: 999px;
  transition: background 180ms ease;
}

.toggle.is-on {
  background: var(--accent);
}

.toggle-thumb {
  display: block;
  width: 17px;
  height: 17px;
  background: #fffdfa;
  border-radius: 50%;
  box-shadow: 0 2px 4px rgba(44, 34, 27, 0.2);
  transition: transform 180ms ease;
}

.toggle.is-on .toggle-thumb {
  transform: translateX(17px);
}

.sync-card {
  display: flex;
  align-items: center;
  gap: 13px;
  padding: 17px 21px;
}

.sync-badge,
.tip-graphic {
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  color: var(--accent-strong);
  background: var(--accent-pale);
  border-radius: 12px;
}

.sync-badge {
  width: 40px;
  height: 40px;
}

.sync-copy {
  min-width: 0;
  flex: 1;
}

.sync-copy .card-kicker {
  margin-bottom: 5px;
}

.sync-copy .card-description {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.secondary-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 34px;
  padding: 0 12px;
  color: var(--ink);
  font-size: 10px;
  font-weight: 650;
  white-space: nowrap;
  background: var(--surface-soft);
  border: 1px solid var(--line);
  border-radius: 9px;
  transition: border-color 160ms ease, background 160ms ease, transform 160ms ease;
}

.secondary-button:hover {
  background: var(--surface-alt);
  border-color: var(--muted-2);
  transform: translateY(-1px);
}

.appearance-grid,
.editor-grid,
.shortcuts-grid,
.account-grid {
  align-items: start;
}

.theme-card {
  grid-column: 1 / -1;
}

.theme-options {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.theme-option {
  position: relative;
  min-width: 0;
  padding: 5px;
  color: var(--muted);
  text-align: left;
  background: transparent;
  border: 1px solid transparent;
  border-radius: 13px;
  transition: border-color 160ms ease, background 160ms ease;
}

.theme-option:hover {
  background: var(--surface-soft);
  border-color: var(--line);
}

.theme-option.is-selected {
  background: var(--accent-pale);
  border-color: color-mix(in srgb, var(--accent) 54%, var(--line));
}

.theme-swatch {
  position: relative;
  display: block;
  height: 76px;
  padding: 10px;
  overflow: hidden;
  border-radius: 9px;
}

.theme-swatch-light {
  color: #9b7a67;
  background: #f3eee8;
}

.theme-swatch-dim {
  color: #c99b7e;
  background: #3a3531;
}

.theme-swatch-system {
  color: #a77d66;
  background: linear-gradient(135deg, #f3eee8 0 50%, #3a3531 50% 100%);
}

.swatch-top {
  display: flex;
  gap: 3px;
}

.swatch-top i {
  display: block;
  width: 4px;
  height: 4px;
  background: currentColor;
  border-radius: 50%;
  opacity: 0.65;
}

.swatch-body {
  position: absolute;
  inset: 27px 12px 10px;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.swatch-body i {
  display: block;
  height: 4px;
  background: currentColor;
  border-radius: 4px;
  opacity: 0.42;
}

.swatch-body i:nth-child(1) {
  width: 67%;
  height: 7px;
  opacity: 0.78;
}

.swatch-body i:nth-child(2) {
  width: 88%;
}

.swatch-body i:nth-child(3) {
  width: 53%;
}

.theme-option-copy {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 10px 6px 5px;
}

.theme-option-title {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: var(--ink-strong);
  font-size: 11px;
  font-weight: 700;
}

.theme-option-description {
  overflow: hidden;
  color: var(--muted);
  font-size: 10px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.selection-check {
  position: absolute;
  top: 12px;
  right: 12px;
  display: grid;
  place-items: center;
  width: 19px;
  height: 19px;
  color: transparent;
  background: transparent;
  border-radius: 50%;
}

.theme-option.is-selected .selection-check {
  color: #fff;
  background: var(--accent);
}

.appearance-preview {
  min-height: 145px;
  margin-top: 21px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 13px;
}

.preview-light,
.preview-system {
  color: #514941;
  background: #f5f0eb;
}

.preview-dim {
  color: #ede4dc;
  background: #302c29;
}

.preview-toolbar {
  height: 31px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 12px;
  background: color-mix(in srgb, currentColor 4%, transparent);
  border-bottom: 1px solid color-mix(in srgb, currentColor 12%, transparent);
}

.preview-toolbar-left {
  display: flex;
  gap: 3px;
}

.preview-toolbar-left i {
  width: 4px;
  height: 4px;
  background: currentColor;
  border-radius: 50%;
  opacity: 0.35;
}

.preview-pill {
  padding: 4px 8px;
  color: currentColor;
  font-size: 8px;
  font-weight: 650;
  background: color-mix(in srgb, currentColor 8%, transparent);
  border-radius: 5px;
  opacity: 0.75;
}

.preview-content {
  display: flex;
  gap: 18px;
  padding: 17px 20px 21px;
}

.preview-sidebar {
  width: 70px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding-top: 3px;
}

.preview-sidebar span {
  display: block;
  width: 100%;
  height: 4px;
  background: currentColor;
  border-radius: 3px;
  opacity: 0.16;
}

.preview-sidebar span:first-child {
  width: 65%;
  opacity: 0.38;
}

.preview-note {
  max-width: 330px;
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 8px;
  padding: 5px 0;
}

.preview-note-title {
  width: 46%;
  margin-bottom: 4px;
  color: currentColor;
  font-size: 15px;
  font-weight: 700;
  letter-spacing: -0.04em;
}

.preview-note-line {
  width: 93%;
  height: 4px;
  background: currentColor;
  border-radius: 4px;
  opacity: 0.17;
}

.preview-note-line.short {
  width: 62%;
}

.preview-note-highlight {
  width: fit-content;
  margin: 3px 0;
  padding: 6px 8px;
  color: var(--accent-strong);
  font-size: 9px;
  font-weight: 600;
  background: color-mix(in srgb, var(--accent) 15%, transparent);
  border-radius: 5px;
}

.compact-card {
  min-height: 100%;
}

.option-block + .option-block {
  margin-top: 25px;
  padding-top: 22px;
  border-top: 1px solid var(--line);
}

.option-label-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 9px;
}

.option-label-row .option-label {
  margin-bottom: 0;
}

.option-value {
  color: var(--muted-2);
  font-size: 10px;
}

.segmented-control {
  display: flex;
  gap: 3px;
  padding: 3px;
  background: var(--surface-alt);
  border: 1px solid var(--line);
  border-radius: 10px;
}

.segment-button {
  min-width: 0;
  flex: 1;
  height: 30px;
  padding: 0 10px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 650;
  text-transform: capitalize;
  background: transparent;
  border-radius: 7px;
  transition: color 160ms ease, background 160ms ease, box-shadow 160ms ease;
}

.segment-button:hover {
  color: var(--ink);
}

.segment-button.is-active {
  color: var(--ink-strong);
  background: var(--surface);
  box-shadow: 0 2px 5px rgba(70, 53, 42, 0.08);
}

.color-grid {
  display: flex;
  gap: 11px;
  padding: 3px 2px;
}

.color-dot {
  position: relative;
  width: 22px;
  height: 22px;
  padding: 0;
  border: 0;
  border-radius: 50%;
}

.color-dot.is-selected::after {
  position: absolute;
  inset: -4px;
  content: '';
  border: 1px solid currentColor;
  border-radius: 50%;
}

.color-dot-clay { color: #ad684a; background: #ad684a; }
.color-dot-ink { color: #4f5557; background: #4f5557; }
.color-dot-moss { color: #788466; background: #788466; }
.color-dot-sky { color: #7899a4; background: #7899a4; }
.color-dot-plum { color: #8b7181; background: #8b7181; }

.editor-controls,
.editor-preview-card {
  min-height: 415px;
}

.control-section {
  margin-bottom: 22px;
}

.control-section .segmented-control {
  margin-top: 9px;
}

.compact-list .setting-row {
  min-height: 61px;
}

.full-button {
  width: 100%;
  margin-top: 21px;
}

.preview-status {
  padding: 5px 8px;
  color: var(--muted);
  font-size: 10px;
  background: var(--surface-alt);
  border-radius: 999px;
}

.editor-preview {
  min-height: 288px;
  padding: 11px;
  background: var(--surface-alt);
  border: 1px solid var(--line);
  border-radius: 13px;
}

.editor-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 5px 10px;
  color: var(--muted);
  font-size: 9px;
}

.editor-paper {
  min-height: 240px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin: 0 auto;
  padding: 28px 27px;
  color: #4c4540;
  background: #fffdfa;
  border: 1px solid rgba(90, 69, 54, 0.08);
  border-radius: 8px;
  box-shadow: 0 5px 14px rgba(61, 45, 36, 0.07);
  transition: max-width 180ms ease;
}

.editor-preview-narrow .editor-paper {
  max-width: 244px;
}

.editor-preview-wide .editor-paper {
  max-width: 100%;
}

.editor-paper-title {
  margin-bottom: 7px;
  color: #302a27;
  font-family: Georgia, 'Times New Roman', serif;
  font-size: 19px;
  letter-spacing: -0.04em;
}

.editor-paper-line {
  width: 91%;
  height: 5px;
  background: #ddd3ca;
  border-radius: 5px;
}

.editor-paper-line.medium {
  width: 75%;
}

.editor-paper-line.short {
  width: 58%;
}

.editor-highlight {
  width: fit-content;
  margin: 5px 0 1px;
  padding: 7px 9px;
  color: #9b5b43;
  font-family: Georgia, 'Times New Roman', serif;
  font-size: 11px;
  background: #f7e8dd;
  border-radius: 5px;
}

.shortcuts-card {
  grid-column: 1 / -1;
}

.shortcut-list {
  border-top: 1px solid var(--line);
}

.shortcut-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  min-height: 58px;
  padding: 10px 0;
}

.shortcut-item + .shortcut-item {
  border-top: 1px solid var(--line);
}

.shortcut-name {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.shortcut-name strong {
  color: var(--ink-strong);
  font-size: 12px;
  font-weight: 650;
}

.shortcut-name span {
  color: var(--muted);
  font-size: 10px;
}

.shortcuts-card .text-button {
  margin-top: 17px;
}

.tip-card {
  min-height: 290px;
  display: flex;
  flex-direction: column;
}

.tip-graphic {
  width: 46px;
  height: 46px;
  margin-bottom: 23px;
}

.tip-copy .card-title {
  font-size: 20px;
}

.tip-copy .card-description {
  max-width: 260px;
  font-size: 11px;
  line-height: 1.6;
}

.tip-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-top: auto;
  padding-top: 24px;
  color: var(--muted);
  font-size: 10px;
}

.tip-list span {
  display: inline-flex;
  align-items: center;
  gap: 7px;
}

.tip-list svg {
  color: var(--accent);
}

.account-grid {
  align-items: stretch;
}

.profile-card,
.security-card {
  min-height: 300px;
}

.profile-hero {
  display: flex;
  align-items: center;
  gap: 14px;
  padding-bottom: 23px;
  border-bottom: 1px solid var(--line);
}

.profile-avatar-large {
  width: 60px;
  height: 60px;
  font-size: 20px;
  border-radius: 19px;
}

.profile-details {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.profile-name {
  color: var(--ink-strong);
  font-size: 15px;
  font-weight: 700;
}

.profile-email {
  color: var(--muted);
  font-size: 10px;
}

.account-badge {
  align-self: flex-start;
  margin-top: 4px;
  color: var(--accent-strong);
  font-size: 9px;
  font-weight: 650;
}

.account-fields {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  margin: 22px 0;
}

.account-field {
  display: flex;
  flex-direction: column;
  gap: 7px;
  min-width: 0;
  padding: 12px;
  background: var(--surface-alt);
  border-radius: 10px;
}

.account-field-label {
  color: var(--muted-2);
  font-size: 9px;
  font-weight: 650;
}

.account-field strong {
  overflow: hidden;
  color: var(--ink-strong);
  font-size: 11px;
  font-weight: 650;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.security-list {
  border-top: 1px solid var(--line);
}

.security-row {
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 64px;
  padding: 9px 0;
}

.security-row + .security-row {
  border-top: 1px solid var(--line);
}

.security-row-icon {
  width: 30px;
  height: 30px;
}

.security-row-copy {
  min-width: 0;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.security-row-copy strong {
  color: var(--ink-strong);
  font-size: 11px;
  font-weight: 650;
}

.security-row-copy span {
  color: var(--muted);
  font-size: 10px;
}

.security-row > svg {
  color: #7daa83;
}

.page-footnote {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  margin-top: 27px;
  color: var(--muted-2);
  font-size: 10px;
}

@media (max-width: 900px) {
  .settings-window {
    grid-template-columns: 88px minmax(0, 1fr);
  }

  .sidebar {
    align-items: center;
    padding-right: 12px;
    padding-left: 12px;
  }

  .brand {
    justify-content: center;
    padding: 0;
  }

  .brand-copy,
  .workspace-copy,
  .workspace-switcher > svg,
  .nav-label,
  .nav-text,
  .account-copy,
  .profile-switcher > svg {
    display: none;
  }

  .workspace-switcher {
    justify-content: center;
    padding: 8px;
  }

  .nav-label {
    text-align: center;
  }

  .nav-item {
    justify-content: center;
    padding: 0;
  }

  .nav-item.is-active::before {
    left: -12px;
  }

  .profile-switcher {
    justify-content: center;
    padding: 8px;
  }

  .settings-grid,
  .appearance-grid,
  .editor-grid,
  .shortcuts-grid,
  .account-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .writing-card,
  .theme-card,
  .shortcuts-card {
    grid-column: auto;
  }

  .sync-card {
    grid-column: auto;
  }
}

@media (max-width: 640px) {
  #root-shell {
    display: block;
    padding: 0;
  }

  .settings-window {
    width: 100%;
    height: auto;
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    border: 0;
    border-radius: 0;
  }

  .sidebar {
    display: none;
  }

  .topbar {
    height: 64px;
    flex-basis: 64px;
    padding: 0 18px;
  }

  .sync-indicator,
  .search-trigger span,
  .search-trigger kbd {
    display: none;
  }

  .search-trigger {
    width: 34px;
    justify-content: center;
    padding: 0;
  }

  .page-body {
    width: 100%;
    padding: 31px 18px 32px;
  }

  .page-heading {
    display: block;
    margin-bottom: 26px;
  }

  .heading-meta {
    margin-top: 17px;
  }

  .banner-link {
    display: none;
  }

  .insight-banner {
