  display: grid;
  grid-template-columns: 62px minmax(0, 1fr);
  overflow: hidden;
  margin-top: 17px;
  border: 1px solid #e5e9e3;
  border-radius: 13px;
  box-shadow: 0 4px 10px rgba(40, 48, 42, .06);
}

.preview-light {
  color: #555e57;
  background: #fff;
  border-color: #e5e9e3;
}

.preview-dim {
  color: #d8d9de;
  background: #2f323a;
  border-color: #444752;
}

.preview-system {
  color: #555e57;
  background: linear-gradient(135deg, #fff 0 67%, #343740 67% 100%);
  border-color: #dfe3de;
}

.preview-sidebar {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 11px;
  padding: 13px 9px;
  background: rgba(123, 131, 121, .065);
  border-right: 1px solid rgba(130, 140, 130, .13);
}

.preview-dim .preview-sidebar {
  background: rgba(0, 0, 0, .12);
  border-color: rgba(255, 255, 255, .08);
}

.preview-logo {
  width: 19px;
  height: 19px;
  display: block;
  margin-bottom: 6px;
  border-radius: 6px;
  box-shadow: 0 2px 5px rgba(39, 46, 41, .13);
}

.preview-side-line {
  width: 31px;
  height: 4px;
  display: block;
  background: rgba(117, 127, 119, .22);
  border-radius: 5px;
}

.preview-side-line-active {
  height: 7px;
  background: rgba(130, 113, 201, .45);
}

.preview-side-line-short {
  width: 22px;
}

.preview-main {
  min-width: 0;
  padding: 12px 16px;
}

.preview-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 18px;
}

.preview-muted-line {
  width: 38px;
  height: 4px;
  display: block;
  background: rgba(126, 137, 128, .2);
  border-radius: 4px;
}

.preview-toolbar-dot {
  width: 5px;
  height: 5px;
  display: block;
  background: rgba(126, 137, 128, .3);
  border-radius: 50%;
}

.preview-kicker {
  display: block;
  margin-bottom: 5px;
  color: rgba(126, 137, 128, .7);
  font-size: 6px;
  font-weight: 800;
  letter-spacing: .16em;
}

.preview-title {
  display: block;
  margin-bottom: 12px;
  font-family: Georgia, serif;
  font-size: 17px;
  font-weight: 600;
  letter-spacing: -.04em;
}

.preview-text-line {
  width: 59%;
  height: 4px;
  display: block;
  margin-top: 7px;
  background: rgba(126, 137, 128, .2);
  border-radius: 4px;
}

.preview-text-line-long {
  width: 84%;
}

.preview-text-line-short {
  width: 42%;
}

.preview-dim .preview-muted-line,
.preview-dim .preview-text-line {
  background: rgba(224, 226, 231, .2);
}

.preview-dim .preview-kicker {
  color: rgba(221, 223, 228, .52);
}

.shortcut-list {
  padding: 0 20px;
}

.shortcut-row {
  min-height: 39px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  color: #69736b;
  font-size: 10.5px;
  border-top: 1px solid #f0f2ee;
}

.key-group {
  display: flex;
  align-items: center;
  gap: 4px;
}

kbd {
  min-width: 20px;
  height: 20px;
  display: inline-grid;
  place-items: center;
  padding: 0 5px;
  color: #747d76;
  font-family: inherit;
  font-size: 9px;
  font-weight: 760;
  background: #f5f7f3;
  border: 1px solid #e2e7e0;
  border-bottom-width: 2px;
  border-radius: 5px;
}

.text-button {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 15px 20px 18px;
  color: #7766b8;
  font-size: 10px;
  font-weight: 720;
  background: transparent;
}

.text-button:hover {
  color: #58478f;
}

.privacy-note,
.section-note {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 5px 4px 2px;
  color: #8f9991;
}

.privacy-icon {
  width: 31px;
  height: 31px;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  color: #6e9c76;
  background: #eaf4eb;
  border-radius: 10px;
}

.privacy-note > span:last-child,
.section-note span {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.privacy-note strong {
  color: #69776d;
  font-size: 10.5px;
  font-weight: 720;
}

.privacy-note small {
  color: #a2aba3;
  font-size: 9.5px;
}

.single-section {
  width: min(100%, 760px);
  margin: 0 auto;
}

.single-section-wide {
  width: min(100%, 880px);
}

.single-section-narrow {
  width: min(100%, 620px);
}

.section-note {
  padding: 0 5px;
  color: #97a099;
  font-size: 10.5px;
}

.section-note svg {
  color: #8471c9;
}

.sync-panel {
  display: flex;
  align-items: center;
  gap: 11px;
  margin: 0 20px 18px;
  padding: 13px;
  background: #f5faf5;
  border: 1px solid #e2eee2;
  border-radius: 12px;
}

.sync-symbol {
  width: 32px;
  height: 32px;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  color: #63966c;
  background: #e1f0e3;
  border-radius: 9px;
}

.sync-copy {
  min-width: 0;
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 3px;
}

.sync-copy strong {
  color: #5d735f;
  font-size: 10.5px;
  font-weight: 740;
}

.sync-copy span {
  color: #91a294;
  font-size: 9.5px;
}

.sync-button {
  height: 29px;
  display: flex;
  align-items: center;
  gap: 6px;
  flex: 0 0 auto;
  padding: 0 9px;
  color: #65836b;
  font-size: 9.5px;
  font-weight: 720;
  background: #fff;
  border: 1px solid #dbe8dc;
  border-radius: 8px;
}

.sync-button:hover {
  background: #f1f8f2;
}

.sync-button:disabled {
  cursor: wait;
  opacity: .72;
}

.sync-button.is-syncing svg {
  animation: spin .8s linear infinite;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

@media (max-width: 980px) {
  #root {
    padding: 16px;
  }

  .app-frame {
    height: calc(100vh - 32px);
    min-height: 680px;
    grid-template-columns: 210px minmax(0, 1fr);
  }

  .sidebar {
    padding-left: 12px;
    padding-right: 12px;
  }

  .topbar {
    padding-left: 25px;
    padding-right: 25px;
  }

  .settings-scroll {
    padding-left: 25px;
    padding-right: 25px;
  }

  .settings-layout {
    grid-template-columns: minmax(0, 1fr);
  }

  .settings-column:last-child {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
    align-items: start;
  }

  .settings-column:last-child .privacy-note {
    grid-column: 1 / -1;
  }
}

@media (max-width: 720px) {
  #root {
    display: block;
    padding: 0;
  }

  .app-frame {
    width: 100%;
    height: auto;
    min-height: 100vh;
    display: block;
    border: 0;
    border-radius: 0;
    box-shadow: none;
  }

  .sidebar {
    display: block;
    padding: 16px 16px 12px;
    border-right: 0;
    border-bottom: 1px solid #e4e9e2;
  }

  .brand {
    display: inline-flex;
    margin: 0 0 14px;
  }

  .workspace-switcher {
    width: min(280px, 100%);
  }

  .sidebar-nav {
    margin-top: 16px;
  }

  .nav-label,
  .nav-label-spaced {
    display: none;
  }

  .nav-list {
    display: flex;
    gap: 5px;
    overflow-x: auto;
    padding-bottom: 2px;
  }

  .nav-item {
    width: auto;
    min-width: max-content;
    min-height: 35px;
    padding: 0 10px;
    font-size: 10.5px;
  }

  .sidebar-lower {
    display: none;
  }

  .main-panel {
    overflow: visible;
  }

  .topbar {
    min-height: 57px;
    padding: 0 18px;
  }

  .settings-scroll {
    overflow: visible;
    padding: 25px 18px 35px;
  }

  .page-header {
    display: block;
    margin-bottom: 22px;
  }

  .page-summary {
    width: max-content;
    margin-top: 17px;
  }

  .settings-column:last-child {
    display: grid;
    grid-template-columns: 1fr;
  }

  .settings-column:last-child .privacy-note {
    grid-column: auto;
  }

  .single-section,
  .single-section-wide,
  .single-section-narrow {
    width: 100%;
  }
}

@media (max-width: 470px) {
  .breadcrumbs > span,
  .command-hint,
  .save-status > span:last-child {
    display: none;
  }

  .topbar-actions {
    gap: 9px;
  }

  .settings-layout {
    gap: 14px;
  }

  .settings-column {
    gap: 14px;
  }

  .setting-row {
    align-items: flex-start;
    flex-direction: column;
    gap: 11px;
  }

  .toggle-row {
    align-items: center;
    flex-direction: row;
  }

  .select-wrap {
    width: 100%;
  }

  .theme-picker {
    gap: 5px;
    padding-left: 14px;
    padding-right: 14px;
  }

  .theme-option {
    justify-content: center;
    padding: 0 5px;
  }

  .theme-option-icon {
    display: none;
  }

  .theme-check {
    top: 4px;
    right: 4px;
  }

  .card-heading,
  .setting-row,
  .accent-area {
    padding-left: 15px;
    padding-right: 15px;
  }

  .shortcut-list {
    padding-left: 15px;
    padding-right: 15px;
  }

  .text-button {
    padding-left: 15px;
    padding-right: 15px;
  }

  .sync-panel {
    align-items: flex-start;
    flex-wrap: wrap;
    margin-left: 15px;
    margin-right: 15px;
  }

  .sync-copy {
    padding-top: 2px;
  }

  .sync-button {
    width: 100%;
    justify-content: center;
    margin-top: 2px;
  }
}

