function Icon({ name, size = 18 }: { name: IconName; size?: number }) {
  return (
    <svg
      className='icon'
      width={size}
      height={size}
      viewBox='0 0 24 24'
      fill='none'
      stroke='currentColor'
      strokeWidth={1.8}
      strokeLinecap='round'
      strokeLinejoin='round'
      aria-hidden='true'
    >
      <path d={iconPaths[name]} />
    </svg>
  );
}

function Toggle({ checked, onChange, label }: { checked: boolean; onChange: () => void; label: string }) {
  return (
    <button
      type='button'
      className={`toggle ${checked ? 'is-on' : ''}`}
      role='switch'
      aria-checked={checked}
      aria-label={label}
      onClick={onChange}
    >
      <span className='toggle-knob' />
    </button>
  );
}

function SettingRow({
  title,
  description,
  children,
  last = false,
}: {
  title: string;
  description: string;
  children: ReactNode;
  last?: boolean;
}) {
  return (
    <div className={`setting-row ${last ? 'is-last' : ''}`}>
      <div className='setting-copy'>
        <h3>{title}</h3>
        <p>{description}</p>
      </div>
      <div className='setting-control'>{children}</div>
    </div>
  );
}

function CardHeading({
  icon,
  tone,
  eyebrow,
  title,
  badge,
}: {
  icon: IconName;
  tone: string;
  eyebrow: string;
  title: string;
  badge?: string;
}) {
  return (
    <div className='card-head'>
      <div className='card-title-wrap'>
        <span className={`icon-tile ${tone}`}>
          <Icon name={icon} size={17} />
        </span>
        <div>
          <span className='card-kicker'>{eyebrow}</span>
          <h2>{title}</h2>
        </div>
      </div>
      {badge ? (
        <span className='card-badge'>
          <Icon name='check' size={13} />
          {badge}
        </span>
      ) : null}
    </div>
  );
}

function ShortcutRow({ icon, label, keys }: { icon: IconName; label: string; keys: string[] }) {
  return (
    <div className='shortcut-row'>
      <div className='shortcut-name'>
        <span className='shortcut-icon'>
          <Icon name={icon} size={15} />
        </span>
        <span>{label}</span>
      </div>
      <div className='shortcut-keys'>
        {keys.map((key) => (
          <kbd key={key}>{key}</kbd>
        ))}
      </div>
    </div>
  );
}

