  font-size: 13px;
  line-height: 1.6;
}

.save-state {
  display: flex;
  align-items: center;
  gap: 8px;
  padding-bottom: 5px;
  color: #8a8e9d;
  font-size: 11px;
  font-weight: 620;
  white-space: nowrap;
}

.save-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #8a8e9d;
  box-shadow: 0 0 0 4px rgba(138, 142, 157, 0.1);
}

.save-dot.is-recent {
  background: var(--teal);
  box-shadow: 0 0 0 4px rgba(54, 183, 154, 0.12);
}

.settings-grid {
  display: grid;
  align-items: start;
  grid-template-columns: minmax(0, 1fr) 315px;
  gap: 26px;
}

.settings-column,
.section-stack,
.side-stack {
  min-width: 0;
}

.section-stack,
.side-stack {
  display: flex;
  flex-direction: column;
  gap: 17px;
}

.settings-card,
.preview-card,
.summary-card {
  border: 1px solid var(--line);
  border-radius: 20px;
  background: rgba(255, 255, 255, 0.94);
  box-shadow: var(--shadow);
}

.settings-card {
  padding: 24px 26px 3px;
}

.card-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 21px;
}

.card-title-wrap {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 12px;
}

.icon-tile {
  display: grid;
  width: 38px;
  height: 38px;
  flex: 0 0 38px;
  place-items: center;
  border-radius: 12px;
}

.icon-tile.indigo {
  color: #7169e8;
  background: #efefff;
}

.icon-tile.teal {
  color: #2b9e85;
  background: #e6f8f3;
}

.icon-tile.rose {
  color: #c45f7d;
  background: #fff0f4;
}

.icon-tile.amber {
  color: #b97825;
  background: #fff4df;
}

.card-kicker,
.preview-kicker {
  display: block;
  margin-bottom: 3px;
  color: #a0a4b3;
  font-size: 9px;
  font-weight: 760;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.card-head h2,
.preview-head h2 {
  margin: 0;
  color: var(--ink);
  font-size: 16px;
  font-weight: 720;
  letter-spacing: -0.025em;
}

.card-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 6px 9px;
  border-radius: 999px;
  color: #389d86;
  font-size: 10px;
  font-weight: 700;
  background: #edf9f5;
}

.setting-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 26px;
  min-height: 78px;
  padding: 18px 0;
  border-top: 1px solid var(--line);
}

.setting-row.is-last {
  padding-bottom: 22px;
}

.setting-copy {
  min-width: 0;
}

.setting-copy h3 {
  margin: 0 0 4px;
  color: #303344;
  font-size: 12px;
  font-weight: 680;
  letter-spacing: -0.01em;
}

.setting-copy p {
  max-width: 520px;
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.48;
}

.setting-control {
  display: flex;
  min-width: 180px;
  align-items: center;
  justify-content: flex-end;
}

.text-input,
.select-input {
  height: 40px;
  border: 1px solid var(--line-strong);
  border-radius: 10px;
  color: #3b3e4d;
  font-size: 12px;
  background: #fbfcff;
  transition: border-color 160ms ease, box-shadow 160ms ease, background 160ms ease;
}

.text-input {
  width: 214px;
  padding: 0 12px;
}

.text-input:hover,
.select-input:hover {
  border-color: #c9cbe0;
  background: #ffffff;
}

.text-input:focus,
.select-input:focus {
  border-color: #aaa5f4;
  box-shadow: 0 0 0 4px rgba(113, 105, 232, 0.1);
  outline: 0;
}

.select-wrap {
  position: relative;
  width: 214px;
}

.select-input {
  width: 100%;
  padding: 0 34px 0 12px;
  appearance: none;
}

.select-wrap::after {
  position: absolute;
  top: 50%;
  right: 13px;
  color: #9296a7;
  content: '⌄';
  font-size: 14px;
  pointer-events: none;
  transform: translateY(-56%);
}

.toggle {
  position: relative;
  width: 47px;
  height: 28px;
  padding: 3px;
  border: 0;
  border-radius: 999px;
  background: #e2e4ec;
  transition: background 180ms ease, box-shadow 180ms ease;
}

.toggle:hover {
  box-shadow: 0 0 0 4px rgba(125, 130, 147, 0.1);
}

.toggle.is-on {
  background: var(--accent);
  box-shadow: 0 4px 10px rgba(113, 105, 232, 0.22);
}

.toggle.is-on:hover {
  box-shadow: 0 0 0 4px rgba(113, 105, 232, 0.11), 0 4px 10px rgba(113, 105, 232, 0.2);
}

.toggle-knob {
  display: block;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: #ffffff;
  box-shadow: 0 2px 5px rgba(36, 40, 68, 0.16);
  transition: transform 180ms ease;
}

.toggle.is-on .toggle-knob {
  transform: translateX(19px);
}

.settings-callout {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 15px 17px;
  border: 1px solid #e7e4ff;
  border-radius: 16px;
  color: #5d57a6;
  background: linear-gradient(100deg, #f4f3ff, #faf9ff);
}

.callout-icon {
  display: grid;
  width: 31px;
  height: 31px;
  flex: 0 0 31px;
  place-items: center;
  border-radius: 10px;
  color: var(--accent);
  background: #e8e6ff;
}

.settings-callout div {
  min-width: 0;
  flex: 1;
}

.settings-callout strong {
  display: block;
  margin-bottom: 3px;
  color: #514b98;
  font-size: 11px;
  font-weight: 720;
}

.settings-callout p {
  margin: 0;
  color: #8380ae;
  font-size: 10px;
  line-height: 1.45;
}

.settings-callout > .icon {
  color: #9894d5;
}

.editor-callout {
  border-color: #dcefeb;
  color: #327d6d;
  background: linear-gradient(100deg, #eefaf7, #f8fcfb);
}

.editor-callout .callout-icon {
  color: #29977f;
  background: #daf3ec;
}

.editor-callout strong {
  color: #327d6d;
}

.editor-callout p {
  color: #729d93;
}

.editor-callout > .icon {
  color: #82b8aa;
}

.range-control {
  display: flex;
  width: 214px;
  align-items: center;
  gap: 11px;
}

.range-control input[type='range'] {
  width: 154px;
  height: 4px;
  accent-color: var(--accent);
  cursor: pointer;
}

.range-value {
  min-width: 36px;
  color: #656a7c;
  font-size: 11px;
  font-variant-numeric: tabular-nums;
  text-align: right;
}

.theme-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
  padding-bottom: 24px;
}

.theme-choice {
  position: relative;
  min-width: 0;
  padding: 9px;
  border: 1px solid var(--line);
  border-radius: 15px;
  color: var(--ink);
  text-align: left;
  background: var(--surface-soft);
  transition: border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
}

.theme-choice:hover {
  border-color: #cac8e7;
  transform: translateY(-1px);
}

.theme-choice.is-selected {
  border-color: #9d98f0;
  box-shadow: 0 0 0 3px rgba(113, 105, 232, 0.1);
}

.theme-swatch {
  display: block;
  height: 75px;
  padding: 10px;
  overflow: hidden;
  border-radius: 10px;
}

.theme-swatch.dusk {
  color: #f9f8ff;
  background: #302d4b;
}

.theme-swatch.paper {
  color: #403c33;
  background: #fffaf0;
  box-shadow: inset 0 0 0 1px #efe8d7;
}

.theme-swatch.midnight {
  color: #f3f5fb;
  background: #171a23;
}

.swatch-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 14px;
}

.swatch-orb {
  display: block;
  width: 10px;
  height: 10px;
  border-radius: 4px;
  background: currentColor;
  opacity: 0.75;
}

.theme-swatch.dusk .swatch-orb {
  background: #a8a1ff;
}

.theme-swatch.paper .swatch-orb {
  background: #e3ab58;
}

.theme-swatch.midnight .swatch-orb {
  background: #78a9ff;
}

.swatch-menu {
  width: 19px;
  height: 4px;
  border-top: 1px solid currentColor;
  border-bottom: 1px solid currentColor;
  opacity: 0.35;
}

.swatch-lines {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.swatch-lines i {
  display: block;
  height: 4px;
  border-radius: 5px;
  background: currentColor;
  opacity: 0.22;
}

.swatch-lines i:nth-child(1) {
  width: 72%;
  opacity: 0.65;
}

.swatch-lines i:nth-child(2) {
  width: 92%;
}

.swatch-lines i:nth-child(3) {
  width: 54%;
}

.theme-option-copy {
  display: flex;
  gap: 3px;
  padding: 10px 2px 2px;
  flex-direction: column;
}

.theme-option-copy strong {
  color: #363949;
  font-size: 11px;
  font-weight: 700;
}

.theme-option-copy span {
  overflow: hidden;
  color: #969aaa;
  font-size: 9px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.selected-mark {
  position: absolute;
  top: 15px;
  right: 15px;
  display: grid;
  width: 20px;
  height: 20px;
  place-items: center;
  border-radius: 50%;
  color: #ffffff;
  background: var(--accent);
  box-shadow: 0 3px 7px rgba(76, 68, 185, 0.3);
}

.segmented-control {
  display: flex;
  padding: 3px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: #f4f5f9;
}

.segmented-control button {
  min-width: 91px;
  padding: 7px 10px;
  border: 0;
  border-radius: 7px;
  color: #9397a7;
  font-size: 10px;
  font-weight: 650;
  background: transparent;
  transition: color 160ms ease, background 160ms ease, box-shadow 160ms ease;
}

.segmented-control button.is-selected {
  color: #4e4b88;
  background: #ffffff;
  box-shadow: 0 2px 6px rgba(53, 58, 90, 0.1);
}

.shortcut-list {
  border-top: 1px solid var(--line);
}

.shortcut-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  min-height: 54px;
  border-bottom: 1px solid var(--line);
}

.shortcut-name {
  display: flex;
  align-items: center;
  gap: 10px;
  color: #4b4e5e;
  font-size: 11px;
  font-weight: 600;
}

.shortcut-icon {
  display: grid;
  width: 27px;
  height: 27px;
  place-items: center;
  border-radius: 8px;
  color: #b77a2e;
  background: #fff5e7;
}

.shortcut-keys {
  display: flex;
  align-items: center;
  gap: 4px;
}

kbd {
  display: inline-grid;
  min-width: 23px;
  height: 23px;
  padding: 0 6px;
  place-items: center;
  border: 1px solid #dfe1e9;
  border-bottom-width: 2px;
  border-radius: 6px;
  color: #6c7080;
  font-family: inherit;
  font-size: 10px;
  font-weight: 720;
  background: #fafbfe;
}

.shortcut-callout {
  border-color: #f3e4c8;
  color: #a8732d;
  background: linear-gradient(100deg, #fff8eb, #fffdf7);
}

.shortcut-callout .callout-icon {
  color: #b77a2e;
  background: #ffefcf;
}

.shortcut-callout strong {
  color: #986729;
}

.shortcut-callout p {
  color: #b19262;
}

.shortcut-callout > .icon {
  color: #c3a477;
}

.side-stack {
  position: sticky;
  top: 22px;
}

.preview-card {
  padding: 19px;
}

.preview-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  margin: 0 2px 15px;
}

.preview-head h2 {
  font-size: 14px;
}

.preview-more {
  width: 28px;
  height: 28px;
  border-radius: 9px;
}

.note-preview {
  position: relative;
  min-height: 278px;
  padding: 18px 17px 17px;
  overflow: hidden;
  border: 1px solid transparent;
  border-radius: 16px;
  transition: background 180ms ease, color 180ms ease, min-height 180ms ease;
}

.note-preview.is-compact {
  min-height: 247px;
}

.note-preview::before {
  position: absolute;
  top: -50px;
  right: -40px;
  width: 145px;
  height: 145px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255, 255, 255, 0.12), rgba(255, 255, 255, 0) 70%);
  content: '';
  pointer-events: none;
}

.note-preview.theme-dusk {
  border-color: #484365;
  color: #f8f7ff;
  background: #302d4b;
}

.note-preview.theme-paper {
  border-color: #eee6d8;
  color: #353229;
  background: #fffaf0;
}

.note-preview.theme-midnight {
  border-color: #303748;
  color: #f2f5fb;
  background: #171a23;
}

.note-preview-top,
.note-tools,
.note-checkline,
.preview-footer,
.storage-label {
  display: flex;
  align-items: center;
}

.note-preview-top {
  position: relative;
  z-index: 1;
  justify-content: space-between;
  margin-bottom: 29px;
}

.note-type {
  font-size: 9px;
  font-weight: 760;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  opacity: 0.62;
}

.note-tools {
  gap: 8px;
  opacity: 0.52;
}

.note-time {
  font-size: 9px;
  font-variant-numeric: tabular-nums;
}

.note-preview h3 {
  position: relative;
  z-index: 1;
  max-width: 220px;
  margin: 0 0 12px;
  font-size: 22px;
  font-weight: 690;
  letter-spacing: -0.055em;
  line-height: 1.08;
}

.note-preview p {
  position: relative;
  z-index: 1;
  margin: 0;
  font-size: 11px;
  line-height: inherit;
}

.note-lead {
  max-width: 220px;
  opacity: 0.68;
}

.note-rule {
  position: relative;
  z-index: 1;
  margin: 24px 0 18px;
  border-top: 1px solid rgba(255, 255, 255, 0.18);
}

.theme-paper .note-rule {
  border-color: rgba(70, 61, 44, 0.13);
}

.note-detail {
  max-width: 210px;
  opacity: 0.82;
}

.note-checkline {
  position: relative;
  z-index: 1;
  gap: 8px;
  margin-top: 17px;
  color: inherit;
  font-size: 10px;
  opacity: 0.72;
}

.fake-check {
  display: grid;
  width: 16px;
  height: 16px;
  flex: 0 0 16px;
  place-items: center;
  border: 1px solid currentColor;
  border-radius: 5px;
  opacity: 0.82;
}

.preview-footer {
  gap: 7px;
  margin: 13px 2px 0;
  color: #a1a5b5;
  font-size: 10px;
}

.preview-pulse {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #72cdb8;
  box-shadow: 0 0 0 4px rgba(54, 183, 154, 0.1);
}

.summary-card {
  padding: 20px 21px 18px;
}

.summary-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 15px;
  color: #777c8e;
  font-size: 10px;
  font-weight: 760;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.summary-spark {
  display: grid;
  width: 25px;
  height: 25px;
  place-items: center;
  border-radius: 8px;
  color: #8a82ee;
  background: #f0efff;
}

.summary-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 11px 0;
  border-top: 1px solid var(--line);
  color: #858a9b;
  font-size: 11px;
}

.summary-row strong {
  overflow: hidden;
  color: #454959;
  font-size: 11px;
  font-weight: 680;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.summary-row strong.status-positive {
  color: #389d86;
}

.storage-block {
  padding-top: 14px;
  border-top: 1px solid var(--line);
}

.storage-label {
  justify-content: space-between;
  margin-bottom: 8px;
  color: #858a9b;
  font-size: 10px;
}

.storage-label span:last-child {
  color: #565b6c;
  font-weight: 650;
}

.storage-meter {
  height: 6px;
  overflow: hidden;
  border-radius: 99px;
  background: #eeeff4;
}

.storage-meter span {
  display: block;
  width: 24%;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #8d86f2, #6d65e1);
}

.help-card {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 15px;
  border: 1px solid #e8e8f5;
  border-radius: 16px;
  color: #878ba0;
  background: #fbfbff;
}

.help-icon {
  display: grid;
  width: 31px;
  height: 31px;
  flex: 0 0 31px;
  place-items: center;
  border-radius: 10px;
  color: #7c75df;
  background: #efefff;
}

.help-card div {
  min-width: 0;
  flex: 1;
}

.help-card strong {
  display: block;
  margin-bottom: 3px;
  color: #555a70;
  font-size: 11px;
  font-weight: 700;
}

.help-card p {
  margin: 0;
  overflow: hidden;
  color: #999daf;
  font-size: 10px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.help-card > .icon {
  color: #aaa8c8;
}

@media (max-width: 1120px) {
  .main-content {
    padding-right: 28px;
    padding-left: 28px;
  }

  .settings-grid {
    grid-template-columns: minmax(0, 1fr) 285px;
    gap: 20px;
  }

  .setting-row {
    gap: 18px;
  }
}

@media (max-width: 900px) {
  .sidebar {
    width: 82px;
    flex-basis: 82px;
    padding-right: 12px;
    padding-left: 12px;
  }

  .brand-lockup {
    justify-content: center;
    padding: 0;
  }

  .brand-name,
  .workspace-meta,
  .workspace-switcher > .icon,
  .nav-section-label,
  .nav-link > span:not(.nav-icon),
  .nav-count,
  .sidebar-bottom {
    display: none;
  }

  .workspace-switcher {
    justify-content: center;
    padding: 8px;
  }

  .sidebar-nav {
    margin-top: 26px;
  }

  .nav-link {
    justify-content: center;
    padding: 11px;
  }

  .nav-divider {
    margin-right: 8px;
    margin-left: 8px;
  }

  .settings-grid {
    grid-template-columns: minmax(0, 1fr) 260px;
  }

  .text-input,
  .select-wrap,
  .range-control {
    width: 190px;
  }

  .range-control input[type='range'] {
    width: 130px;
  }

  .segmented-control button {
    min-width: 75px;
  }
}

@media (max-width: 720px) {
  .sidebar {
    display: none;
  }

  .main-content {
    padding: 0 16px 30px;
  }

  .topbar {
    height: 64px;
  }

  .mobile-menu {
    display: grid;
    place-items: center;
  }

  .page-heading {
    display: block;
    padding: 32px 0 27px;
  }

  .page-heading h1 {
    font-size: 34px;
  }

  .page-heading p {
    font-size: 12px;
  }

  .save-state {
    padding-top: 20px;
  }

  .settings-grid {
    display: block;
  }

  .side-stack {
    position: static;
    margin-top: 17px;
  }

  .settings-card {
    padding-right: 18px;
    padding-left: 18px;
  }

  .setting-row {
    align-items: flex-start;
    flex-direction: column;
    gap: 14px;
    padding: 18px 0;
  }

  .setting-control {
    width: 100%;
    min-width: 0;
    justify-content: flex-start;
  }

  .text-input,
  .select-wrap,
  .range-control {
    width: 100%;
  }

  .range-control input[type='range'] {
    width: 100%;
  }

  .theme-grid {
    grid-template-columns: 1fr;
  }

  .theme-swatch {
    height: 69px;
  }

  .theme-choice {
    display: flex;
    align-items: center;
    gap: 12px;
  }

  .theme-option-copy {
    padding: 0;
  }

  .theme-choice .selected-mark {
    top: 50%;
    right: 13px;
    transform: translateY(-50%);
  }

  .theme-swatch {
    width: 105px;
    flex: 0 0 105px;
  }

  .settings-callout {
    align-items: flex-start;
  }

  .shortcut-row {
    min-height: 58px;
  }
}

