  --mint-ink: #478063;
  --blue: #e5eef8;
  --blue-ink: #4f759d;
  --shadow: 0 18px 42px rgba(36, 49, 41, 0.07), 0 2px 7px rgba(36, 49, 41, 0.04);
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  min-height: 100%;
}

body {
  margin: 0;
  background: var(--page-bg);
  color: var(--ink);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  -webkit-font-smoothing: antialiased;
}

button,
select {
  font: inherit;
}

button {
  cursor: pointer;
}

.app-shell {
  display: grid;
  grid-template-columns: 260px minmax(0, 1fr);
  min-height: 100vh;
  background: var(--page-bg);
}

.sidebar {
  display: flex;
  min-height: 100vh;
  flex-direction: column;
  justify-content: space-between;
  padding: 28px 17px 18px;
  color: var(--sidebar-text);
  background: linear-gradient(165deg, #233029 0%, #1b251f 54%, #17201b 100%);
}

.sidebar-top {
  min-width: 0;
}

.sidebar-brand {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 0 10px;
}

.brand-mark {
  display: grid;
  width: 37px;
  height: 37px;
  flex: 0 0 37px;
  place-items: center;
  color: #20372a;
  border-radius: 12px;
  background: #cfe5d3;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.18), 0 7px 18px rgba(8, 15, 11, 0.2);
}

.brand-copy {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.brand-name {
  color: #f5f8f3;
  font-size: 15px;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.workspace-name {
  overflow: hidden;
  color: var(--sidebar-muted);
  font-size: 11px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.settings-search {
  display: flex;
  width: 100%;
  align-items: center;
  justify-content: space-between;
  margin: 32px 0 25px;
  padding: 10px 10px 10px 12px;
  color: #aab7ad;
  border: 1px solid rgba(222, 239, 224, 0.11);
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.055);
  transition: border-color 160ms ease, background 160ms ease, color 160ms ease;
}

.settings-search:hover {
  color: #e7efe7;
  border-color: rgba(222, 239, 224, 0.23);
  background: rgba(255, 255, 255, 0.09);
}

.search-label {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
}

.settings-search kbd {
  padding: 3px 5px;
  color: #8d9d91;
  font-size: 10px;
  line-height: 1;
  border: 1px solid rgba(222, 239, 224, 0.13);
  border-radius: 5px;
  background: rgba(0, 0, 0, 0.13);
}

.sidebar-nav {
  display: grid;
  gap: 5px;
}

.nav-label {
  margin: 0 10px 8px;
  color: #718176;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}

.nav-item {
  position: relative;
  display: flex;
  width: 100%;
  align-items: center;
  gap: 11px;
  padding: 10px 10px;
  color: var(--sidebar-muted);
  text-align: left;
  border: 0;
  border-radius: 10px;
  background: transparent;
  transition: color 160ms ease, background 160ms ease, transform 160ms ease;
}

.nav-item:hover {
  color: #eaf2eb;
  background: rgba(255, 255, 255, 0.065);
}

.nav-item:active {
  transform: translateY(1px);
}

.nav-item.is-active {
  color: #f4faf3;
  background: rgba(196, 227, 202, 0.14);
  box-shadow: inset 0 0 0 1px rgba(205, 237, 210, 0.08);
}

.nav-item.is-active::before {
  position: absolute;
  top: 11px;
  bottom: 11px;
  left: -17px;
  width: 3px;
  border-radius: 0 4px 4px 0;
  background: #b9dfc0;
  content: '';
}

.nav-icon {
  display: grid;
  width: 24px;
  height: 24px;
  flex: 0 0 24px;
  place-items: center;
  color: currentColor;
  border-radius: 7px;
}

.nav-item.is-active .nav-icon {
  color: #c9e5cc;
  background: rgba(196, 227, 202, 0.13);
}

.nav-item-label {
  flex: 1;
  font-size: 12.5px;
  font-weight: 520;
}

.nav-badge {
  display: inline-grid;
  min-width: 19px;
  height: 19px;
  place-items: center;
  padding: 0 5px;
  color: #bde1c3;
  font-size: 10px;
  font-weight: 700;
  border-radius: 7px;
  background: rgba(181, 223, 190, 0.15);
}

.sidebar-footer {
  display: grid;
  gap: 15px;
}

.sidebar-help {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 0 10px;
  color: #99a99c;
  font-size: 11.5px;
  text-align: left;
  border: 0;
  background: transparent;
}

.sidebar-help:hover {
  color: #e1ede2;
}

.sidebar-help > svg {
  margin-left: auto;
}

.sidebar-help-icon {
  display: grid;
  width: 23px;
  height: 23px;
  place-items: center;
  color: #aec4b1;
  border: 1px solid rgba(201, 226, 204, 0.16);
  border-radius: 7px;
}

.profile-card {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 10px;
  border: 1px solid rgba(221, 240, 224, 0.1);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.055);
}

.avatar {
  display: grid;
  width: 29px;
  height: 29px;
  flex: 0 0 29px;
  place-items: center;
  color: #31513d;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.03em;
  border-radius: 9px;
  background: #d8e7d8;
}

.profile-copy {
  display: grid;
  min-width: 0;
  flex: 1;
  gap: 2px;
}

.profile-name {
  overflow: hidden;
  color: #e6eee6;
  font-size: 11px;
  font-weight: 650;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.profile-plan {
  color: #829487;
  font-size: 10px;
}

.profile-card > svg {
  color: #829487;
}

.content {
  min-width: 0;
  background: var(--page-bg);
}

.topbar {
  position: sticky;
  z-index: 5;
  top: 0;
  display: flex;
  height: 76px;
  align-items: center;
  justify-content: space-between;
  padding: 0 48px;
  border-bottom: 1px solid rgba(210, 218, 210, 0.7);
  background: rgba(244, 245, 241, 0.88);
  backdrop-filter: blur(18px);
}

.breadcrumbs {
  display: flex;
  align-items: center;
  gap: 8px;
  color: #98a29b;
  font-size: 12px;
}

.breadcrumbs svg {
  color: #b5bdb6;
}

.crumb-current {
  color: #465249;
  font-weight: 650;
}

.topbar-actions {
  display: flex;
  align-items: center;
  gap: 20px;
}

.autosave-status {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: #7c887e;
  font-size: 11px;
}

.status-dot,
.live-indicator {
  display: inline-block;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #70a77c;
  box-shadow: 0 0 0 4px rgba(112, 167, 124, 0.12);
}

.icon-button {
  display: grid;
  width: 34px;
  height: 34px;
  place-items: center;
  color: #758078;
  border: 1px solid var(--line-strong);
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.64);
  transition: color 160ms ease, border-color 160ms ease, background 160ms ease;
}

.icon-button:hover {
  color: var(--ink);
  border-color: #c5cec5;
  background: var(--surface);
}

.page {
  width: min(100%, 1240px);
  margin: 0 auto;
  padding: 43px 48px 58px;
}

.page-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 28px;
  margin-bottom: 29px;
}

.eyebrow,
.card-overline {
  margin: 0 0 8px;
  color: var(--accent);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.page-heading h1 {
  margin: 0;
  color: #1e2922;
  font-size: clamp(31px, 4vw, 43px);
  font-weight: 720;
  letter-spacing: -0.055em;
  line-height: 1.03;
}

.heading-copy {
  max-width: 560px;
  margin: 11px 0 0;
  color: var(--ink-soft);
  font-size: 13px;
  line-height: 1.55;
}

.save-button {
  display: inline-flex;
  min-width: 131px;
  height: 39px;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 0 15px;
  color: #f5faf5;
  font-size: 12px;
  font-weight: 700;
  border: 0;
  border-radius: 10px;
  background: var(--accent);
  box-shadow: 0 8px 18px rgba(63, 114, 89, 0.18);
  transition: transform 160ms ease, background 160ms ease, box-shadow 160ms ease;
}

.save-button:hover {
  background: var(--accent-deep);
  box-shadow: 0 10px 22px rgba(63, 114, 89, 0.24);
  transform: translateY(-1px);
}

.save-button.is-saved {
  color: #3c6c51;
  border: 1px solid #cfe4d3;
  background: #eff8f0;
  box-shadow: none;
}

.preview-card,
.settings-card,
.shortcut-card {
  border: 1px solid var(--line);
  background: var(--surface);
  box-shadow: var(--shadow);
}

.preview-card {
  margin-bottom: 24px;
  padding: 19px;
  border-radius: 20px;
}

.preview-card-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  margin: 0 2px 15px;
}

.preview-label {
  display: flex;
  align-items: center;
  gap: 9px;
  color: #536158;
  font-size: 11px;
  font-weight: 750;
}

.preview-note {
  margin-left: 2px;
  color: #a0aaa2;
  font-size: 10px;
  font-weight: 500;
}

.preview-action,
.text-button {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 0;
  color: var(--accent);
  font-size: 11px;
  font-weight: 700;
  border: 0;
  background: transparent;
}

.preview-action:hover,
.text-button:hover {
  color: var(--accent-deep);
}

.note-preview {
  overflow: hidden;
  color: #26352c;
  border: 1px solid #dce5dc;
  border-radius: 15px;
  background: #fffefa;
  transition: color 220ms ease, background 220ms ease, border-color 220ms ease;
}

.note-window-bar {
  display: flex;
  height: 38px;
  align-items: center;
  justify-content: space-between;
  padding: 0 14px;
  color: #99a39b;
  border-bottom: 1px solid #e8ede8;
  background: #fafcf9;
}

.window-dots,
.window-actions {
  display: flex;
  width: 62px;
  align-items: center;
  gap: 5px;
}

.window-dots span,
.window-actions span {
  display: block;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #c9d2ca;
}

.window-dots span:first-child {
  background: #d8aca1;
}

.window-dots span:nth-child(2) {
  background: #d9c998;
}

.window-dots span:nth-child(3) {
  background: #a7c6a7;
}

.window-actions {
  justify-content: flex-end;
}

.window-actions span {
  width: 13px;
  height: 4px;
  border-radius: 3px;
  background: #d6ded7;
}

.window-path {
  display: flex;
  align-items: center;
  gap: 6px;
  color: #8d9990;
  font-size: 10px;
  letter-spacing: 0.01em;
}

.note-window-content {
  display: grid;
  grid-template-columns: 190px minmax(0, 1fr);
  min-height: 268px;
}

.note-outline {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 25px 18px;
  color: #8a958d;
  border-right: 1px solid #edf0ec;
  background: #f8faf7;
}

.outline-heading {
  margin: 0 0 10px;
  color: #a5afa6;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.14em;
}

.outline-item {
  overflow: hidden;
  padding: 8px 9px;
  color: #839087;
  font-size: 10px;
  text-overflow: ellipsis;
  white-space: nowrap;
  border-radius: 7px;
}

.outline-item.is-current {
  color: #486957;
  font-weight: 700;
  background: #eaf3ea;
}

.outline-item.muted {
  color: #aeb7af;
}

.outline-line {
  width: 100%;
  height: 1px;
  margin: 12px 0 4px;
  background: #e7ece6;
}

.note-copy {
  max-width: 690px;
  padding: 37px 52px 34px;
  font-family: Inter, ui-sans-serif, system-ui, sans-serif;
}

.note-meta {
  display: flex;
  align-items: center;
  gap: 10px;
  color: #a0aaa1;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.13em;
}

.note-status {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  color: #78a180;
  font-size: 8px;
  font-weight: 650;
  letter-spacing: 0;
  text-transform: none;
}

.note-status::before {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: #77ad81;
  content: '';
}

.note-copy h2 {
  margin: 12px 0 9px;
  color: #233329;
  font-size: 29px;
  font-weight: 680;
  letter-spacing: -0.05em;
  line-height: 1.05;
}

.note-copy > p {
  max-width: 600px;
  margin: 0;
  color: #6e7c72;
  font-size: 12px;
  line-height: 1.68;
}

.note-callout {
  display: flex;
  max-width: 485px;
  align-items: flex-start;
  gap: 10px;
  margin-top: 22px;
  padding: 12px 14px;
  border: 1px solid #e0ebdf;
  border-radius: 9px;
  background: #f0f7ee;
}

.callout-icon {
  display: grid;
  width: 25px;
  height: 25px;
  flex: 0 0 25px;
  place-items: center;
  color: #6a9a73;
  border-radius: 7px;
  background: #dcebdc;
}

.note-callout strong {
  display: block;
  margin: 1px 0 3px;
  color: #4a6b52;
  font-size: 10px;
  font-weight: 750;
}

.note-callout p {
  margin: 0;
  color: #7e9580;
  font-size: 10px;
  line-height: 1.4;
}

.note-lines {
  display: grid;
  gap: 6px;
  margin-top: 21px;
  color: #a1aba3;
  font-size: 10px;
}

.note-lines span {
  display: flex;
  align-items: baseline;
  gap: 10px;
}

.line-number {
  width: 19px;
  flex: 0 0 19px;
  color: #9caf9e;
  font-size: 8px;
  text-align: right;
  opacity: 0;
}

.note-lines.show-line-numbers .line-number {
  opacity: 1;
}

.typeface-serif .note-copy {
  font-family: Georgia, 'Times New Roman', serif;
}

.typeface-serif .note-copy h2 {
  font-family: Georgia, 'Times New Roman', serif;
  font-weight: 600;
  letter-spacing: -0.035em;
}

.typeface-mono .note-copy {
  font-family: 'SFMono-Regular', Consolas, 'Liberation Mono', monospace;
}

.typeface-mono .note-copy h2 {
  font-family: 'SFMono-Regular', Consolas, 'Liberation Mono', monospace;
  font-size: 22px;
  letter-spacing: -0.045em;
}

.density-compact .note-copy {
  padding-top: 30px;
  padding-bottom: 26px;
}

.density-compact .note-callout {
  margin-top: 16px;
}

.density-spacious .note-copy {
  padding-top: 47px;
  padding-bottom: 43px;
}

.density-spacious .note-callout {
  margin-top: 28px;
}

.note-preview.theme-dim {
  color: #3f403a;
  border-color: #dedbd2;
  background: #f7f3eb;
}

.theme-dim .note-window-bar {
  border-color: #e8e2d8;
  background: #f1ede5;
}

.theme-dim .note-outline {
  border-color: #e7e1d7;
  background: #f0ece3;
}

.theme-dim .outline-item.is-current {
  color: #7b6848;
  background: #e9e0cd;
}

.theme-dim .note-copy h2 {
  color: #3c3b36;
}

.theme-dim .note-copy > p {
  color: #78766d;
}

.theme-dim .note-callout {
  border-color: #e5dcc9;
  background: #f3eadd;
}

.theme-dim .callout-icon {
  color: #9b7b47;
  background: #eadcc3;
}

.theme-dim .note-callout strong {
  color: #806a43;
}

.theme-dim .note-callout p {
  color: #9a896c;
}

.note-preview.theme-dark {
  color: #dce8dc;
  border-color: #3b4c40;
  background: #222c26;
}

.theme-dark .note-window-bar {
  color: #728477;
  border-color: #344238;
  background: #263229;
}

.theme-dark .window-dots span,
.theme-dark .window-actions span {
  background: #526258;
}

.theme-dark .window-dots span:first-child {
  background: #9a6f69;
}

.theme-dark .window-dots span:nth-child(2) {
  background: #9f9167;
}

.theme-dark .window-dots span:nth-child(3) {
  background: #6f9878;
}

.theme-dark .window-path {
  color: #839388;
}

.theme-dark .note-outline {
  color: #87988a;
  border-color: #344238;
  background: #1d2721;
}

.theme-dark .outline-heading {
  color: #718174;
}

.theme-dark .outline-item {
  color: #899b8d;
}

.theme-dark .outline-item.is-current {
  color: #b9d9bc;
  background: #2d4534;
}

.theme-dark .outline-item.muted,
.theme-dark .note-meta {
  color: #718075;
}

.theme-dark .outline-line {
  background: #344238;
}

.theme-dark .note-meta,
.theme-dark .note-status,
.theme-dark .note-copy > p,
.theme-dark .note-lines {
  color: #91a397;
}

.theme-dark .note-copy h2 {
  color: #eff6ed;
}

.theme-dark .note-status::before {
  background: #82b68c;
}

.theme-dark .note-callout {
  border-color: #3d5944;
  background: #2b4031;
}

.theme-dark .callout-icon {
  color: #a6d3a6;
  background: #385440;
}

.theme-dark .note-callout strong {
  color: #c3e0c1;
}

.theme-dark .note-callout p {
  color: #9ebca1;
}

.theme-dark .line-number {
  color: #75917c;
}

.settings-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 24px;
  align-items: start;
}

.settings-card {
  min-width: 0;
  padding: 25px 24px 8px;
  border-radius: 17px;
}

.card-heading {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  min-height: 56px;
  margin-bottom: 7px;
}

.heading-icon {
  display: grid;
  width: 35px;
  height: 35px;
  flex: 0 0 35px;
  place-items: center;
  border-radius: 11px;
}

.tone-lilac {
  color: var(--lilac-ink);
  background: var(--lilac);
}

.tone-mint {
  color: var(--mint-ink);
  background: var(--mint);
}

.tone-blue {
  color: var(--blue-ink);
  background: var(--blue);
}

.card-heading h2,
.shortcut-copy h2 {
  margin: 0;
  color: #2d3931;
  font-size: 17px;
  font-weight: 710;
  letter-spacing: -0.035em;
}

.card-heading p:not(.card-overline),
.shortcut-copy p:not(.card-overline) {
  margin: 5px 0 0;
  color: #8b968e;
  font-size: 11px;
  line-height: 1.45;
}

.card-overline {
  margin-bottom: 4px;
  color: #97a39a;
  font-size: 8px;
  letter-spacing: 0.15em;
}

.setting-row {
  display: flex;
  min-width: 0;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 19px 0;
  border-top: 1px solid var(--line);
}

.setting-row-column {
  display: block;
}

.setting-info {
  min-width: 0;
}

.setting-name {
  display: block;
  color: #455149;
  font-size: 12px;
  font-weight: 700;
}

.setting-info p {
  margin: 5px 0 0;
  color: #9aa49c;
  font-size: 10.5px;
  line-height: 1.45;
}

.theme-options {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
  margin-top: 16px;
}

.theme-option {
  position: relative;
  display: flex;
  min-width: 0;
  flex-direction: column;
  align-items: stretch;
  gap: 9px;
  padding: 8px;
  color: #7b877e;
  text-align: left;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: #fbfcfa;
