  padding: 46px 44px 40px;
}

.page-intro {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 33px;
}

.section-kicker,
.eyebrow {
  display: block;
  color: var(--accent);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.page-intro h1 {
  margin: 8px 0 7px;
  color: var(--ink);
  font-size: clamp(30px, 3vw, 38px);
  font-weight: 770;
  letter-spacing: -0.055em;
  line-height: 1;
}

.page-intro p {
  max-width: 560px;
  margin: 0;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.6;
}

.workspace-pill {
  gap: 8px;
  flex: 0 0 auto;
  min-height: 33px;
  padding: 0 12px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 650;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 999px;
}

.status-dot,
.sync-dot {
  display: inline-block;
  width: 7px;
  height: 7px;
  background: #4fc493;
  border-radius: 50%;
  box-shadow: 0 0 0 3px rgba(79, 196, 147, 0.12);
}

.settings-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 314px;
  align-items: start;
  gap: 23px;
}

.content-column {
  display: grid;
  gap: 18px;
  min-width: 0;
}

.panel-card,
.preview-tip,
.save-bar {
  background: var(--surface);
  border: 1px solid var(--line);
  box-shadow: 0 10px 30px rgba(36, 44, 75, 0.035);
}

.panel-card {
  padding: 23px 24px;
  border-radius: 20px;
}

.panel-card-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 15px;
}

.card-title-wrap {
  display: flex;
  align-items: center;
  gap: 13px;
  min-width: 0;
}

.card-icon {
  display: grid;
  flex: 0 0 auto;
  width: 39px;
  height: 39px;
  place-items: center;
  border-radius: 12px;
}

.card-icon.violet {
  color: #6b5fe8;
  background: #efedff;
}

.card-icon.mint {
  color: #289d78;
  background: #e3f7ef;
}

.card-icon.blue {
  color: #377fce;
  background: #e6f1ff;
}

.card-icon.orange {
  color: #ce8429;
  background: #fff0dc;
}

.card-icon.coral {
  color: #d96768;
  background: #ffe9e9;
}

.shell-dark .card-icon.violet {
  color: #b0a8ff;
  background: rgba(117, 104, 245, 0.16);
}

.shell-dark .card-icon.mint {
  color: #73d9b3;
  background: rgba(57, 185, 138, 0.14);
}

.shell-dark .card-icon.blue {
  color: #8dc2ff;
  background: rgba(78, 145, 232, 0.15);
}

.shell-dark .card-icon.orange {
  color: #f5bd70;
  background: rgba(232, 163, 64, 0.15);
}

.shell-dark .card-icon.coral {
  color: #ff9a9a;
  background: rgba(241, 120, 120, 0.15);
}

.card-title-wrap h2,
.preview-heading h2 {
  margin: 0;
  color: var(--ink);
  font-size: 15px;
  font-weight: 750;
  letter-spacing: -0.02em;
}

.card-title-wrap p {
  margin: 4px 0 0;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.45;
}

.card-status {
  padding: 5px 8px;
  color: #32956f;
  font-size: 10px;
  font-weight: 750;
  background: #e8f8f0;
  border-radius: 7px;
}

.shell-dark .card-status {
  color: #73d9b3;
  background: rgba(57, 185, 138, 0.13);
}

.theme-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 11px;
  margin-top: 23px;
}

.theme-choice {
  min-width: 0;
  padding: 9px;
  text-align: left;
  background: var(--surface-muted);
  border: 1px solid var(--line);
  border-radius: 14px;
  transition: border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
}

.theme-choice:hover {
  border-color: var(--line-strong);
  transform: translateY(-1px);
}

.theme-choice.is-selected {
  border-color: rgba(112, 101, 235, 0.65);
  box-shadow: 0 0 0 3px rgba(112, 101, 235, 0.1);
}

.theme-thumbnail {
  display: flex;
  height: 69px;
  gap: 6px;
  padding: 8px;
  overflow: hidden;
  border: 1px solid rgba(25, 31, 53, 0.08);
  border-radius: 9px;
}

.theme-thumbnail.light {
  background: #fff;
}

.theme-thumbnail.dim {
  background: #eceff4;
}

.theme-thumbnail.dark {
  background: #161c2d;
  border-color: rgba(255, 255, 255, 0.08);
}

.thumb-sidebar {
  width: 25%;
  flex: 0 0 25%;
  border-radius: 4px;
}

.light .thumb-sidebar {
  background: #eeedff;
}

.dim .thumb-sidebar {
  background: #dce2ec;
}

.dark .thumb-sidebar {
  background: #242c43;
}

.thumb-content {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 5px;
  padding: 4px 2px;
}

.thumb-content i {
  display: block;
  height: 4px;
  background: #d9dde7;
  border-radius: 99px;
}

.thumb-content i:nth-child(1) {
  width: 64%;
  height: 6px;
  background: #aeb5c5;
}

.thumb-content i:nth-child(2) {
  width: 90%;
}

.thumb-content i:nth-child(3) {
  width: 73%;
}

.dark .thumb-content i {
  background: #3a455e;
}

.dark .thumb-content i:nth-child(1) {
  background: #7b87a1;
}

.theme-choice-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 7px;
  padding: 9px 2px 1px;
}

.theme-choice-copy {
  display: grid;
  min-width: 0;
  gap: 3px;
}

.theme-choice-copy strong {
  color: var(--ink);
  font-size: 11px;
  font-weight: 720;
}

.theme-choice-copy small {
  overflow: hidden;
  color: var(--muted);
  font-size: 9px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.theme-radio {
  display: grid;
  flex: 0 0 auto;
  width: 17px;
  height: 17px;
  place-items: center;
  color: #fff;
  background: transparent;
  border: 1px solid var(--line-strong);
  border-radius: 50%;
}

.theme-choice.is-selected .theme-radio {
  background: var(--accent);
  border-color: var(--accent);
}

.subsection {
  margin-top: 26px;
  padding-top: 22px;
  border-top: 1px solid var(--line);
}

.subsection-heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 15px;
}

.subsection-heading h3 {
  margin: 0;
  color: var(--ink);
  font-size: 12px;
  font-weight: 730;
}

.subsection-heading p {
  margin: 4px 0 0;
  color: var(--muted);
  font-size: 10px;
}

.accent-name {
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
}

.accent-options {
  display: flex;
  gap: 10px;
  margin-top: 16px;
}

.accent-option {
  display: grid;
  width: 31px;
  height: 31px;
  padding: 4px;
  place-items: center;
  background: transparent;
  border: 2px solid transparent;
  border-radius: 50%;
  transition: border-color 160ms ease, transform 160ms ease;
}

.accent-option:hover {
  transform: scale(1.08);
}

.accent-option.is-selected {
  border-color: var(--ink);
}

.accent-dot {
  display: block;
  width: 100%;
  height: 100%;
  border-radius: 50%;
  box-shadow: inset 0 0 0 1px rgba(0, 0, 0, 0.08);
}

.setting-list {
  display: grid;
  margin-top: 18px;
}

.toggle-row {
  display: flex;
  width: 100%;
  align-items: center;
  gap: 15px;
  min-height: 65px;
  padding: 12px 0;
  color: var(--ink);
  text-align: left;
  background: transparent;
  border-top: 1px solid var(--line);
}

.toggle-row:first-child {
  padding-top: 5px;
  border-top: 0;
}

.toggle-copy {
  display: grid;
  flex: 1;
  gap: 4px;
}

.toggle-copy strong {
  font-size: 12px;
  font-weight: 700;
}

.toggle-copy small {
  color: var(--muted);
  font-size: 10px;
  line-height: 1.45;
}

.toggle-track {
  display: flex;
  width: 40px;
  height: 23px;
  flex: 0 0 auto;
  align-items: center;
  padding: 3px;
  background: var(--line-strong);
  border-radius: 99px;
  transition: background 160ms ease;
}

.toggle-thumb {
  display: block;
  width: 17px;
  height: 17px;
  background: #fff;
  border-radius: 50%;
  box-shadow: 0 2px 5px rgba(22, 29, 49, 0.18);
  transition: transform 160ms ease;
}

.toggle-row.is-on .toggle-track {
  background: var(--accent);
}

.toggle-row.is-on .toggle-thumb {
  transform: translateX(17px);
}

.field-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
  margin-top: 24px;
}

.field {
  display: grid;
  gap: 8px;
}

.field-label {
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
}

.select-wrap {
  position: relative;
  display: block;
}

.select-wrap select {
  width: 100%;
  height: 39px;
  appearance: none;
  padding: 0 30px 0 11px;
  color: var(--ink);
  font-size: 11px;
  background: var(--surface-muted);
  border: 1px solid var(--line);
  border-radius: 10px;
  outline: none;
}

.select-wrap select:hover {
  border-color: var(--line-strong);
}

.select-wrap svg {
  position: absolute;
  top: 50%;
  right: 10px;
  color: var(--muted);
  pointer-events: none;
  transform: translateY(-50%);
}

.editor-sample {
  margin-top: 22px;
  padding: 16px 17px;
  color: var(--ink);
  background: var(--surface-muted);
  border: 1px solid var(--line);
  border-radius: 12px;
}

.sample-label {
  display: block;
  margin-bottom: 8px;
  color: var(--accent);
  font-family: Inter, ui-sans-serif, sans-serif;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.editor-sample p {
  margin: 0;
  letter-spacing: -0.02em;
}

.text-button {
  padding: 6px 2px;
  color: var(--accent);
  font-size: 11px;
  font-weight: 700;
  background: transparent;
}

.text-button:hover {
  color: var(--ink);
}

.shortcut-list {
  margin-top: 21px;
  border-top: 1px solid var(--line);
}

.shortcut-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  min-height: 55px;
  color: var(--ink);
  font-size: 12px;
  border-bottom: 1px solid var(--line);
}

.key-combo {
  display: flex;
  gap: 5px;
}

kbd {
  display: inline-grid;
  min-width: 25px;
  height: 24px;
  padding: 0 6px;
  place-items: center;
  color: var(--muted);
  font-family: inherit;
  font-size: 10px;
  font-weight: 700;
  background: var(--surface-muted);
  border: 1px solid var(--line-strong);
  border-bottom-width: 2px;
  border-radius: 6px;
}

.shortcut-footer,
.notification-preview,
.privacy-note {
  display: flex;
  align-items: center;
  gap: 10px;
  color: var(--muted);
  font-size: 10px;
}

.shortcut-footer {
  padding-top: 19px;
}

.shortcut-footer svg {
  color: var(--accent);
}

.notification-preview,
.privacy-note {
  margin-top: 23px;
  padding: 13px;
  background: var(--surface-muted);
  border: 1px solid var(--line);
  border-radius: 12px;
}

.notification-icon,
.privacy-icon {
  display: grid;
  flex: 0 0 auto;
  width: 31px;
  height: 31px;
  place-items: center;
  color: var(--accent);
  background: var(--accent-soft);
  border-radius: 9px;
}

.notification-preview strong,
.privacy-note strong {
  display: block;
  margin-bottom: 3px;
  color: var(--ink);
  font-size: 11px;
  font-weight: 700;
}

.notification-preview p,
.privacy-note p {
  margin: 0;
  font-size: 10px;
  line-height: 1.4;
}

.profile-card {
  display: flex;
  align-items: center;
  gap: 13px;
  margin-top: 22px;
  padding: 16px;
  background: var(--surface-muted);
  border: 1px solid var(--line);
  border-radius: 14px;
}

.profile-large {
  display: grid;
  width: 46px;
  height: 46px;
  flex: 0 0 auto;
  place-items: center;
  color: #4d3c88;
  font-size: 13px;
  font-weight: 800;
  background: linear-gradient(145deg, #f4d8bd, #ddad9b);
  border-radius: 14px;
}

.profile-copy {
  display: grid;
  flex: 1;
  gap: 4px;
}

.profile-copy strong {
  color: var(--ink);
  font-size: 12px;
}

.profile-copy span {
  color: var(--muted);
  font-size: 10px;
}

.outline-button {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 10px;
  color: var(--ink);
  font-size: 10px;
  font-weight: 700;
  background: var(--surface);
  border: 1px solid var(--line-strong);
  border-radius: 8px;
}

.outline-button:hover {
  border-color: var(--accent);
}

.preview-column {
  position: sticky;
  top: 24px;
  display: grid;
  gap: 13px;
}

.preview-card {
  position: relative;
  overflow: hidden;
  padding: 20px;
  background: linear-gradient(145deg, var(--surface) 0%, var(--surface-muted) 100%);
  border: 1px solid var(--line);
  border-radius: 21px;
  box-shadow: 0 16px 38px rgba(34, 42, 76, 0.07);
}

.preview-glow {
  position: absolute;
  top: -80px;
  right: -45px;
  width: 190px;
  height: 190px;
  background: var(--preview-accent-soft);
  border-radius: 50%;
  filter: blur(4px);
  opacity: 0.82;
}

.preview-header,
.preview-bottom,
.note-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.preview-heading {
  display: grid;
  gap: 6px;
}

.preview-heading h2 {
  font-size: 16px;
}

.preview-more {
  position: relative;
  z-index: 1;
  width: 30px;
  height: 30px;
  color: var(--muted);
}

.note-preview {
  position: relative;
  z-index: 1;
  margin-top: 19px;
  padding: 17px 16px 14px;
  color: #273047;
  background: #fff;
  border: 1px solid rgba(34, 44, 72, 0.08);
  border-radius: 16px;
  box-shadow: 0 12px 24px rgba(34, 42, 76, 0.09);
}

.preview-dim .note-preview {
  color: #2e3548;
  background: #f6f7fa;
}

.preview-dark .note-preview {
  color: #edf0f8;
  background: #20283b;
  border-color: rgba(255, 255, 255, 0.08);
  box-shadow: 0 12px 24px rgba(0, 0, 0, 0.22);
}

.note-meta {
  display: flex;
  align-items: center;
  gap: 6px;
  color: #8a92a3;
  font-size: 9px;
  font-weight: 650;
}

.preview-dark .note-meta {
  color: #8d98b0;
}

.note-bullet {
  width: 6px;
  height: 6px;
  background: var(--preview-accent);
  border-radius: 50%;
}

.meta-separator {
  color: #bbc1cd;
  font-size: 12px;
}

.note-title-row {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  margin-top: 19px;
}

.note-file-icon {
  display: grid;
  width: 29px;
  height: 29px;
  flex: 0 0 auto;
  place-items: center;
  color: var(--preview-accent);
  background: var(--preview-accent-soft);
  border-radius: 9px;
}

.note-label {
  display: block;
  margin: 1px 0 4px;
  color: #9299aa;
  font-size: 9px;
  font-weight: 700;
}

.preview-dark .note-label {
  color: #929db4;
}

.note-preview h3 {
  max-width: 195px;
  margin: 0;
  font-size: 16px;
  font-weight: 760;
  letter-spacing: -0.045em;
  line-height: 1.14;
}

.note-body {
  margin: 16px 0 0;
  color: #717a8d;
  font-size: 10px;
  line-height: 1.65;
}

.preview-dark .note-body {
  color: #9ba5ba;
}

.note-highlight {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 15px;
  padding: 10px 10px 10px 9px;
  color: #646d82;
  font-size: 10px;
  font-weight: 650;
  background: var(--preview-accent-soft);
  border-left: 3px solid var(--preview-accent);
  border-radius: 0 8px 8px 0;
}

.note-highlight svg {
  flex: 0 0 auto;
  color: var(--preview-accent);
}

.preview-dark .note-highlight {
  color: #b1b9ca;
}

.note-divider {
  height: 1px;
  margin: 17px 0 12px;
  background: rgba(38, 48, 72, 0.09);
}

.preview-dark .note-divider {
  background: rgba(255, 255, 255, 0.1);
}

.note-checklist {
  display: grid;
  gap: 9px;
}

.check-line {
  display: flex;
  align-items: center;
  gap: 8px;
  color: #697388;
  font-size: 10px;
}

.preview-dark .check-line {
  color: #abb4c6;
}

.check-box {
  display: grid;
  width: 14px;
  height: 14px;
  flex: 0 0 auto;
  place-items: center;
  color: #fff;
  border: 1px solid #cdd3de;
  border-radius: 4px;
}

.check-box.checked {
  background: var(--preview-accent);
  border-color: var(--preview-accent);
}

.note-footer {
  margin-top: 17px;
  color: #9ba2b1;
  font-size: 9px;
}

.note-footer span:first-child {
  display: flex;
  align-items: center;
  gap: 4px;
}

.preview-bottom {
  position: relative;
  z-index: 1;
  margin-top: 15px;
  color: var(--muted);
  font-size: 9px;
  font-weight: 650;
}

.preview-sync {
  display: flex;
  align-items: center;
  gap: 6px;
}

.preview-accent-label {
  color: var(--preview-accent);
}

.preview-tip {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 13px 14px;
  border-radius: 14px;
}

.tip-icon {
  display: grid;
  width: 28px;
  height: 28px;
  flex: 0 0 auto;
  place-items: center;
  color: var(--accent);
  background: var(--accent-soft);
  border-radius: 9px;
}

.preview-tip strong {
  display: block;
  margin: 1px 0 3px;
  color: var(--ink);
  font-size: 10px;
  font-weight: 750;
}

.preview-tip p {
  margin: 0;
  color: var(--muted);
  font-size: 10px;
  line-height: 1.4;
}

.accent-violet {
  --preview-accent: #7568f5;
  --preview-accent-soft: #eeecff;
}

.accent-coral {
  --preview-accent: #f17878;
  --preview-accent-soft: #ffebeb;
}

.accent-mint {
  --preview-accent: #39b98a;
  --preview-accent-soft: #e4f8f0;
}

.accent-blue {
  --preview-accent: #4e91e8;
  --preview-accent-soft: #e8f2ff;
}

.accent-amber {
  --preview-accent: #e8a340;
  --preview-accent-soft: #fff3df;
}

.preview-dark.accent-violet {
  --preview-accent-soft: rgba(117, 104, 245, 0.18);
}

.preview-dark.accent-coral {
  --preview-accent-soft: rgba(241, 120, 120, 0.17);
}

.preview-dark.accent-mint {
  --preview-accent-soft: rgba(57, 185, 138, 0.17);
}

.preview-dark.accent-blue {
  --preview-accent-soft: rgba(78, 145, 232, 0.18);
}

.preview-dark.accent-amber {
  --preview-accent-soft: rgba(232, 163, 64, 0.17);
}

.save-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-top: 24px;
  padding: 12px 13px 12px 16px;
  border-radius: 15px;
}

.save-status {
  gap: 8px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 600;
}

.save-status svg {
  color: #4fc493;
}

.save-button {
  gap: 7px;
  min-height: 36px;
  padding: 0 14px;
  color: #fff;
  font-size: 11px;
  font-weight: 750;
  background: var(--accent);
  border-radius: 10px;
  box-shadow: 0 7px 15px rgba(112, 101, 235, 0.22);
  transition: transform 160ms ease, box-shadow 160ms ease, background 160ms ease;
}

.save-button:hover {
  background: #6257dc;
  box-shadow: 0 9px 19px rgba(112, 101, 235, 0.3);
  transform: translateY(-1px);
}

.save-button.saved {
  background: #37a77d;
  box-shadow: 0 7px 15px rgba(55, 167, 125, 0.22);
}

@media (max-width: 1080px) {
  .app-shell {
    grid-template-columns: 78px minmax(0, 1fr);
  }

  .sidebar {
    align-items: center;
    padding: 27px 11px 17px;
  }

  .brand {
    padding: 0;
  }

  .brand-copy,
  .workspace-details,
  .workspace-switcher > svg,
  .nav-label,
  .nav-text,
  .sidebar-callout,
  .profile-meta,
  .footer-dot {
    display: none;
  }

  .workspace-switcher {
    min-height: 0;
    margin-top: 31px;
    padding: 7px;
    border-radius: 12px;
  }

  .sidebar-nav {
    width: 100%;
    margin-top: 36px;
  }

  .nav-item {
    justify-content: center;
    min-height: 43px;
    padding: 0;
  }

  .active-mark {
    position: absolute;
    right: -11px;
    width: 3px;
  }

  .sidebar-footer {
    width: 100%;
    justify-content: center;
    padding: 14px 0 1px;
  }

  .settings-layout {
    grid-template-columns: minmax(0, 1fr);
  }

  .preview-column {
    position: static;
    grid-template-columns: minmax(0, 1fr) minmax(220px, 0.55fr);
  }
}

@media (max-width: 760px) {
  .app-shell {
    display: block;
    overflow: visible;
  }

  .sidebar {
    display: flex;
    min-height: 70px;
    height: 70px;
    flex-direction: row;
    justify-content: space-between;
    padding: 16px 18px;
  }

  .brand {
    gap: 10px;
  }

  .brand-copy {
    display: inline;
  }

  .workspace-switcher,
  .sidebar-nav,
  .sidebar-spacer,
  .sidebar-callout {
    display: none;
  }

  .sidebar-footer {
    width: auto;
    padding: 0;
    border-top: 0;
  }

  .profile-meta,
  .footer-dot {
    display: none;
  }

  .topbar {
    height: 67px;
    padding: 0 20px;
  }

  .help-button span {
    display: none;
  }

  .help-button {
    width: 35px;
    justify-content: center;
    padding: 0;
  }

  .page-content {
    padding: 32px 20px 28px;
  }

  .page-intro {
    align-items: flex-start;
    flex-direction: column;
    gap: 15px;
    margin-bottom: 26px;
  }

  .page-intro h1 {
    font-size: 32px;
  }

  .theme-grid,
  .field-grid {
    grid-template-columns: 1fr;
  }

  .theme-thumbnail {
    height: 56px;
  }

  .preview-column {
    grid-template-columns: 1fr;
  }

  .preview-tip {
    display: none;
  }

  .save-bar {
    align-items: stretch;
    flex-direction: column;
  }

  .save-button {
    justify-content: center;
  }
}

@media (max-width: 430px) {
  .panel-card {
    padding: 19px 17px;
    border-radius: 17px;
  }

  .card-title-wrap {
    gap: 10px;
  }

  .card-icon {
    width: 35px;
    height: 35px;
    border-radius: 10px;
  }

  .card-title-wrap p {
    max-width: 205px;
  }

  .profile-card {
    align-items: flex-start;
    flex-wrap: wrap;
  }

  .outline-button {
    width: 100%;
    justify-content: center;
    margin-top: 3px;
  }

  .shortcut-row {
    align-items: flex-start;
    flex-direction: column;
    justify-content: center;
    gap: 8px;
    padding: 12px 0;
  }
}

