function getInitials(name: string) {
  const initials = name
    .split(' ')
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0])
    .join('')
    .toUpperCase();

  return initials || 'SC';
}

type ToggleRowProps = {
  title: string;
  description: string;
  checked: boolean;
  onChange: () => void;
  icon?: IconName;
};

function ToggleRow({ title, description, checked, onChange, icon = 'checkSquare' }: ToggleRowProps) {
  return (
    <div className='toggle-row'>
      <span className='toggle-icon'>
        <Icon name={icon} size={17} />
      </span>
      <span className='toggle-copy'>
        <strong>{title}</strong>
        <span>{description}</span>
      </span>
      <button
        type='button'
        className={`switch ${checked ? 'is-on' : ''}`}
        role='switch'
        aria-checked={checked}
        aria-label={title}
        onClick={onChange}
      >
        <span className='switch-thumb' />
      </button>
    </div>
  );
}

type SettingsSectionProps = {
  kicker: string;
  title: string;
  description: string;
  children: ReactNode;
  action?: ReactNode;
};

function SettingsSection({ kicker, title, description, children, action }: SettingsSectionProps) {
  return (
    <section className='settings-section'>
      <div className='section-heading'>
        <div>
          <span className='section-kicker'>{kicker}</span>
          <h3>{title}</h3>
          <p>{description}</p>
        </div>
        {action ? <div className='section-action'>{action}</div> : null}
      </div>
      {children}
    </section>
  );
}

type SelectFieldProps = {
  label: string;
  value: string;
  options: string[];
  hint?: string;
  onChange: (value: string) => void;
};

function SelectField({ label, value, options, hint, onChange }: SelectFieldProps) {
  return (
    <label className='field'>
      <span className='field-label'>{label}</span>
      <span className='select-control'>
        <select value={value} onChange={(event) => onChange(event.target.value)}>
          {options.map((option) => (
            <option key={option} value={option}>
              {option}
            </option>
          ))}
        </select>
        <Icon name='chevronDown' size={16} />
      </span>
      {hint ? <span className='field-hint'>{hint}</span> : null}
    </label>
  );
}

