          />
          <ToggleRow
            title='Spell check'
            description='Catch small slips before they become part of the note.'
            icon='type'
            checked={toggles.spellCheck}
            onChange={() => onToggle('spellCheck')}
          />
          <ToggleRow
            title='Focus mode'
