type AppearanceSettingsProps = {
  theme: ThemeChoice;
  onThemeChange: (theme: ThemeChoice) => void;
  density: number;
  onDensityChange: (density: number) => void;
};

function AppearanceSettings({ theme, onThemeChange, density, onDensityChange }: AppearanceSettingsProps) {
  return (
    <div className='settings-sections'>
      <SettingsSection
        kicker='THEME'
        title='Choose your atmosphere'
        description='Your theme follows you across every notebook and device.'
      >
        <div className='theme-grid'>
          {themeOptions.map((option) => (
            <button
              type='button'
              key={option.id}
              className={`theme-option ${theme === option.id ? 'is-selected' : ''}`}
              onClick={() => onThemeChange(option.id)}
              aria-pressed={theme === option.id}
            >
              <span className={`theme-icon theme-icon-${option.id}`}>
                <Icon name={option.icon} size={19} />
              </span>
              <span className='theme-copy'>
