  margin: 0 auto;
  padding: 35px 0 29px;
}

.eyebrow {
  color: var(--accent);
}

.page-heading h1 {
  margin: 8px 0 6px;
  color: var(--ink);
  font-size: clamp(29px, 3vw, 36px);
  font-weight: 760;
  letter-spacing: -0.055em;
  line-height: 1;
}

.page-heading p {
  margin: 0;
  color: var(--ink-soft);
  font-size: 13px;
}

.heading-actions {
  gap: 15px;
  padding-bottom: 1px;
}

.save-state {
  gap: 7px;
  color: var(--ink-faint);
  font-size: 11px;
  font-weight: 650;
  white-space: nowrap;
}

.save-state.is-saved {
  color: var(--success);
}

.save-state-dot,
.sync-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--teal);
  box-shadow: 0 0 0 3px rgba(69, 188, 168, 0.12);
}

.save-state.is-saved .save-state-dot {
  background: var(--success);
}

.primary-button {
  min-height: 37px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 0 15px;
  border-radius: 9px;
  background: var(--accent);
  color: #fff;
  font-size: 11px;
  font-weight: 740;
  cursor: pointer;
  box-shadow: 0 8px 17px rgba(108, 89, 215, 0.18);
  transition: transform 160ms ease, background 160ms ease, box-shadow 160ms ease;
}

.primary-button:hover {
  background: var(--accent-strong);
  box-shadow: 0 10px 22px rgba(108, 89, 215, 0.25);
  transform: translateY(-1px);
}

.primary-button.is-saved {
  background: var(--success);
  box-shadow: 0 8px 17px rgba(49, 155, 131, 0.18);
}

.settings-layout {
  max-width: 1120px;
  display: grid;
  grid-template-columns: 218px minmax(0, 1fr);
  align-items: start;
  gap: 25px;
  margin: 0 auto;
}

.settings-menu {
  padding-top: 6px;
}

.menu-heading {
  padding: 0 11px 14px;
  color: var(--ink-faint);
  font-size: 10px;
  letter-spacing: 0.01em;
  text-transform: none;
}

.settings-menu-items {
  display: grid;
  gap: 4px;
}

.settings-menu-item {
  width: 100%;
  min-height: 58px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 8px 10px;
  border: 1px solid transparent;
  border-radius: 12px;
  background: transparent;
  color: var(--ink-soft);
  text-align: left;
  cursor: pointer;
  transition: background 160ms ease, border-color 160ms ease, color 160ms ease, transform 160ms ease;
}

.settings-menu-item:hover {
  background: var(--surface-muted);
  color: var(--ink);
}

.settings-menu-item.is-active {
  border-color: rgba(108, 89, 215, 0.14);
  background: var(--surface);
  color: var(--accent);
  box-shadow: 0 8px 20px rgba(48, 55, 77, 0.05);
}

.menu-item-leading {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 10px;
}

.menu-item-icon {
  width: 31px;
  height: 31px;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  border-radius: 9px;
  background: var(--surface-strong);
  color: var(--ink-soft);
}

.settings-menu-item.is-active .menu-item-icon {
  background: var(--accent-soft);
  color: var(--accent);
}

.menu-item-copy {
  min-width: 0;
  display: grid;
  gap: 3px;
}

.menu-item-copy strong {
  overflow: hidden;
  color: inherit;
  font-size: 12px;
  font-weight: 720;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.menu-item-copy small {
  overflow: hidden;
  color: var(--ink-faint);
  font-size: 10px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.settings-menu-item > .icon {
  color: var(--ink-faint);
}

.settings-menu-item.is-active > .icon {
  color: var(--accent);
}

.help-card {
  position: relative;
  margin-top: 27px;
  padding: 16px 15px 15px;
  overflow: hidden;
  border: 1px solid rgba(108, 89, 215, 0.14);
  border-radius: 14px;
  background: linear-gradient(145deg, var(--accent-pale), var(--surface));
}

.help-card::after {
  content: '';
  position: absolute;
  top: -26px;
  right: -26px;
  width: 80px;
  height: 80px;
  border: 1px solid rgba(108, 89, 215, 0.13);
  border-radius: 50%;
  box-shadow: 0 0 0 12px rgba(108, 89, 215, 0.035), 0 0 0 24px rgba(108, 89, 215, 0.025);
}

.help-card-icon {
  width: 27px;
  height: 27px;
  display: grid;
  place-items: center;
  margin-bottom: 13px;
  border-radius: 8px;
  background: var(--accent-soft);
  color: var(--accent);
}

.help-card strong {
  display: block;
  color: var(--ink);
  font-size: 12px;
  font-weight: 740;
}

.help-card p {
  max-width: 150px;
  margin: 5px 0 13px;
  color: var(--ink-soft);
  font-size: 10px;
  line-height: 1.5;
}

.help-link,
.text-button {
  gap: 6px;
  padding: 0;
  background: transparent;
  color: var(--accent);
  font-size: 10px;
  font-weight: 730;
  cursor: pointer;
}

.help-link:hover,
.text-button:hover {
  color: var(--accent-strong);
}

.settings-card {
  min-width: 0;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 19px;
  background: var(--surface);
  box-shadow: var(--shadow);
}

.settings-card-header {
  min-height: 119px;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  padding: 27px 31px 25px;
  border-bottom: 1px solid var(--line);
}

.card-kicker {
  color: var(--accent);
}

.settings-card-header h2 {
  margin: 7px 0 5px;
  color: var(--ink);
  font-size: 23px;
  font-weight: 750;
  letter-spacing: -0.04em;
  line-height: 1.1;
}

.settings-card-header p {
  margin: 0;
  color: var(--ink-soft);
  font-size: 11px;
  line-height: 1.5;
}

.sync-badge {
  gap: 7px;
  padding: 7px 9px;
  border: 1px solid var(--line);
  border-radius: 99px;
  color: var(--ink-soft);
  font-size: 10px;
  font-weight: 650;
  white-space: nowrap;
}

.sync-dot {
  width: 6px;
  height: 6px;
  box-shadow: none;
}

.settings-body {
  padding: 0 31px;
}

.settings-sections {
  display: grid;
}

.settings-section {
  padding: 27px 0 28px;
  border-bottom: 1px solid var(--line);
}

.settings-section:first-child {
  padding-top: 25px;
}

.settings-section:last-child {
  border-bottom: 0;
}

.section-heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
  margin-bottom: 18px;
}

.section-kicker {
  color: var(--ink-faint);
  font-size: 9px;
}

.section-heading h3 {
  margin: 6px 0 4px;
  color: var(--ink);
  font-size: 15px;
  font-weight: 740;
  letter-spacing: -0.025em;
}

.section-heading p {
  max-width: 490px;
  margin: 0;
  color: var(--ink-soft);
  font-size: 11px;
  line-height: 1.55;
}

.identity-card {
  min-height: 76px;
  display: flex;
  align-items: center;
  gap: 13px;
  margin-bottom: 17px;
  padding: 11px 13px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: linear-gradient(110deg, var(--surface-muted), var(--surface));
}

.identity-copy {
  gap: 4px;
}

.identity-copy strong {
  color: var(--ink);
  font-size: 12px;
  font-weight: 740;
}

.identity-copy span {
  color: var(--ink-soft);
  font-size: 10px;
}

.identity-card .text-button {
  margin-left: auto;
}

.form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
}

.field {
  min-width: 0;
  display: grid;
  align-content: start;
  gap: 7px;
}

.field-label {
  color: var(--ink-soft);
  font-size: 10px;
  font-weight: 720;
}

.field input,
.field select {
  width: 100%;
  height: 38px;
  border: 1px solid var(--line-strong);
  border-radius: 9px;
  outline: 0;
  background: var(--surface);
  color: var(--ink);
  font-size: 11px;
  transition: border-color 160ms ease, box-shadow 160ms ease;
}

.field input {
  padding: 0 12px;
}

.field input::placeholder {
  color: var(--ink-faint);
}

.field input:focus,
.field select:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(108, 89, 215, 0.11);
}

.field input[readonly] {
  color: var(--ink-soft);
}

.input-with-icon,
.select-control {
  position: relative;
  display: block;
}

.input-with-icon > .icon {
  position: absolute;
  top: 11px;
  left: 12px;
  z-index: 1;
  color: var(--ink-faint);
}

.input-with-icon input {
  padding-left: 37px;
}

.select-control select {
  appearance: none;
  padding: 0 35px 0 12px;
  cursor: pointer;
}

.select-control > .icon {
  position: absolute;
  top: 11px;
  right: 11px;
  pointer-events: none;
  color: var(--ink-faint);
}

.field-hint {
  min-height: 14px;
  color: var(--ink-faint);
  font-size: 10px;
  line-height: 1.4;
}

.inline-note {
  gap: 7px;
  margin-top: 15px;
  color: var(--teal);
  font-size: 10px;
  font-weight: 650;
}

.toggle-list {
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 13px;
}

.toggle-row {
  min-height: 67px;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 11px 14px;
}

.toggle-row + .toggle-row {
  border-top: 1px solid var(--line);
}

.toggle-icon {
  width: 32px;
  height: 32px;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  border-radius: 9px;
  background: var(--accent-soft);
  color: var(--accent);
}

.toggle-copy {
  min-width: 0;
  display: grid;
  gap: 4px;
}

.toggle-copy strong {
  color: var(--ink);
  font-size: 11px;
  font-weight: 720;
}

.toggle-copy > span {
  overflow: hidden;
  color: var(--ink-soft);
  font-size: 10px;
  line-height: 1.4;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.switch {
  position: relative;
  width: 38px;
  height: 22px;
  flex: 0 0 auto;
  margin-left: auto;
  padding: 0;
  border-radius: 99px;
  background: var(--surface-strong);
  box-shadow: inset 0 0 0 1px var(--line-strong);
  cursor: pointer;
  transition: background 160ms ease, box-shadow 160ms ease;
}

.switch.is-on {
  background: var(--accent);
  box-shadow: inset 0 0 0 1px var(--accent);
}

.switch-thumb {
  position: absolute;
  top: 3px;
  left: 3px;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: #fff;
  box-shadow: 0 2px 4px rgba(23, 31, 48, 0.18);
  transition: transform 160ms ease;
}

.switch.is-on .switch-thumb {
  transform: translateX(16px);
}

.settings-footer {
  min-height: 57px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  padding: 14px 31px;
  background: var(--surface-muted);
  color: var(--ink-faint);
}

.footer-note,
.footer-shortcut {
  gap: 7px;
  font-size: 10px;
}

.footer-note .icon {
  color: var(--teal);
}

.footer-shortcut {
  gap: 4px;
}

.footer-shortcut kbd + kbd {
  margin-left: 1px;
}

.shortcut-card {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px;
  border: 1px solid var(--line);
  border-radius: 13px;
  background: var(--surface-muted);
}

.shortcut-icon {
  width: 36px;
  height: 36px;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  border-radius: 10px;
  background: var(--surface);
  color: var(--accent);
  box-shadow: 0 4px 10px rgba(38, 47, 69, 0.06);
}

.shortcut-copy {
  gap: 4px;
}

.shortcut-copy strong {
  color: var(--ink);
  font-size: 11px;
  font-weight: 730;
}

.shortcut-copy span {
  color: var(--ink-soft);
  font-size: 10px;
}

.shortcut-keys {
  display: flex;
  gap: 12px;
  margin-left: auto;
}

.shortcut-keys > span {
  display: grid;
  grid-template-columns: auto auto;
  gap: 3px;
}

.shortcut-keys kbd {
  min-width: 20px;
  padding: 4px 5px;
  border: 1px solid var(--line-strong);
  border-bottom-width: 2px;
  border-radius: 5px;
  background: var(--surface);
  color: var(--ink-soft);
  font-size: 10px;
  line-height: 1;
  text-align: center;
}

.shortcut-keys small {
  grid-column: 1 / -1;
  margin-top: 3px;
  color: var(--ink-faint);
  font-size: 9px;
  text-align: center;
}

.editor-tip {
  display: flex;
  align-items: center;
  gap: 9px;
  margin: 22px 0 26px;
  padding: 11px 13px;
  border: 1px solid rgba(69, 188, 168, 0.18);
  border-radius: 10px;
  background: rgba(69, 188, 168, 0.08);
  color: var(--ink-soft);
  font-size: 10px;
}

.editor-tip strong {
  color: var(--teal);
  font-weight: 740;
}

.tip-icon {
  color: var(--teal);
}

.editor-tip code {
  padding: 2px 4px;
  border-radius: 4px;
  background: rgba(69, 188, 168, 0.12);
  color: var(--ink);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 9px;
}

.theme-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.theme-option {
  position: relative;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 11px 10px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--surface-muted);
  color: var(--ink);
  text-align: left;
  cursor: pointer;
  transition: border-color 160ms ease, background 160ms ease, box-shadow 160ms ease, transform 160ms ease;
}

.theme-option:hover {
  border-color: var(--line-strong);
  transform: translateY(-1px);
}

.theme-option.is-selected {
  border-color: var(--accent);
  background: var(--accent-pale);
  box-shadow: 0 6px 16px rgba(108, 89, 215, 0.1);
}

.theme-icon {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  border-radius: 10px;
}

.theme-icon-system {
  background: #e9e8ff;
  color: #6c59d7;
}

.theme-icon-light {
  background: #fff3cf;
  color: #bf861c;
}

.theme-icon-dark {
  background: #34364b;
  color: #b9b4ff;
}

.theme-copy {
  min-width: 0;
  display: grid;
  gap: 3px;
}

.theme-copy strong,
.theme-copy small {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.theme-copy strong {
  color: var(--ink);
  font-size: 11px;
  font-weight: 730;
}

.theme-copy small {
  color: var(--ink-faint);
  font-size: 9px;
}

.radio-dot {
  width: 13px;
  height: 13px;
  flex: 0 0 auto;
  margin-left: auto;
  border: 1px solid var(--line-strong);
  border-radius: 50%;
  background: var(--surface);
}

.theme-option.is-selected .radio-dot {
  border: 4px solid var(--accent);
}

.range-heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 15px;
}

.range-heading > span {
  display: grid;
  gap: 4px;
}

.range-heading strong {
  color: var(--ink);
  font-size: 11px;
  font-weight: 730;
}

.range-heading small {
  color: var(--ink-soft);
  font-size: 10px;
}

.range-value {
  color: var(--accent) !important;
  font-size: 12px !important;
}

.range-wrap {
  position: relative;
  height: 18px;
  display: flex;
  align-items: center;
}

.range-wrap::before,
.range-progress {
  position: absolute;
  left: 0;
  right: 0;
  height: 6px;
  border-radius: 99px;
}

.range-wrap::before {
  content: '';
  background: var(--surface-strong);
}

.range-progress {
  right: auto;
  background: linear-gradient(90deg, var(--accent), #a18cf0 74%, var(--teal));
}

.range-input {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 18px;
  margin: 0;
  appearance: none;
  background: transparent;
  cursor: pointer;
}

.range-input::-webkit-slider-thumb {
  width: 16px;
  height: 16px;
  appearance: none;
  border: 3px solid var(--surface);
  border-radius: 50%;
  background: var(--accent);
  box-shadow: 0 2px 6px rgba(64, 51, 133, 0.3);
}

.range-input::-moz-range-thumb {
  width: 12px;
  height: 12px;
  border: 2px solid var(--surface);
  border-radius: 50%;
  background: var(--accent);
  box-shadow: 0 2px 6px rgba(64, 51, 133, 0.3);
}

.range-labels {
  display: flex;
  justify-content: space-between;
  margin-top: 3px;
  color: var(--ink-faint);
  font-size: 9px;
}

.preview-card {
  min-height: 137px;
  padding: 17px 18px 16px;
  border: 1px solid #e7e1d5;
  border-radius: 14px;
  background: #fffdf8;
  color: #36343b;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.7);
}

.preview-card.preview-is-dark {
  border-color: #47495b;
  background: #282a36;
  color: #edeef5;
}

.preview-topline {
  display: flex;
  justify-content: space-between;
  color: #9d988e;
  font-size: 9px;
}

.preview-is-dark .preview-topline {
  color: #898da1;
}

.preview-notebook {
  display: flex;
  align-items: center;
  gap: 6px;
}

.preview-color-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #d99562;
}

.preview-card h4 {
  margin: 14px 0 6px;
  color: inherit;
  font-size: 16px;
  font-weight: 740;
  letter-spacing: -0.035em;
}

.preview-card p {
  max-width: 420px;
  margin: 0;
  color: #77736d;
  font-family: Georgia, serif;
  font-size: 11px;
  line-height: 1.5;
}

.preview-is-dark p {
  color: #b0b1be;
}

.preview-rule {
  height: 1px;
  margin: 13px 0 9px;
  background: #eee9df;
}

.preview-is-dark .preview-rule {
  background: #414351;
}

.preview-lines {
  display: grid;
  gap: 5px;
}

.preview-lines span {
  width: 62%;
  height: 4px;
  border-radius: 99px;
  background: #e9e4db;
}

.preview-lines span:nth-child(2) {
  width: 78%;
}

.preview-lines .is-short {
  width: 43%;
}

.preview-is-dark .preview-lines span {
  background: #494b5b;
}

.quiet-hours-card {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px;
  border: 1px solid var(--line);
  border-radius: 13px;
  background: var(--surface-muted);
}

.quiet-hours-icon {
  width: 36px;
  height: 36px;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  border-radius: 10px;
  background: #e9e7ff;
  color: #6c59d7;
}

.theme-dark .quiet-hours-icon {
  background: #393452;
  color: #b2a7ff;
}

.quiet-hours-copy {
  gap: 4px;
}

.quiet-hours-copy strong {
  color: var(--ink);
  font-size: 11px;
  font-weight: 730;
}

.quiet-hours-copy span {
  color: var(--ink-soft);
  font-size: 10px;
}

.status-pill {
  margin-left: auto;
  padding: 5px 8px;
  border-radius: 99px;
  background: var(--surface-strong);
  color: var(--ink-faint);
  font-size: 9px;
  font-weight: 720;
}

.quiet-hours-card .text-button {
  margin-left: 4px;
}

.notification-footnote {
  display: flex;
  align-items: center;
  gap: 7px;
  margin: 23px 0 26px;
  color: var(--ink-faint);
  font-size: 10px;
}

.notification-footnote .icon {
  color: var(--teal);
}

@media (max-width: 1100px) {
  .main-content {
    padding-right: 28px;
    padding-left: 28px;
  }

  .settings-layout,
  .page-heading {
    max-width: 100%;
  }
}

@media (max-width: 880px) {
  .sidebar {
    width: 215px;
    flex-basis: 215px;
  }

  .settings-layout {
    grid-template-columns: 184px minmax(0, 1fr);
    gap: 17px;
