}

.save-button.is-saved {
  color: var(--accent);
  background: var(--accent-soft);
  box-shadow: none;
}

.save-button.is-saved:hover {
  box-shadow: none;
}

.intro-strip {
  position: relative;
  overflow: hidden;
  min-height: 88px;
  display: flex;
  align-items: center;
  gap: 14px;
  margin-bottom: 20px;
  padding: 18px 21px;
  background: linear-gradient(107deg, var(--accent-wash), rgba(var(--accent-rgb), 0.015) 60%), var(--panel);
  border: 1px solid rgba(var(--accent-rgb), 0.14);
  border-radius: 17px;
  box-shadow: var(--shadow-soft);
}

.intro-icon {
  width: 42px;
  height: 42px;
  z-index: 1;
  display: grid;
  flex: 0 0 auto;
  place-items: center;
  color: var(--accent);
  background: var(--accent-soft);
  border: 1px solid rgba(var(--accent-rgb), 0.13);
  border-radius: 13px;
}

.intro-copy {
  z-index: 1;
}

.intro-copy strong {
  display: block;
  color: var(--text);
  font-size: 13px;
  font-weight: 730;
}

.intro-copy p {
  margin: 4px 0 0;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.4;
}

.intro-meta {
  z-index: 1;
  display: flex;
  align-items: center;
  gap: 17px;
  margin-left: auto;
}

.intro-meta-item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--muted-strong);
  font-size: 10px;
  font-weight: 620;
  white-space: nowrap;
}

.intro-meta-item .icon {
  color: var(--accent);
}

.intro-decoration {
  position: absolute;
  z-index: 0;
  display: block;
  border: 1px solid rgba(var(--accent-rgb), 0.11);
  border-radius: 50%;
}

.intro-decoration-one {
  right: 92px;
  bottom: -43px;
  width: 130px;
  height: 130px;
}

.intro-decoration-two {
  right: 38px;
  bottom: -75px;
  width: 160px;
  height: 160px;
}

.settings-columns {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 296px;
  align-items: start;
  gap: 20px;
}

.settings-stack,
.aside-stack {
  min-width: 0;
  display: grid;
  gap: 18px;
}

.aside-stack {
  position: sticky;
  top: 24px;
}

.panel-card,
.side-card {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 17px;
  box-shadow: var(--shadow-soft);
}

.panel-card {
  padding: 25px 26px;
}

.section-header {
  margin-bottom: 22px;
}

.section-header h2,
.side-card h2,
.empty-panel h2,
.no-results h2 {
  margin: 6px 0 5px;
  color: var(--text);
  font-size: 17px;
  font-weight: 740;
  letter-spacing: -0.025em;
}

.section-header p,
.data-actions p,
.danger-zone p,
.help-card p,
.empty-panel p,
.no-results p {
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.5;
}

.profile-row {
  display: flex;
  align-items: center;
  gap: 13px;
  padding-top: 2px;
}

.profile-copy {
  min-width: 0;
  flex: 1;
}

.profile-name {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--text);
  font-size: 13px;
  font-weight: 720;
}

.profile-email {
  margin-top: 4px;
  overflow: hidden;
  color: var(--muted);
  font-size: 11px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.verified-mark {
  width: 16px;
  height: 16px;
  display: inline-grid;
  place-items: center;
  color: #fff;
  background: var(--accent);
  border-radius: 50%;
}

.profile-actions {
  display: flex;
  align-items: center;
  gap: 17px;
}

.plan-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 8px;
  color: var(--accent);
  font-size: 10px;
  font-weight: 700;
  background: var(--accent-soft);
  border-radius: 7px;
}

.plan-dot {
  width: 5px;
  height: 5px;
  background: var(--accent);
  border-radius: 50%;
}

.text-button {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 0;
  color: var(--muted-strong);
  font-size: 11px;
  font-weight: 650;
  background: transparent;
}

.text-button:hover {
  color: var(--accent);
}

.settings-list {
  display: grid;
}

.setting-row {
  min-height: 70px;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 0;
  border-top: 1px solid var(--line);
}

.setting-row:first-child {
  padding-top: 0;
  border-top: 0;
}

.setting-row.last {
  padding-bottom: 0;
}

.setting-icon {
  width: 31px;
  height: 31px;
  display: grid;
  flex: 0 0 auto;
  place-items: center;
  color: var(--muted-strong);
  background: var(--panel-quiet);
  border: 1px solid var(--line);
  border-radius: 9px;
}

.setting-copy {
  min-width: 0;
  flex: 1;
}

.setting-title {
  color: var(--text);
  font-size: 12px;
  font-weight: 680;
}

.setting-description {
  margin-top: 4px;
  color: var(--muted);
  font-size: 10px;
  line-height: 1.35;
}

.setting-control {
  margin-left: auto;
  padding-left: 12px;
}

.select-control {
  position: relative;
  display: block;
}

.select-control select {
  width: 154px;
  height: 35px;
  appearance: none;
  padding: 0 31px 0 11px;
  color: var(--text);
  font-size: 11px;
  background: var(--input);
  border: 1px solid var(--line);
  border-radius: 8px;
  outline: 0;
  cursor: pointer;
}

.select-control select:hover {
  border-color: var(--line-strong);
}

.select-control select:focus {
  border-color: rgba(var(--accent-rgb), 0.55);
  box-shadow: 0 0 0 3px var(--accent-soft);
}

.select-control > .icon {
  position: absolute;
  top: 50%;
  right: 10px;
  color: var(--muted);
  pointer-events: none;
  transform: translateY(-50%);
}

.toggle {
  width: 42px;
  height: 24px;
  display: flex;
  align-items: center;
  padding: 3px;
  background: var(--line-strong);
  border-radius: 20px;
  transition: background 160ms ease, box-shadow 160ms ease;
}

.toggle:hover {
  box-shadow: 0 0 0 3px rgba(var(--accent-rgb), 0.07);
}

.toggle.is-on {
  background: var(--accent);
}

.toggle-knob {
  width: 18px;
  height: 18px;
  display: block;
  background: #fff;
  border-radius: 50%;
  box-shadow: 0 2px 4px rgba(19, 24, 40, 0.2);
  transition: transform 160ms ease;
}

.toggle.is-on .toggle-knob {
  transform: translateX(18px);
}

.field-label {
  color: var(--text);
  font-size: 11px;
  font-weight: 700;
}

.field-help {
  margin-top: 4px;
  color: var(--muted);
  font-size: 10px;
}

.theme-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
  margin-top: 10px;
}

.theme-choice {
  position: relative;
  min-width: 0;
  display: grid;
  gap: 9px;
  padding: 8px;
  color: var(--muted-strong);
  text-align: left;
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 11px;
  transition: border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
}

.theme-choice:hover {
  border-color: var(--line-strong);
  transform: translateY(-1px);
}

.theme-choice.is-selected {
  border-color: rgba(var(--accent-rgb), 0.65);
  box-shadow: 0 0 0 3px var(--accent-soft);
}

.theme-choice-label {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 0 3px 1px;
  color: var(--text);
  font-size: 10px;
  font-weight: 680;
}

.theme-choice-label .icon {
  color: var(--accent);
}

.selected-check {
  position: absolute;
  top: 7px;
  right: 7px;
  width: 17px;
  height: 17px;
  display: grid;
  place-items: center;
  color: #fff;
  background: var(--accent);
  border-radius: 50%;
}

.theme-preview {
  height: 61px;
  display: grid;
  grid-template-columns: 22px 1fr;
  overflow: hidden;
  border: 1px solid rgba(41, 48, 70, 0.1);
  border-radius: 7px;
}

.theme-preview.light {
  background: #f8f9fc;
}

.theme-preview.dim {
  background: #e9ecf1;
}

.theme-preview.dark {
  background: #202633;
  border-color: rgba(255, 255, 255, 0.08);
}

.theme-preview-sidebar {
  display: block;
  background: #edeef5;
  border-right: 1px solid rgba(41, 48, 70, 0.08);
}

.theme-preview.dim .theme-preview-sidebar {
  background: #dde1e9;
}

.theme-preview.dark .theme-preview-sidebar {
  background: #171c27;
  border-right-color: rgba(255, 255, 255, 0.06);
}

.theme-preview-content {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 11px 8px;
}

.theme-preview-line {
  width: 72%;
  height: 4px;
  display: block;
  background: #d6dae5;
  border-radius: 4px;
}

.theme-preview-line.wide {
  width: 91%;
  height: 6px;
  background: #b3b9c8;
}

.theme-preview-line.short {
  width: 48%;
}

.theme-preview-line.accent-line {
  width: 62%;
  background: var(--accent);
  opacity: 0.68;
}

.theme-preview.dark .theme-preview-line {
  background: #495365;
}

.theme-preview.dark .theme-preview-line.wide {
  background: #8e98aa;
}

.theme-preview.dark .theme-preview-line.accent-line {
  background: var(--accent);
}

.accent-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  margin-top: 22px;
  padding-top: 19px;
  border-top: 1px solid var(--line);
}

.accent-options {
  display: flex;
  align-items: center;
  gap: 9px;
}

.accent-dot {
  width: 25px;
  height: 25px;
  display: grid;
  place-items: center;
  padding: 0;
  border: 2px solid transparent;
  border-radius: 50%;
  transition: transform 160ms ease, box-shadow 160ms ease;
}

.accent-dot:hover {
  transform: scale(1.1);
}

.accent-dot > span {
  width: 100%;
  height: 100%;
  display: grid;
  place-items: center;
  color: #fff;
  border: 2px solid var(--panel);
  border-radius: 50%;
}

.accent-dot.is-selected {
  box-shadow: 0 0 0 2px var(--panel), 0 0 0 4px var(--accent);
}

.accent-violet {
  background: #6c61e2;
}

.accent-mint {
  background: #239d80;
}

.accent-coral {
  background: #de6b65;
}

.accent-blue {
  background: #367cd0;
}

.data-actions,
.danger-zone {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
}

.data-actions {
  margin-top: 21px;
  padding-top: 20px;
  border-top: 1px solid var(--line);
}

.data-actions p,
.danger-zone p {
  margin-top: 4px;
}

.secondary-button,
.danger-button {
  min-height: 34px;
  padding: 0 11px;
  color: var(--muted-strong);
  font-size: 10px;
  font-weight: 700;
  background: var(--panel-quiet);
  border: 1px solid var(--line);
}

.secondary-button:hover {
  color: var(--accent);
  border-color: rgba(var(--accent-rgb), 0.35);
  background: var(--accent-soft);
  transform: translateY(-1px);
}

.danger-zone {
  margin-top: 14px;
  padding-top: 15px;
  border-top: 1px dashed var(--line-strong);
}

.danger-label {
  color: var(--danger);
}

.danger-button {
  color: var(--danger);
  background: var(--danger-soft);
  border-color: rgba(209, 92, 106, 0.18);
}

.danger-button:hover {
  border-color: rgba(209, 92, 106, 0.36);
  transform: translateY(-1px);
}

.side-card {
  padding: 18px;
}

.side-card-heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
}

.side-card-heading h2 {
  margin-top: 6px;
}

.side-card-heading > .icon {
  color: var(--accent);
}

.preview-status {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 5px 7px;
  color: var(--success);
  font-size: 9px;
  font-weight: 700;
  background: rgba(43, 154, 104, 0.09);
  border-radius: 6px;
}

.preview-status span {
  width: 5px;
  height: 5px;
  background: var(--success);
  border-radius: 50%;
}

.preview-window {
  overflow: hidden;
  margin-top: 15px;
  color: #252a3b;
  background: #fbfbfd;
  border: 1px solid #e4e6ed;
  border-radius: 12px;
  box-shadow: 0 10px 22px rgba(37, 43, 68, 0.09);
}

.preview-window.dim {
  color: #313847;
  background: #eef0f3;
  border-color: #dce0e7;
}

.preview-window.dark {
  color: #edf0f5;
  background: #252c39;
  border-color: #353e4f;
  box-shadow: 0 10px 22px rgba(0, 0, 0, 0.18);
}

.preview-toolbar {
  height: 28px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 9px;
  color: #9aa2b1;
  background: rgba(236, 238, 244, 0.6);
  border-bottom: 1px solid rgba(56, 64, 84, 0.08);
}

.preview-window.dim .preview-toolbar {
  background: rgba(221, 225, 232, 0.62);
}

.preview-window.dark .preview-toolbar {
  background: #1d2330;
  border-bottom-color: rgba(255, 255, 255, 0.06);
}

.traffic-lights {
  display: flex;
  gap: 3px;
}

.traffic-lights i {
  width: 4px;
  height: 4px;
  display: block;
  background: #c6cad4;
  border-radius: 50%;
}

.traffic-lights i:first-child {
  background: #eeaa8f;
}

.traffic-lights i:nth-child(2) {
  background: #e5c882;
}

.traffic-lights i:last-child {
  background: #9dceb2;
}

.preview-toolbar-title {
  margin-left: 18px;
  font-size: 8px;
  font-weight: 650;
}

.preview-toolbar-menu {
  letter-spacing: 1px;
}

.preview-page {
  min-height: 166px;
  padding: 18px 17px 17px;
}

.preview-date {
  color: #9da4b3;
  font-size: 7px;
  font-weight: 750;
  letter-spacing: 0.13em;
}

.preview-window.dark .preview-date {
  color: #8b95a7;
}

.preview-title {
  margin-top: 12px;
  color: inherit;
  font-family: Georgia, 'Times New Roman', serif;
  font-size: 17px;
  font-weight: 500;
  letter-spacing: -0.035em;
}

.preview-rule {
  width: 100%;
  height: 1px;
  margin: 12px 0 13px;
  background: rgba(71, 79, 100, 0.12);
}

.preview-window.dark .preview-rule {
  background: rgba(255, 255, 255, 0.1);
}

.preview-text {
  color: #6f7787;
  font-family: Georgia, 'Times New Roman', serif;
  font-size: 9px;
  line-height: 1.5;
}

.preview-window.dark .preview-text {
  color: #aeb6c5;
}

.preview-highlight {
  width: 82%;
  height: 7px;
  margin-top: 13px;
  background: rgba(var(--accent-rgb), 0.16);
  border-radius: 3px;
}

.preview-line {
  height: 4px;
  margin-top: 8px;
  background: #d7dbe4;
  border-radius: 3px;
}

.preview-window.dark .preview-line {
  background: #4e5869;
}

.preview-line-long {
  width: 94%;
}

.preview-line-medium {
  width: 76%;
}

.preview-line-short {
  width: 47%;
}

.preview-card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-top: 13px;
  color: var(--muted);
  font-size: 9px;
}

.preview-card-footer > span:first-child {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.mini-accent {
  width: 7px;
  height: 7px;
  display: inline-block;
  border-radius: 50%;
}

.shortcut-list {
  display: grid;
  gap: 1px;
  margin-top: 14px;
}

.shortcut-row {
  min-height: 35px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  color: var(--muted-strong);
  font-size: 10px;
  border-bottom: 1px solid var(--line);
}

.shortcut-row:last-child {
  border-bottom: 0;
}

.key-combo {
  display: flex;
  gap: 4px;
}

.key-combo kbd {
  min-width: 20px;
  height: 19px;
  display: inline-grid;
  place-items: center;
  padding: 0 5px;
  color: var(--muted-strong);
  font-size: 9px;
  line-height: 1;
  background: var(--panel-quiet);
  border: 1px solid var(--line-strong);
  border-bottom-width: 2px;
  border-radius: 5px;
}

.help-card {
  position: relative;
  overflow: hidden;
  min-height: 190px;
  color: #fff;
  background: linear-gradient(145deg, rgba(var(--accent-rgb), 0.98), rgba(var(--accent-rgb), 0.72));
  border-color: rgba(var(--accent-rgb), 0.55);
  box-shadow: 0 17px 31px rgba(var(--accent-rgb), 0.17);
}

.help-card::after {
  position: absolute;
  right: -43px;
  bottom: -54px;
  width: 150px;
  height: 150px;
  content: '';
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-radius: 50%;
  box-shadow: 0 0 0 19px rgba(255, 255, 255, 0.04), 0 0 0 39px rgba(255, 255, 255, 0.035);
}

.help-card .side-kicker {
  position: relative;
  z-index: 1;
  color: rgba(255, 255, 255, 0.66);
}

.help-card h2 {
  position: relative;
  z-index: 1;
  max-width: 180px;
  margin-top: 8px;
  color: #fff;
  font-size: 18px;
  line-height: 1.08;
}

.help-card p {
  position: relative;
  z-index: 1;
  max-width: 205px;
  margin-top: 9px;
  color: rgba(255, 255, 255, 0.72);
}

.help-button {
  position: relative;
  z-index: 1;
  min-height: 32px;
  margin-top: 15px;
  padding: 0 10px;
  color: var(--accent);
  font-size: 10px;
  font-weight: 730;
  background: #fff;
  border: 1px solid rgba(255, 255, 255, 0.8);
}

.help-button:hover {
  transform: translateY(-1px);
  box-shadow: 0 7px 15px rgba(33, 34, 68, 0.16);
}

.help-orbit {
  position: absolute;
  top: 17px;
  right: 19px;
  width: 45px;
  height: 45px;
  border: 1px solid rgba(255, 255, 255, 0.22);
  border-radius: 50%;
}

.help-orbit::before,
.help-orbit::after {
  position: absolute;
  content: '';
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 50%;
}

.help-orbit::before {
  inset: 6px;
}

.help-orbit::after {
  inset: 14px;
}

.help-orbit span {
  position: absolute;
  width: 5px;
  height: 5px;
  display: block;
  background: rgba(255, 255, 255, 0.75);
  border-radius: 50%;
}

.help-orbit span:first-child {
  top: -2px;
  left: 19px;
}

.help-orbit span:nth-child(2) {
  right: -2px;
  bottom: 10px;
}

.help-orbit span:last-child {
  bottom: 2px;
  left: 7px;
}

.empty-panel,
.no-results {
  min-height: 375px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
}

.empty-icon {
  width: 47px;
  height: 47px;
  display: grid;
  place-items: center;
  color: var(--accent);
  background: var(--accent-soft);
  border: 1px solid rgba(var(--accent-rgb), 0.14);
  border-radius: 14px;
}

.empty-panel .card-kicker,
.no-results h2 {
  margin-top: 17px;
}

.empty-panel h2,
.no-results h2 {
  margin-bottom: 6px;
}

.empty-panel p,
.no-results p {
  max-width: 310px;
}

.empty-panel .secondary-button,
.no-results .secondary-button {
  margin-top: 20px;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  padding: 0;
  margin: -1px;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@media (max-width: 1160px) {
  .content-shell {
    width: calc(100% - 48px);
  }

  .topbar {
    padding-right: 24px;
    padding-left: 24px;
  }
}

@media (max-width: 980px) {
  .settings-columns {
    grid-template-columns: 1fr;
  }

  .aside-stack {
    position: static;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

