* {
  box-sizing: border-box;
}

:root {
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  color: #242635;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
  background: #eceef4;
}

button,
select {
  font: inherit;
}

button,
a,
select {
  -webkit-tap-highlight-color: transparent;
}

button,
a {
  transition: background-color 160ms ease, border-color 160ms ease, color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
}

button {
  border: 0;
}

a {
  color: inherit;
  text-decoration: none;
}

button:focus-visible,
a:focus-visible,
select:focus-visible {
  outline: 3px solid color-mix(in srgb, var(--accent) 36%, transparent);
  outline-offset: 2px;
}

.app-shell {
  --accent: #7669e8;
  --accent-soft: #f0eeff;
  --accent-ink: #5d52c9;
  --ink: #242635;
  --muted: #858a9d;
  --subtle: #a1a6b6;
  --line: #e8e9f0;
  --frame-line: #dde0eb;
  --main-bg: #ffffff;
  --sidebar-bg: #fbfbfe;
  --card-bg: #ffffff;
  --control-bg: #fbfbfd;
  --soft-bg: #f6f7fa;
  --shadow: 0 28px 70px rgba(48, 52, 88, 0.14), 0 5px 16px rgba(48, 52, 88, 0.06);
  min-height: 100vh;
  padding: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--ink);
  background: radial-gradient(circle at 14% 18%, rgba(214, 210, 255, 0.52), transparent 27%), radial-gradient(circle at 87% 83%, rgba(207, 236, 228, 0.5), transparent 28%), #eceef4;
}

.app-shell.accent-coral {
  --accent: #ee826d;
  --accent-soft: #fff0ec;
  --accent-ink: #ca5b48;
}

.app-shell.accent-mint {
  --accent: #43b996;
  --accent-soft: #e9f8f3;
  --accent-ink: #258b70;
}

.app-shell.accent-blue {
  --accent: #5b8de8;
  --accent-soft: #edf3ff;
  --accent-ink: #3b6fc8;
}

.app-shell.theme-dark {
  --ink: #f1f2f8;
  --muted: #a5aabd;
  --subtle: #777d91;
  --line: #2c3040;
  --frame-line: #34394b;
  --main-bg: #151721;
  --sidebar-bg: #1b1e2a;
  --card-bg: #1b1e2a;
  --control-bg: #191c27;
  --soft-bg: #202433;
  --shadow: 0 28px 70px rgba(3, 5, 14, 0.42), 0 5px 16px rgba(3, 5, 14, 0.22);
  background: radial-gradient(circle at 14% 18%, rgba(80, 72, 164, 0.23), transparent 28%), radial-gradient(circle at 87% 83%, rgba(40, 110, 91, 0.18), transparent 30%), #11131c;
}

.app-shell.theme-dark.accent-coral {
  --accent-soft: #382622;
  --accent-ink: #ff9e8b;
}

.app-shell.theme-dark.accent-mint {
  --accent-soft: #19352f;
  --accent-ink: #6dd5b3;
}

.app-shell.theme-dark.accent-blue {
  --accent-soft: #1e2e4b;
  --accent-ink: #8eaff5;
}

.app-frame {
  width: min(1160px, 100%);
  height: min(790px, calc(100vh - 64px));
  min-height: 680px;
  display: grid;
  grid-template-columns: 244px minmax(0, 1fr);
  overflow: hidden;
  background: var(--main-bg);
  border: 1px solid var(--frame-line);
  border-radius: 28px;
  box-shadow: var(--shadow);
}

.sidebar {
  display: flex;
  flex-direction: column;
  min-width: 0;
  padding: 28px 16px 18px;
  background: var(--sidebar-bg);
  border-right: 1px solid var(--line);
}

.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 0 10px;
}

.brand-mark {
  width: 32px;
  height: 32px;
  display: grid;
  place-items: center;
  color: #fff;
  background: var(--accent);
  border-radius: 10px;
  box-shadow: 0 7px 15px color-mix(in srgb, var(--accent) 26%, transparent);
}

.brand-name {
  font-size: 17px;
  font-weight: 750;
  letter-spacing: -0.055em;
}

.workspace-picker {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 28px;
  padding: 10px;
  color: var(--ink);
  text-align: left;
  cursor: pointer;
  background: transparent;
  border: 1px solid transparent;
  border-radius: 13px;
}

.workspace-picker:hover {
  background: var(--soft-bg);
  border-color: var(--line);
}

.workspace-avatar,
.profile-avatar {
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  color: #fff;
  font-weight: 750;
  letter-spacing: -0.03em;
}

.workspace-avatar {
  width: 31px;
  height: 31px;
  font-size: 13px;
  background: linear-gradient(145deg, #f1a587, #d96e8e);
  border-radius: 10px;
}

.workspace-copy,
.profile-copy,
.sync-copy {
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.workspace-copy {
  flex: 1;
  gap: 2px;
}

.workspace-name,
.profile-name {
  overflow: hidden;
  font-size: 12px;
  font-weight: 700;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.workspace-kind,
.profile-email {
  overflow: hidden;
  color: var(--muted);
  font-size: 10px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.workspace-picker > svg {
  flex: 0 0 auto;
  color: var(--muted);
}

.sidebar-nav {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 28px;
  margin-top: 30px;
}

.nav-group {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.nav-label,
.heading-eyebrow,
.preview-date {
  color: var(--subtle);
  font-size: 9px;
  font-weight: 750;
  letter-spacing: 0.15em;
  text-transform: uppercase;
}

.nav-label {
  padding: 0 12px 6px;
}

.nav-item {
  position: relative;
  display: flex;
  align-items: center;
  gap: 11px;
  min-height: 40px;
  padding: 0 12px;
  color: var(--muted);
  font-size: 12px;
  font-weight: 650;
  border-radius: 11px;
}

.nav-item:hover {
  color: var(--ink);
  background: var(--soft-bg);
}

.nav-item.is-active {
  color: var(--accent-ink);
  background: var(--accent-soft);
}

.nav-icon {
  width: 19px;
  height: 19px;
  display: grid;
  place-items: center;
}

.nav-indicator {
  width: 4px;
  height: 4px;
  margin-left: auto;
  background: var(--accent);
  border-radius: 50%;
}

.sidebar-bottom {
  display: flex;
  flex-direction: column;
  gap: 15px;
}

.plan-card {
  display: flex;
  flex-direction: column;
  padding: 15px;
  background: linear-gradient(145deg, var(--accent-soft), var(--soft-bg));
  border: 1px solid color-mix(in srgb, var(--accent) 16%, var(--line));
  border-radius: 15px;
}

.plan-icon {
  width: 25px;
  height: 25px;
  display: grid;
  place-items: center;
  margin-bottom: 11px;
  color: var(--accent-ink);
  background: var(--main-bg);
  border-radius: 8px;
}

.plan-title {
  font-size: 11px;
  font-weight: 750;
}

.plan-copy {
  margin-top: 3px;
  color: var(--muted);
  font-size: 10px;
}

.usage-bar {
  height: 4px;
  margin: 11px 0 12px;
  overflow: hidden;
  background: color-mix(in srgb, var(--accent) 15%, transparent);
  border-radius: 99px;
}

.usage-bar span {
  display: block;
  width: 48%;
  height: 100%;
  background: var(--accent);
  border-radius: inherit;
}

.plan-link {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  width: fit-content;
  color: var(--accent-ink);
  font-size: 10px;
  font-weight: 750;
}

.plan-link:hover {
  color: var(--accent);
}

.profile-row {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 8px 7px;
  color: var(--ink);
  text-align: left;
  cursor: pointer;
  background: transparent;
  border-radius: 12px;
}

.profile-row:hover {
  background: var(--soft-bg);
}

.profile-avatar {
  width: 28px;
  height: 28px;
  font-size: 9px;
  background: #252a3b;
  border-radius: 50%;
}

.profile-copy {
  flex: 1;
  gap: 2px;
}

.profile-row > svg {
  color: var(--muted);
}

.main-content {
  min-width: 0;
  overflow-y: auto;
  padding: 34px 42px 22px;
  background: var(--main-bg);
  scrollbar-width: thin;
  scrollbar-color: var(--line) transparent;
}

.main-content::-webkit-scrollbar {
  width: 7px;
}

.main-content::-webkit-scrollbar-thumb {
  background: var(--line);
  border: 2px solid var(--main-bg);
  border-radius: 99px;
}

.main-topline,
.breadcrumbs,
.workspace-state,
.heading-actions,
.save-status,
.field-heading,
.preview-toolbar,
.footer-note,
.compact-setting,
.sync-card,
.sync-badge {
  display: flex;
  align-items: center;
}

.main-topline {
  justify-content: space-between;
  gap: 20px;
}

.breadcrumbs {
  gap: 7px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 600;
}

.breadcrumbs svg {
  color: var(--subtle);
}

.breadcrumb-current {
  color: var(--ink);
}

.workspace-state {
  gap: 7px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 600;
}

.state-dot,
.status-dot,
.preview-pulse,
.live-dot {
  display: inline-block;
  flex: 0 0 auto;
  border-radius: 50%;
}

.state-dot {
  width: 6px;
  height: 6px;
  background: #55bc8a;
  box-shadow: 0 0 0 3px rgba(85, 188, 138, 0.12);
}

.heading-row {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 24px;
  padding: 25px 0 28px;
}

.heading-copy {
  min-width: 0;
}

.heading-eyebrow {
  color: var(--accent-ink);
}

.heading-copy h1 {
  margin: 8px 0 6px;
  color: var(--ink);
  font-size: clamp(28px, 3vw, 35px);
  font-weight: 760;
  letter-spacing: -0.055em;
  line-height: 1;
}

.heading-copy p {
  margin: 0;
  color: var(--muted);
  font-size: 12px;
}

.heading-actions {
  flex: 0 0 auto;
  gap: 16px;
}

.save-status {
  gap: 7px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 650;
  white-space: nowrap;
}

.status-dot {
  width: 6px;
  height: 6px;
  background: #59bf8d;
}

.save-status.is-dirty .status-dot {
  background: #efa45b;
  box-shadow: 0 0 0 3px rgba(239, 164, 91, 0.13);
}

.save-button {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 38px;
  padding: 0 13px;
  color: #fff;
  font-size: 11px;
  font-weight: 750;
  cursor: pointer;
  background: var(--accent);
  border: 1px solid var(--accent);
  border-radius: 10px;
  box-shadow: 0 7px 14px color-mix(in srgb, var(--accent) 23%, transparent);
}

.save-button:hover {
  transform: translateY(-1px);
  box-shadow: 0 10px 18px color-mix(in srgb, var(--accent) 28%, transparent);
}

.save-button.is-saved {
  color: var(--muted);
  cursor: default;
  background: var(--soft-bg);
  border-color: var(--line);
  box-shadow: none;
}

.save-button.is-saved:hover {
  transform: none;
  box-shadow: none;
}

.save-key {
  margin-left: 2px;
  padding-left: 9px;
  color: rgba(255, 255, 255, 0.72);
  font-size: 10px;
  font-weight: 600;
  border-left: 1px solid rgba(255, 255, 255, 0.28);
}

.content-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.08fr) minmax(285px, 0.92fr);
  gap: 18px;
  align-items: start;
}

.side-stack {
  display: flex;
  flex-direction: column;
  gap: 16px;
  min-width: 0;
}

.settings-card,
.sync-card {
  border: 1px solid var(--line);
  box-shadow: 0 5px 16px rgba(45, 48, 78, 0.025);
}

.settings-card {
  background: var(--card-bg);
  border-radius: 19px;
}

.editor-card,
.appearance-card {
  padding: 25px 25px 23px;
}

.card-heading h2 {
  margin: 16px 0 6px;
  color: var(--ink);
  font-size: 17px;
  font-weight: 740;
  letter-spacing: -0.035em;
}

.card-heading p {
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.5;
}

.section-tag {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--accent-ink);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.tag-icon {
  width: 27px;
  height: 27px;
  display: grid;
  place-items: center;
  color: var(--accent-ink);
  background: var(--accent-soft);
  border-radius: 8px;
}

.settings-list {
  margin-top: 23px;
  border-top: 1px solid var(--line);
}

.setting-row {
  min-height: 72px;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 14px;
  border-bottom: 1px solid var(--line);
}

.setting-copy {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.setting-title {
  color: var(--ink);
  font-size: 11px;
  font-weight: 700;
}

.setting-description {
  color: var(--muted);
  font-size: 10px;
  line-height: 1.35;
}

.select-shell {
  position: relative;
  display: block;
  width: 125px;
}

.select-shell select {
  width: 100%;
  appearance: none;
  padding: 9px 29px 9px 11px;
  color: var(--ink);
  font-size: 10px;
  font-weight: 650;
  cursor: pointer;
  background: var(--control-bg);
  border: 1px solid var(--line);
  border-radius: 9px;
}

.select-shell select:hover {
  border-color: color-mix(in srgb, var(--accent) 38%, var(--line));
}

.select-shell > svg {
  position: absolute;
  top: 50%;
  right: 9px;
  color: var(--muted);
  pointer-events: none;
  transform: translateY(-50%);
}

.toggle {
  position: relative;
  width: 39px;
  height: 23px;
  flex: 0 0 auto;
  padding: 3px;
  cursor: pointer;
  background: #dfe2eb;
  border-radius: 99px;
}

.theme-dark .toggle {
  background: #3b4050;
}

.toggle.is-on {
  background: var(--accent);
}

.toggle-thumb {
  display: block;
  width: 17px;
  height: 17px;
  background: #fff;
  border-radius: 50%;
  box-shadow: 0 1px 3px rgba(23, 26, 44, 0.18);
  transform: translateX(0);
  transition: transform 160ms ease;
}

.toggle.is-on .toggle-thumb {
  transform: translateX(16px);
}

.editor-preview {
  margin-top: 21px;
  padding: 12px;
  background: var(--soft-bg);
  border: 1px solid var(--line);
  border-radius: 14px;
}

.preview-toolbar {
  justify-content: space-between;
  gap: 12px;
  padding: 0 2px;
}

.preview-label,
.preview-mode {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: var(--muted);
  font-size: 9px;
  font-weight: 700;
}

.preview-pulse {
  width: 6px;
  height: 6px;
  background: var(--accent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 14%, transparent);
}

.preview-mode {
  color: var(--accent-ink);
  font-size: 9px;
}

.preview-paper {
  min-height: 115px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 9px;
  margin-top: 10px;
  padding: 18px 20px;
  background: var(--card-bg);
  border: 1px solid var(--line);
  border-radius: 11px;
  box-shadow: 0 3px 8px rgba(45, 48, 78, 0.035);
}

.preview-date {
  font-size: 8px;
  letter-spacing: 0.13em;
}

.preview-title {
  color: var(--ink);
  font-family: Georgia, 'Times New Roman', serif;
  font-size: 17px;
  font-weight: 600;
  letter-spacing: -0.025em;
}

.preview-line {
  display: block;
  height: 5px;
  background: color-mix(in srgb, var(--muted) 17%, transparent);
  border-radius: 99px;
}

.preview-line-long {
  width: 82%;
}

.preview-line-short {
  width: 57%;
}

.appearance-card {
  padding-bottom: 25px;
}

.theme-field {
  margin-top: 22px;
}

.field-heading {
  justify-content: space-between;
  gap: 14px;
}

.field-hint {
  color: var(--subtle);
  font-size: 9px;
  text-align: right;
}

.theme-options {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 7px;
  margin-top: 11px;
}

.theme-option {
  position: relative;
  min-width: 0;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 10px;
  padding: 11px 9px 10px;
  color: var(--muted);
  font-size: 9px;
  font-weight: 700;
  text-align: left;
  cursor: pointer;
  background: var(--control-bg);
  border: 1px solid var(--line);
  border-radius: 10px;
}

.theme-option:hover {
  color: var(--ink);
  border-color: color-mix(in srgb, var(--accent) 35%, var(--line));
}

.theme-option.is-selected {
  color: var(--accent-ink);
  background: var(--accent-soft);
  border-color: color-mix(in srgb, var(--accent) 47%, var(--line));
}

.theme-icon {
  width: 25px;
  height: 25px;
  display: grid;
  place-items: center;
  color: var(--muted);
  background: var(--soft-bg);
  border-radius: 8px;
}

.theme-option.is-selected .theme-icon {
  color: var(--accent-ink);
  background: var(--card-bg);
}

.theme-check {
  position: absolute;
  top: 9px;
  right: 8px;
  width: 17px;
  height: 17px;
  display: grid;
  place-items: center;
  color: #fff;
  opacity: 0;
  background: var(--accent);
  border-radius: 50%;
  transform: scale(0.7);
  transition: opacity 160ms ease, transform 160ms ease;
}

.theme-option.is-selected .theme-check {
  opacity: 1;
  transform: scale(1);
}

.color-field {
  margin-top: 23px;
  padding-top: 20px;
  border-top: 1px solid var(--line);
}

.accent-picker {
  display: flex;
  align-items: center;
  gap: 9px;
  margin-top: 12px;
}

.accent-option {
  width: 31px;
  height: 31px;
  display: grid;
  place-items: center;
  padding: 0;
  cursor: pointer;
  background: transparent;
  border: 1px solid transparent;
  border-radius: 50%;
}

.accent-option:hover {
  background: var(--soft-bg);
}

.accent-option.is-selected {
  border-color: color-mix(in srgb, var(--accent) 38%, var(--line));
}

.accent-swatch {
  width: 19px;
  height: 19px;
  display: block;
  border-radius: 50%;
  box-shadow: inset 0 0 0 1px rgba(0, 0, 0, 0.08);
}

.accent-option.is-selected .accent-swatch {
  box-shadow: 0 0 0 3px var(--card-bg), 0 0 0 4px var(--accent);
}

.selected-accent {
  margin-left: 4px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 650;
}

.notifications-card {
  padding: 21px 23px 18px;
}

.compact-heading h2 {
  margin-top: 13px;
  font-size: 15px;
}

.compact-settings {
  margin-top: 17px;
  border-top: 1px solid var(--line);
}

.compact-setting {
  justify-content: space-between;
  gap: 14px;
  min-height: 62px;
  border-bottom: 1px solid var(--line);
}

.compact-setting:last-child {
  border-bottom: 0;
}

.sync-card {
  gap: 11px;
  padding: 15px 17px;
  background: var(--soft-bg);
  border-radius: 15px;
}

.sync-icon {
  width: 32px;
  height: 32px;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  color: #2d9d71;
  background: #e8f7ef;
  border-radius: 10px;
}

.theme-dark .sync-icon {
  background: #19372e;
}

.sync-copy {
  gap: 3px;
}

.sync-title {
  color: var(--ink);
  font-size: 11px;
  font-weight: 750;
}

.sync-description {
  color: var(--muted);
  font-size: 9px;
}

.sync-badge {
  gap: 5px;
  margin-left: auto;
  padding: 5px 7px;
  color: #2d9d71;
  font-size: 9px;
  font-weight: 750;
  background: #e8f7ef;
  border-radius: 7px;
}

.theme-dark .sync-badge {
  background: #19372e;
}

.live-dot {
  width: 5px;
  height: 5px;
  background: #40b680;
}

.main-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  margin-top: 22px;
  padding-top: 17px;
  border-top: 1px solid var(--line);
}

.footer-note {
  gap: 8px;
  min-width: 0;
  color: var(--muted);
  font-size: 10px;
}

.footer-note strong {
  color: var(--ink);
  font-weight: 700;
}

.footer-note-icon {
  width: 25px;
  height: 25px;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  color: var(--accent-ink);
  background: var(--accent-soft);
  border-radius: 8px;
}

.reset-button {
  flex: 0 0 auto;
  padding: 6px 0 6px 8px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 650;
  cursor: pointer;
  background: transparent;
}

.reset-button:hover {
  color: var(--accent-ink);
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
