function PageIntro({ eyebrow, title, description, icon }: { eyebrow: string; title: string; description: string; icon: IconName }) {
  return (
    <div className='page-intro'>
      <div>
        <div className='eyebrow'>{eyebrow}</div>
        <h2>{title}</h2>
        <p>{description}</p>
      </div>
      <div className='intro-icon'>
        <Icon name={icon} size={24} strokeWidth={1.6} />
      </div>
    </div>
  );
}

function SectionBlock({ title, description, badge, children }: { title: string; description: string; badge?: string; children: ReactNode }) {
  return (
    <section className='section-block'>
      <div className='section-heading'>
        <div>
          <h3>{title}</h3>
          <p>{description}</p>
        </div>
        {badge ? <span className='section-badge'>{badge}</span> : null}
      </div>
      {children}
    </section>
  );
}

function SettingRow({ title, description, children, last = false }: { title: string; description: string; children: ReactNode; last?: boolean }) {
  return (
    <div className={`setting-row${last ? ' is-last' : ''}`}>
      <div className='setting-copy'>
        <div className='setting-title'>{title}</div>
        <div className='setting-description'>{description}</div>
      </div>
      <div className='setting-control'>{children}</div>
    </div>
  );
}

function SelectControl({ value, options, label, onChange }: { value: string; options: string[]; label: string; onChange: (value: string) => void }) {
  return (
    <label className='select-control'>
      <select value={value} aria-label={label} onChange={(event) => onChange(event.target.value)}>
        {options.map((option) => (
          <option key={option} value={option}>
            {option}
          </option>
        ))}
      </select>
      <span className='select-arrow'>
        <Icon name='chevron-down' size={15} />
      </span>
    </label>
  );
}

function SegmentedControl({ value, options, label, onChange }: { value: string; options: readonly string[]; label: string; onChange: (value: string) => void }) {
  return (
    <div className='segment-control' role='group' aria-label={label}>
      {options.map((option) => (
        <button key={option} type='button' className={value === option ? 'is-selected' : ''} aria-pressed={value === option} onClick={() => onChange(option)}>
          {option}
        </button>
      ))}
    </div>
  );
}

function Toggle({ checked, label, onChange }: { checked: boolean; label: string; onChange: (checked: boolean) => void }) {
  return (
    <button type='button' className={`toggle${checked ? ' is-on' : ''}`} aria-label={label} aria-pressed={checked} onClick={() => onChange(!checked)}>
      <span className='toggle-thumb' />
    </button>
  );
}

function SummaryRail({ theme, notebook, focusMode, accent }: { theme: Theme; notebook: string; focusMode: boolean; accent: Accent }) {
  const accentLabel = accentOptions.find((option) => option.id === accent)?.label ?? 'Moss';

