  gap: 9px;
  margin-top: 15px;
}

.current-setting {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.current-setting span {
  color: #9aa69e;
  font-size: 9px;
}

.current-setting strong {
  max-width: 98px;
  overflow: hidden;
  color: #5f7165;
  font-size: 9px;
  font-weight: 700;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tip-card {
  position: relative;
  min-height: 132px;
  margin-top: 15px;
  padding: 15px 16px;
  overflow: hidden;
  border: 1px solid #eee3cd;
  border-radius: 16px;
  background: #fcf6e9;
}

.tip-card::after {
  position: absolute;
  right: -22px;
  bottom: -26px;
  width: 78px;
  height: 78px;
  content: '';
  border: 1px solid rgba(205, 159, 75, 0.18);
  border-radius: 50%;
  box-shadow: 0 0 0 10px rgba(205, 159, 75, 0.05), 0 0 0 20px rgba(205, 159, 75, 0.04);
}

.tip-heading {
  display: flex;
  align-items: center;
  gap: 7px;
  color: #795f35;
  font-size: 10px;
  font-weight: 750;
}

.tip-icon {
  display: grid;
  width: 23px;
  height: 23px;
  place-items: center;
  color: #b58435;
  border-radius: 7px;
  background: #f3dfb4;
}

.tip-card p {
  max-width: 150px;
  margin: 11px 0 14px;
  color: #9a8158;
  font-size: 10px;
  line-height: 1.5;
}

.shortcut-chip {
  position: relative;
  z-index: 1;
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.shortcut-chip span {
  display: grid;
  width: 19px;
  height: 19px;
  place-items: center;
  color: #94703a;
  border: 1px solid #e7cf9e;
  border-radius: 5px;
  background: rgba(255, 252, 242, 0.72);
  font-size: 9px;
  font-weight: 750;
}

.action-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-top: 31px;
  padding-top: 20px;
  border-top: 1px solid #e5ebe3;
}

.footer-note {
  display: flex;
  align-items: center;
  gap: 7px;
  color: #93a097;
  font-size: 10px;
}

.footer-note svg {
  color: #769481;
}

.save-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-width: 121px;
  height: 36px;
  padding: 0 14px;
  color: #fff;
  border-radius: 9px;
  background: var(--accent-color);
  box-shadow: 0 5px 12px rgba(61, 112, 82, 0.18);
  font-size: 10px;
  font-weight: 750;
  transition: transform 160ms ease, filter 160ms ease, box-shadow 160ms ease;
}

.save-button:hover {
  filter: brightness(0.94);
  box-shadow: 0 7px 15px rgba(61, 112, 82, 0.24);
  transform: translateY(-1px);
}

.save-button:active {
  transform: translateY(0);
}

.save-button.is-saved {
  background: #547a64;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.app-frame.theme-dark .main-pane,
.app-frame.theme-dark .content-scroll {
  color: #e9f0e9;
  background: #1b2520;
}

.app-frame.theme-dark .topbar {
  border-color: #314238;
  background: rgba(27, 37, 32, 0.9);
}

.app-frame.theme-dark .breadcrumb,
.app-frame.theme-dark .topbar-title p,
.app-frame.theme-dark .page-intro p,
.app-frame.theme-dark .section-heading p,
.app-frame.theme-dark .setting-description,
.app-frame.theme-dark .summary-description,
.app-frame.theme-dark .current-setting span,
.app-frame.theme-dark .footer-note {
  color: #96aa9d;
}

.app-frame.theme-dark .topbar-title h1,
.app-frame.theme-dark .page-intro h2,
.app-frame.theme-dark .section-heading h3,
.app-frame.theme-dark .setting-title,
.app-frame.theme-dark .summary-card h3 {
  color: #edf3ed;
}

.app-frame.theme-dark .icon-button,
.app-frame.theme-dark .settings-card,
.app-frame.theme-dark .summary-card {
  border-color: #34473b;
  background: #243029;
  box-shadow: none;
}

.app-frame.theme-dark .icon-button {
  color: #a9b9ae;
}

.app-frame.theme-dark .setting-row + .setting-row,
.app-frame.theme-dark .summary-stats,
.app-frame.theme-dark .summary-stats div + div,
.app-frame.theme-dark .action-footer {
  border-color: #34473b;
}

.app-frame.theme-dark .select-control select,
.app-frame.theme-dark .segment-control {
  color: #e9f0e9;
  border-color: #405449;
  background: #1c2721;
}

.app-frame.theme-dark .select-control select {
  color: #e9f0e9;
}

.app-frame.theme-dark .segment-control button {
  color: #9caf9f;
}

.app-frame.theme-dark .segment-control button.is-selected {
  color: #edf3ed;
  background: #3a5143;
  box-shadow: none;
}

.app-frame.theme-dark .section-badge {
  color: #9caf9f;
  border-color: #34473b;
  background: #202c25;
}

.app-frame.theme-dark .info-banner {
  border-color: #385641;
  background: #24382b;
}

.app-frame.theme-dark .info-banner strong {
  color: #c5ddc8;
}

.app-frame.theme-dark .info-banner p {
  color: #9db5a1;
}

.app-frame.theme-dark .private-pill,
.app-frame.theme-dark .summary-icon {
  background: #2a4030;
}

.app-frame.theme-dark .summary-stats strong,
.app-frame.theme-dark .current-setting strong {
  color: #c4d6c8;
}

@media (max-width: 1080px) {
  .settings-layout {
    grid-template-columns: minmax(0, 1fr);
  }

  .summary-rail {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(190px, 0.72fr);
    align-items: start;
    gap: 15px;
    padding-top: 25px;
  }

  .tip-card {
    min-height: 0;
    margin-top: 0;
  }
}

@media (max-width: 760px) {
  #root {
    display: block;
    padding: 12px;
  }

  .app-frame {
    display: block;
    width: 100%;
    height: auto;
    min-height: calc(100vh - 24px);
    overflow: visible;
    border-radius: 20px;
  }

  .sidebar {
    display: none;
  }

  .topbar {
    padding: 23px 20px 21px;
    border-radius: 20px 20px 0 0;
  }

  .topbar-row {
    align-items: flex-start;
    margin-top: 19px;
  }

  .topbar-actions {
    gap: 9px;
  }

  .save-indicator span:last-child {
    display: none;
  }

  .content-scroll {
    overflow: visible;
    padding: 28px 20px 32px;
  }

  .page-intro h2 {
    font-size: 22px;
  }

  .summary-rail {
    grid-template-columns: 1fr;
  }

  .tip-card {
    margin-top: 0;
  }
}

@media (max-width: 570px) {
  .topbar-title h1 {
    font-size: 24px;
  }

  .topbar-title p {
    max-width: 190px;
    line-height: 1.45;
  }

  .page-intro {
    min-height: 0;
  }

  .intro-icon {
    width: 43px;
    height: 43px;
    border-radius: 13px;
  }

  .section-heading {
    align-items: flex-start;
    flex-direction: column;
    gap: 8px;
  }

  .section-badge {
    display: none;
  }

  .setting-row {
    align-items: flex-start;
    flex-direction: column;
    gap: 14px;
    padding: 18px;
  }

  .setting-control,
  .select-control,
  .segment-control {
    width: 100%;
  }

  .segment-control button {
    flex: 1;
    min-width: 0;
    padding: 0 5px;
  }

  .toggle-control {
    align-self: flex-start;
  }

  .action-footer {
    align-items: flex-start;
    flex-direction: column;
  }

  .save-button {
    width: 100%;
  }
}

