function Toggle({
  checked,
  title,
  description,
  onToggle,
}: {
  checked: boolean;
  title: string;
  description: string;
  onToggle: () => void;
}) {
  return (
    <div className='toggle-row'>
      <div className='toggle-copy'>
        <div className='toggle-title'>
          {title}
          <span className={`toggle-state ${checked ? 'enabled' : ''}`}>{checked ? 'On' : 'Off'}</span>
        </div>
        <p>{description}</p>
      </div>
      <button
        className={`switch ${checked ? 'is-on' : ''}`}
        type='button'
        role='switch'
        aria-checked={checked}
        aria-label={`Toggle ${title}`}
        onClick={onToggle}
      >
        <span />
      </button>
    </div>
  );
}

