export default function App() {
  const [activeSection, setActiveSection] = useState<SectionName>('General');
  const [saveState, setSaveState] = useState('All changes saved');
  const [notebook, setNotebook] = useState('Daily notes');
  const [font, setFont] = useState('Inter');
  const [autoSave, setAutoSave] = useState(true);
  const [weekStartsMonday, setWeekStartsMonday] = useState(true);
  const [spellCheck, setSpellCheck] = useState(true);
  const [smartPunctuation, setSmartPunctuation] = useState(true);
  const [focusMode, setFocusMode] = useState(false);
  const [theme, setTheme] = useState<ThemeName>('Light');
  const [compactMode, setCompactMode] = useState(false);
  const [accent, setAccent] = useState<AccentName>('coral');
  const [digest, setDigest] = useState(true);
  const [mentions, setMentions] = useState(true);
  const [weeklyReview, setWeeklyReview] = useState(false);
  const [delivery, setDelivery] = useState('Email & in-app');

  const markChanged = () => {
    setSaveState('Saving…');
    window.setTimeout(() => setSaveState('All changes saved'), 650);
  };

  const activePanel =
    activeSection === 'General' ? (
      <GeneralSettings
        notebook={notebook}
        font={font}
        autoSave={autoSave}
        weekStartsMonday={weekStartsMonday}
        onNotebookChange={(value) => {
          setNotebook(value);
          markChanged();
        }}
        onFontChange={(value) => {
          setFont(value);
          markChanged();
        }}
        onAutoSaveChange={() => {
          setAutoSave((value) => !value);
          markChanged();
        }}
        onWeekStartsChange={() => {
          setWeekStartsMonday((value) => !value);
          markChanged();
        }}
      />
    ) : activeSection === 'Editor' ? (
