function CardHeader({
  icon,
  title,
  description,
  tone = 'blue',
}: {
  icon: IconName;
  title: string;
  description: string;
  tone?: 'blue' | 'lilac' | 'peach' | 'mint' | 'gold';
}) {
  return (
    <div className='card-heading'>
      <div className={`heading-icon ${tone}`}><Icon name={icon} size={19} /></div>
      <div>
        <h2>{title}</h2>
        <p>{description}</p>
      </div>
    </div>
  );
}

function ToggleRow({
  icon,
  label,
  description,
  checked,
  onChange,
}: {
  icon: IconName;
  label: string;
  description: string;
  checked: boolean;
  onChange: (value: boolean) => void;
}) {
  return (
    <div className='toggle-row'>
      <div className='toggle-icon'><Icon name={icon} size={17} /></div>
      <div className='toggle-copy'>
        <span className='toggle-label'>{label}</span>
        <span className='toggle-description'>{description}</span>
      </div>
      <button
        type='button'
        className={`switch ${checked ? 'is-on' : ''}`}
        aria-pressed={checked}
        aria-label={`${label} ${checked ? 'on' : 'off'}`}
        onClick={() => onChange(!checked)}
      >
        <span />
      </button>
    </div>
  );
}

function SelectField({
  label,
  value,
  options,
  onChange,
  hint,
}: {
  label: string;
  value: string;
  options: ReadonlyArray<{ label: string; value: string }>;
  onChange: (value: string) => void;
  hint?: string;
}) {
  return (
    <label className='field'>
      <span className='field-label'>{label}</span>
      <span className='select-wrap'>
        <select value={value} onChange={(event) => onChange(event.target.value)}>
          {options.map((option) => <option value={option.value} key={option.value}>{option.label}</option>)}
        </select>
        <Icon name='chevronDown' size={15} />
      </span>
      {hint && <span className='field-hint'>{hint}</span>}
    </label>
  );
}

function ThemeCard({
  value,
  label,
  detail,
  theme,
  onSelect,
}: {
  value: Theme;
  label: string;
  detail: string;
  theme: Theme;
  onSelect: (value: Theme) => void;
}) {
  const selected = theme === value;
  const icon: Record<Theme, IconName> = { light: 'sun', dark: 'moon', system: 'monitor' };

  return (
    <button type='button' className={`theme-choice ${selected ? 'is-selected' : ''}`} aria-pressed={selected} onClick={() => onSelect(value)}>
      <span className={`theme-preview preview-${value}`}>
        <span className='preview-top'><i /><i /><i /></span>
        <span className='preview-lines'><i /><i className='short' /></span>
      </span>
      <span className='theme-choice-footer'>
        <span className='theme-choice-name'><Icon name={icon[value]} size={14} />{label}</span>
        {selected && <Icon name='check' size={15} className='theme-check' />}
      </span>
      <span className='theme-detail'>{detail}</span>
    </button>
  );
}

function KeyboardKey({ children }: { children: string }) {
  return <kbd>{children}</kbd>;
}

