function Toggle({ label, value, onChange }: { label: string; value: boolean; onChange: () => void }) {
  return (
    <button
      className={`toggle ${value ? 'is-on' : ''}`}
      type='button'
      role='switch'
      aria-checked={value}
      aria-label={`${label} ${value ? 'enabled' : 'disabled'}`}
      onClick={onChange}
    >
      <span className='toggle-knob' />
    </button>
  );
}

