  flex-direction: column;
  gap: 8px;
}

.preview-line,
.preview-lines span {
  height: 5px;
  display: block;
  background: #edf0eb;
  border-radius: 999px;
}

.preview-lines span:nth-child(1) {
  width: 92%;
}

.preview-lines span:nth-child(2) {
  width: 80%;
}

.preview-lines span:nth-child(3) {
  width: 87%;
}

.preview-lines span:nth-child(4) {
  width: 55%;
}

.preview-caption {
  display: flex;
  align-items: center;
  gap: 7px;
  margin: 11px 4px 0;
  color: #a0a8a1;
  font-size: 10px;
}

.caption-dot {
  width: 5px;
  height: 5px;
  background: var(--accent);
}

.tip-card {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  margin-top: 21px;
  padding: 13px;
  background: var(--accent-wash);
  border: 1px solid var(--accent-soft);
  border-radius: 11px;
}

.tip-badge {
  width: 27px;
  height: 27px;
  display: grid;
  flex: 0 0 27px;
  place-items: center;
  color: var(--accent-strong);
  background: var(--accent-soft);
  border-radius: 8px;
}

.tip-card > span:last-child {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.tip-card strong {
  color: #627168;
  font-size: 10px;
  font-weight: 700;
}

.tip-card > span:last-child > span {
  color: #98a29a;
  font-size: 10px;
  line-height: 1.45;
}

.preview-card.theme-dark {
  color: #dfe9e2;
  background: #202824;
  border-color: #344139;
}

.preview-card.theme-dark .preview-window-bar {
  color: #7f9185;
  border-color: #344139;
}

.preview-card.theme-dark .window-action {
  color: #8da196;
}

.preview-card.theme-dark .preview-note-type,
.preview-card.theme-dark .note-type-icon,
.preview-card.theme-dark .preview-highlight {
  color: #a5c9b2;
}

.preview-card.theme-dark .note-type-icon,
.preview-card.theme-dark .preview-highlight {
  background: rgba(135, 185, 155, 0.14);
}

.preview-card.theme-dark .preview-date,
.preview-card.theme-dark .preview-meta {
  color: #718078;
}

.preview-card.theme-dark h3 {
  color: #eef5ef;
}

.preview-card.theme-dark .preview-text {
  color: #9aaa9f;
}

.preview-card.theme-dark .preview-lines span {
  background: #34423a;
}

.preview-card.theme-system {
  background: #fbfcfa;
}

@media (max-width: 1040px) {
  .sidebar {
    width: 218px;
    flex-basis: 218px;
  }

  .topbar,
  .content-wrap {
    padding-left: 34px;
    padding-right: 34px;
  }

  .content-grid {
    grid-template-columns: minmax(0, 1fr) 264px;
