    width: 46px;
    height: 42px;
    justify-content: center;
    margin: 4px auto;
    padding: 0;
  }

  .sidebar-bottom {
    width: 100%;
  }

  .sidebar-bottom > .nav-item {
    margin-bottom: 11px;
  }

  .sidebar-divider {
    margin: 0 5px 15px;
  }

  .account-row {
    justify-content: center;
    padding: 7px 0;
  }

  .content-grid {
    grid-template-columns: 1fr;
  }

  .preview-column {
    position: static;
