    padding: 34px 16px 48px;
  }

  .heading-block {
    align-items: flex-start;
    flex-direction: column;
    gap: 18px;
    margin-bottom: 27px;
  }

  .saved-state {
    padding-bottom: 0;
  }

  .settings-card {
    border-radius: 13px;
  }

  .setting-section {
    padding: 23px 18px 7px;
  }

  .preference-row {
    align-items: flex-start;
    flex-direction: column;
    gap: 12px;
    padding: 16px 0;
  }

  .preference-help {
    max-width: none;
  }

  .segmented-control,
  .density-control {
    width: 100%;
  }

  .segment-button,
  .density-control button {
    flex: 1;
  }

  .swatch-options {
    padding: 2px 0;
  }

  .toggle-row {
