  font-size: 10px;
  font-weight: 800;
  background: linear-gradient(145deg, #f0a27d, #d86f78);
  border: 3px solid #ffffff;
  border-radius: 50%;
  box-shadow: 0 2px 7px rgba(41, 42, 64, 0.1);
}

.settings-page {
  width: min(1120px, calc(100% - 84px));
  margin: 0 auto;
  padding: 36px 0 56px;
}

.page-intro {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 25px;
}

.intro-copy h1 {
  margin: 6px 0 6px;
  color: #25263f;
  font-size: 29px;
  font-weight: 760;
  letter-spacing: -0.045em;
}

.intro-copy > p:last-child {
  margin: 0;
  color: #898b9e;
  font-size: 12px;
}

.page-meta {
  display: flex;
  align-items: center;
  gap: 10px;
  padding-bottom: 3px;
  color: #a5a6b4;
  font-size: 10px;
  font-weight: 600;
}

.sync-indicator,
.autosave,
.sync-note,
.preview-status {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.sync-indicator {
  color: #6e8f7f;
}

.status-dot {
  width: 6px;
  height: 6px;
  border: 0;
}

.meta-divider {
  width: 3px;
  height: 3px;
  background: #c5c6d0;
  border-radius: 50%;
}

.settings-panel {
  display: grid;
  grid-template-columns: 218px minmax(0, 1fr);
  overflow: hidden;
  min-height: 690px;
  background: var(--surface);
  border: 1px solid #e8e9f0;
  border-radius: 20px;
  box-shadow: 0 18px 45px rgba(39, 39, 72, 0.07);
}

.settings-nav {
  display: flex;
  flex-direction: column;
  padding: 26px 13px 18px;
  background: #fbfbfd;
  border-right: 1px solid #ececf2;
}

.settings-nav-label {
  padding: 0 10px 12px;
}

.settings-items {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.settings-item {
  display: grid;
  grid-template-columns: 31px minmax(0, 1fr) 14px;
  align-items: center;
  min-height: 58px;
  width: 100%;
  gap: 9px;
  padding: 7px 8px;
  color: #888a9c;
  text-align: left;
  background: transparent;
  border-radius: 11px;
  transition: background 160ms ease, color 160ms ease;
}

.settings-item:hover {
  color: #5c5e75;
  background: #f3f3f8;
}

.settings-item.active {
  color: var(--violet-dark);
  background: #eeecff;
}

.settings-item-icon {
  display: grid;
  width: 31px;
  height: 31px;
  place-items: center;
  color: #999bad;
  background: #f3f3f7;
  border-radius: 9px;
}

.settings-item.active .settings-item-icon {
  color: var(--violet);
  background: #ffffff;
  box-shadow: 0 3px 9px rgba(89, 76, 190, 0.11);
}

.settings-item > .ui-icon {
  color: #b0b1bf;
}

.settings-item.active > .ui-icon {
  color: #8278dd;
}

.settings-item-copy {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 3px;
}

.settings-item-copy strong {
  overflow: hidden;
  color: inherit;
  font-size: 11px;
  font-weight: 750;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.settings-item-copy small {
  overflow: hidden;
  color: #a4a5b4;
  font-size: 9px;
  font-weight: 550;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.settings-item.active .settings-item-copy small {
  color: #8f88c9;
}

.settings-nav-footnote {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  margin-top: auto;
  padding: 15px 10px 2px;
  color: #a2a4b3;
  font-size: 10px;
  line-height: 1.45;
  border-top: 1px solid #ededf2;
}

.settings-nav-footnote strong {
  display: block;
  color: #73758b;
  font-size: 10px;
  font-weight: 700;
}

.settings-nav-footnote .ui-icon {
  color: #8d83df;
  margin-top: 1px;
}

.settings-content {
  min-width: 0;
  padding: 29px 30px 18px;
  background: #ffffff;
}

.section-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
  padding-bottom: 24px;
  border-bottom: 1px solid #f0f0f4;
}

.section-context {
  display: flex;
  align-items: flex-start;
  gap: 13px;
  min-width: 0;
}

.section-icon {
  display: grid;
  width: 39px;
  height: 39px;
  place-items: center;
  flex: none;
  color: var(--violet);
  background: #f0eeff;
  border-radius: 11px;
}

.section-header-copy {
  min-width: 0;
}

.section-kicker {
  display: block;
  margin-bottom: 4px;
  color: #aaaab8;
  font-size: 8px;
}

.section-header h2 {
  margin: 0;
  color: #2d2e48;
  font-size: 20px;
  font-weight: 760;
  letter-spacing: -0.035em;
}

.section-header p {
  margin: 5px 0 0;
  color: #9698a8;
  font-size: 11px;
}

.section-actions {
  display: flex;
  align-items: center;
  gap: 15px;
  padding-top: 5px;
}

.autosave {
  color: #789487;
  font-size: 10px;
  font-weight: 650;
}

.primary-button,
.ghost-button,
.outline-button,
.text-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  white-space: nowrap;
  transition: color 160ms ease, background 160ms ease, border-color 160ms ease, transform 160ms ease;
}

.primary-button {
  min-height: 34px;
  padding: 0 14px;
  color: #ffffff;
  font-size: 10px;
  font-weight: 750;
  background: linear-gradient(135deg, #7568e2, #5d50cf);
  border-radius: 8px;
  box-shadow: 0 5px 12px rgba(92, 78, 203, 0.19);
}

.primary-button:hover {
  background: linear-gradient(135deg, #695bd7, #5144bd);
  transform: translateY(-1px);
}

.section-stack {
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding-top: 22px;
}

.setting-card {
  padding: 21px 22px 20px;
  background: #ffffff;
  border: 1px solid #eaebf1;
  border-radius: 14px;
}

.card-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 19px;
}

.card-kicker {
  margin-bottom: 7px;
  color: #aaaab8;
  font-size: 8px;
}

.card-head h3,
.quiet-card h3,
.security-banner h3 {
  margin: 0;
  color: #36374f;
  font-size: 13px;
  font-weight: 750;
  letter-spacing: -0.015em;
}

.card-description {
  margin: 5px 0 0;
  color: #999baa;
  font-size: 10px;
  line-height: 1.4;
}

.card-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 5px 8px;
  color: #8a82cb;
  font-size: 9px;
  font-weight: 700;
  white-space: nowrap;
  background: #f7f5ff;
  border-radius: 6px;
}

.card-badge .ui-icon {
  color: #8d82e4;
}

.badge-dot {
  width: 5px;
  height: 5px;
  background: #69ba94;
  border-radius: 50%;
}

.profile-line {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 13px 14px;
  background: #fafaff;
  border: 1px solid #efeff7;
  border-radius: 11px;
}

.avatar-large {
  width: 41px;
  height: 41px;
  font-size: 12px;
}

.profile-copy {
  display: flex;
  min-width: 0;
  flex: 1;
  flex-direction: column;
  gap: 3px;
}

.profile-name {
  color: #3f4058;
  font-size: 12px;
  font-weight: 750;
}

.profile-email {
  color: #999baa;
  font-size: 10px;
}

.ghost-button,
.outline-button {
  min-height: 31px;
  padding: 0 10px;
  color: #6b6d82;
  font-size: 10px;
  font-weight: 700;
  background: #ffffff;
  border: 1px solid #e7e7ee;
  border-radius: 7px;
}

.ghost-button:hover,
.outline-button:hover {
  color: var(--violet-dark);
  background: #f8f7ff;
  border-color: #d9d5f7;
}

.field-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 15px;
  margin-top: 20px;
  padding-top: 19px;
  border-top: 1px solid #f0f0f4;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 7px;
  color: #74768a;
  font-size: 10px;
  font-weight: 700;
}

.field input,
.field-select {
  width: 100%;
  min-height: 35px;
  padding: 0 10px;
  color: #4d4f67;
  font-size: 10px;
  font-weight: 600;
  background: #fcfcfe;
  border: 1px solid #e7e8ef;
  border-radius: 8px;
  transition: border-color 160ms ease, box-shadow 160ms ease;
}

.field input:focus,
.field-select:focus {
  border-color: #aaa1ed;
  box-shadow: 0 0 0 3px rgba(99, 86, 216, 0.08);
  outline: 0;
}

.select-wrap {
  position: relative;
  min-width: 153px;
}

.field .select-wrap {
  width: 100%;
}

.select-wrap .field-select {
  appearance: none;
  padding-right: 29px;
}

.select-wrap > .ui-icon {
  position: absolute;
  top: 50%;
  right: 9px;
  color: #989aaa;
  pointer-events: none;
  transform: translateY(-50%);
}

.setting-list {
  display: flex;
  flex-direction: column;
}

.setting-row {
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr) auto;
  align-items: center;
  gap: 13px;
  min-height: 65px;
  padding: 10px 0;
}

.setting-row + .setting-row {
  border-top: 1px solid #f0f0f4;
}

.setting-row-icon {
  display: grid;
  width: 32px;
  height: 32px;
  place-items: center;
  color: #8177d9;
  background: #f5f3ff;
  border-radius: 9px;
}

.setting-copy,
.accent-copy {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 4px;
}

.row-label {
  color: #53556d;
  font-size: 11px;
  font-weight: 720;
}

.row-help {
  overflow: hidden;
  color: #a0a1b0;
  font-size: 9px;
  line-height: 1.35;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.toggle {
  display: flex;
  align-items: center;
  width: 40px;
  height: 23px;
  padding: 2px;
  background: #dedfe8;
  border-radius: 99px;
  transition: background 180ms ease;
}

.toggle.is-on {
  background: var(--violet);
}

.toggle-thumb {
  display: block;
  width: 19px;
  height: 19px;
  background: #ffffff;
  border-radius: 50%;
  box-shadow: 0 1px 4px rgba(31, 32, 54, 0.19);
  transition: transform 180ms ease;
}

.toggle.is-on .toggle-thumb {
  transform: translateX(17px);
}

.theme-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 11px;
}

.theme-option {
  padding: 7px;
  color: #74768a;
  text-align: left;
  background: #ffffff;
  border: 1px solid #e7e7ef;
  border-radius: 11px;
  transition: border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
}

.theme-option:hover {
  border-color: #c9c4f3;
  transform: translateY(-1px);
}

.theme-option.selected {
  border-color: #8277e3;
  box-shadow: 0 0 0 3px rgba(99, 86, 216, 0.09);
}

.theme-preview {
  height: 82px;
  overflow: hidden;
  padding: 8px;
  border: 1px solid rgba(55, 57, 85, 0.1);
  border-radius: 7px;
}

.preview-light {
  background: #ffffff;
}

.preview-dark {
  background: #292a3c;
}

.preview-system {
  background: linear-gradient(90deg, #ffffff 0 50%, #292a3c 50% 100%);
}

.preview-window-top {
  display: flex;
  align-items: center;
  gap: 5px;
  height: 11px;
}

.preview-dots,
.preview-dots::before,
.preview-dots::after {
  display: block;
  width: 3px;
  height: 3px;
  background: #b8b8c5;
  border-radius: 50%;
}

.preview-dots {
  position: relative;
  margin-left: 1px;
}

.preview-dots::before,
.preview-dots::after {
  position: absolute;
  top: 0;
  content: '';
}

.preview-dots::before {
  left: 5px;
}

.preview-dots::after {
  left: 10px;
}

.preview-window-title {
  display: block;
  width: 23px;
  height: 3px;
  margin-left: auto;
  background: #dddde5;
  border-radius: 3px;
}

.preview-window-body {
  display: flex;
  flex-direction: column;
  gap: 7px;
  padding: 12px 8px 0 17px;
}

.preview-window-body span {
  display: block;
  width: 72%;
  height: 4px;
  background: #dcdce4;
  border-radius: 2px;
}

.preview-window-body span:nth-child(2) {
  width: 51%;
}

.preview-window-body span:nth-child(3) {
  width: 84%;
  background: #a79bef;
}

.preview-window-body span:nth-child(4) {
  width: 63%;
}

.preview-dark .preview-dots,
.preview-dark .preview-dots::before,
.preview-dark .preview-dots::after,
.preview-system .preview-dots,
.preview-system .preview-dots::before,
.preview-system .preview-dots::after {
  background: #77798f;
}

.preview-dark .preview-window-title {
  background: #55576c;
}

.preview-dark .preview-window-body span,
.preview-system .preview-window-body span:nth-child(n + 3) {
  background: #56586e;
}

.preview-dark .preview-window-body span:nth-child(3) {
  background: #8479db;
}

.preview-system .preview-window-body {
  width: 50%;
}

.theme-option-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  padding: 9px 3px 2px;
  color: #57596f;
  font-size: 10px;
  font-weight: 720;
}

.theme-option-footer > span:first-child,
.theme-selected {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}

.theme-selected {
  color: #756ad3;
  font-size: 8px;
  font-weight: 750;
}

.accent-section {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  margin-top: 20px;
  padding-top: 18px;
  border-top: 1px solid #f0f0f4;
}

.accent-swatches {
  display: flex;
  align-items: center;
  gap: 9px;
}

.accent-swatch {
  display: grid;
  width: 25px;
  height: 25px;
  place-items: center;
  color: #ffffff;
  border: 3px solid #ffffff;
  border-radius: 50%;
  box-shadow: 0 0 0 1px transparent;
  transition: transform 160ms ease, box-shadow 160ms ease;
}

.accent-swatch:hover {
  transform: scale(1.08);
}

.accent-swatch.selected {
  box-shadow: 0 0 0 2px #8b82e5;
}

.accent-violet { background: #695bd5; }
.accent-coral { background: #e38373; }
.accent-teal { background: #43aaa0; }
.accent-blue { background: #568bd9; }
.accent-gold { background: #d6a23f; }

.editor-preview {
  padding: 13px;
  background: #faf9ff;
  border: 1px solid #e7e4fb;
  border-radius: 14px;
}

.editor-preview-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 10px;
}

.editor-preview-label {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: #7770bd;
  font-size: 9px;
  font-weight: 750;
}

.preview-status {
  color: #86a495;
  font-size: 9px;
  font-weight: 650;
}

.editor-paper {
  padding: 20px 23px 22px;
  background: #ffffff;
  border: 1px solid #eeeef5;
  border-radius: 10px;
  box-shadow: 0 6px 15px rgba(76, 66, 155, 0.05);
}

.editor-paper-kicker {
  color: #a8a9b8;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.13em;
}

.editor-paper h4 {
  margin: 9px 0 6px;
  color: #383950;
  font-family: Georgia, serif;
  font-size: 18px;
  font-weight: 500;
  letter-spacing: -0.02em;
}

.editor-paper p {
  max-width: 440px;
  margin: 0;
  color: #898b9e;
  font-size: 10px;
  line-height: 1.6;
}

.editor-highlight {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 15px;
  padding: 8px 10px;
  color: #6e69aa;
  font-size: 9px;
  background: #f4f2ff;
  border-radius: 6px;
}

.editor-highlight span {
  width: 3px;
  height: 17px;
  background: #8e83e7;
  border-radius: 3px;
}

.quiet-card {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 17px 19px;
  background: #fcfcfe;
}

.quiet-card p {
  margin: 5px 0 0;
  color: #9a9bab;
  font-size: 10px;
  line-height: 1.4;
}

.quiet-card > div:nth-child(2) {
  min-width: 0;
  flex: 1;
}

.quiet-card-icon {
  display: grid;
  width: 35px;
  height: 35px;
  place-items: center;
  color: #8176d9;
  background: #f0eeff;
  border-radius: 10px;
}

.text-button {
  padding: 0;
  color: #776dd0;
  font-size: 10px;
  font-weight: 750;
  background: transparent;
}

.text-button:hover {
  color: #4d42b4;
}

.security-banner {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 15px 17px;
  background: #f3fbf7;
  border: 1px solid #dff1e8;
  border-radius: 13px;
}

.security-banner-icon {
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  color: #3f9b75;
  background: #dff4e9;
  border-radius: 11px;
}

.security-banner-copy {
  min-width: 0;
  flex: 1;
}

.security-banner h3 {
  color: #367359;
}

.security-banner p {
  margin: 5px 0 0;
  color: #80a492;
  font-size: 10px;
}

.status-pill {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 5px 8px;
  color: #818396;
  font-size: 9px;
  font-weight: 750;
  white-space: nowrap;
  background: #f4f4f8;
  border-radius: 6px;
}

.status-pill.success {
  color: #438665;
  background: #dff3e8;
}

.content-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 20px;
  padding-top: 16px;
  border-top: 1px solid #f0f0f4;
}

.sync-note {
  color: #b0b1bd;
  font-size: 9px;
  font-weight: 600;
}

.sync-note .ui-icon {
  color: #9a9cab;
}

.empty-state {
  display: grid;
  min-height: 280px;
  place-items: center;
  text-align: center;
}

.empty-state .section-icon {
  margin: 0 auto 14px;
}

.empty-state h3 {
  margin: 0;
  color: #44465e;
  font-size: 14px;
}

.empty-state p {
  margin: 6px 0 0;
  color: #9a9cab;
  font-size: 10px;
}

@media (max-width: 1050px) {
  .app-sidebar {
    flex-basis: 220px;
    width: 220px;
  }

  .topbar {
    padding: 0 28px;
  }

  .settings-page {
    width: min(100% - 56px, 1120px);
  }
}

@media (max-width: 800px) {
  .app-sidebar {
    display: none;
  }

  .settings-page {
    width: min(100% - 34px, 680px);
    padding-top: 27px;
  }

  .settings-panel {
    grid-template-columns: 1fr;
  }

  .settings-nav {
    padding: 16px;
    border-right: 0;
    border-bottom: 1px solid #ececf2;
  }

  .settings-nav-label {
    padding-bottom: 9px;
  }

  .settings-items {
    display: grid;
    grid-template-columns: repeat(5, minmax(0, 1fr));
    gap: 5px;
  }

  .settings-item {
    display: flex;
    min-height: 0;
    flex-direction: column;
    justify-content: center;
    gap: 5px;
    padding: 9px 5px;
    text-align: center;
  }

  .settings-item > .ui-icon,
  .settings-item-copy small {
    display: none;
  }

  .settings-item-copy {
    display: block;
    width: 100%;
  }

  .settings-item-copy strong {
    display: block;
    font-size: 9px;
    white-space: normal;
  }

  .settings-nav-footnote {
    display: none;
  }

  .settings-content {
    padding: 25px 22px 18px;
  }
}

@media (max-width: 560px) {
  .topbar {
    height: 64px;
    padding: 0 17px;
  }

  .search-trigger {
    width: 35px;
    padding: 0;
    justify-content: center;
  }

