function SelectField({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: string;
  options: string[];
  onChange: (value: string) => void;
}) {
  return (
    <label className='control-group'>
      <span className='field-label'>{label}</span>
      <span className='select-wrap'>
