function Toggle({ checked, onChange, label }: { checked: boolean; onChange: () => void; label: string }) {
  return (
    <button
      type='button'
      className={`toggle ${checked ? 'on' : ''}`}
      role='switch'
      aria-checked={checked}
      aria-label={label}
      onClick={onChange}
