    </button>
  );
}

function SelectField({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: string;
  options: string[];
  onChange: (value: string) => void;
}) {
  return (
    <label className='select-wrap'>
      <select aria-label={label} value={value} onChange={(event) => onChange(event.target.value)}>
