function App() {
  const [activeTab, setActiveTab] = useState<Tab>('General');
  const [saved, setSaved] = useState(false);
  const [defaultNotebook, setDefaultNotebook] = useState('Personal');
  const [startPage, setStartPage] = useState('All notes');
  const [theme, setTheme] = useState('Light');
  const [accent, setAccent] = useState('Sage');
  const [density, setDensity] = useState('Comfortable');
  const [settings, setSettings] = useState<PreferenceState>({
    launch: true,
    suggestions: true,
    spellcheck: true,
    markdown: true,
    sounds: false,
  });

  const markChanged = () => setSaved(false);
  const togglePreference = (key: PreferenceKey) => {
    setSettings((current) => ({ ...current, [key]: !current[key] }));
    markChanged();
  };

  const renderTab = () => {
    switch (activeTab) {
      case 'Editor':
        return <EditorTab settings={settings} onToggle={togglePreference} />;
      case 'Appearance':
        return (
          <AppearanceTab
            theme={theme}
            onThemeChange={(value) => { setTheme(value); markChanged(); }}
            accent={accent}
            onAccentChange={(value) => { setAccent(value); markChanged(); }}
            density={density}
            onDensityChange={(value) => { setDensity(value); markChanged(); }}
          />
        );
      case 'Shortcuts':
        return <ShortcutsTab />;
      case 'General':
      default:
        return (
          <GeneralTab
            settings={settings}
            onToggle={togglePreference}
            defaultNotebook={defaultNotebook}
            onDefaultNotebookChange={(value) => { setDefaultNotebook(value); markChanged(); }}
            startPage={startPage}
            onStartPageChange={(value) => { setStartPage(value); markChanged(); }}
          />
        );
    }
  };

  return (
    <div className='app-shell'>
      <aside className='sidebar'>
        <div className='brand'>
          <span className='brand-mark'>n</span>
          <span className='brand-name'>notelet</span>
          <span className='brand-tag'>BETA</span>
        </div>

        <button type='button' className='workspace-switcher'>
          <span className='workspace-avatar'>J</span>
          <span className='workspace-copy'>
            <span className='workspace-name'>Jordan’s space</span>
            <span className='workspace-role'>Personal workspace</span>
          </span>
          <Icon name='chevron' size={15} />
        </button>

        <nav className='primary-nav' aria-label='Primary navigation'>
          <p className='nav-label'>Workspace</p>
          {navItems.map((item) => (
            <button type='button' className='nav-item' key={item.label}>
              <Icon name={item.icon} size={17} />
              <span>{item.label}</span>
            </button>
          ))}
          <p className='nav-label account-label'>Account</p>
          <button type='button' className='nav-item active' aria-current='page' onClick={() => setActiveTab('General')}>
            <Icon name='settings' size={17} />
            <span>Settings</span>
          </button>
        </nav>

        <div className='sidebar-bottom'>
          <div className='plan-card'>
            <div className='plan-topline'>
              <span>Personal plan</span>
              <span className='plan-badge'>FREE</span>
            </div>
            <p>Keep your ideas close, wherever they happen.</p>
            <div className='plan-progress'><span /></div>
            <span className='plan-meta'>620 / 1,000 notes</span>
          </div>
          <button type='button' className='profile-card'>
            <span className='profile-avatar'>JM</span>
            <span className='profile-copy'>
              <span className='profile-name'>Jordan Miller</span>
              <span className='profile-email'>jordan@example.com</span>
            </span>
            <Icon name='more' size={16} />
          </button>
        </div>
      </aside>

      <main className='main-panel'>
        <header className='topbar'>
          <div className='breadcrumb'>
            <span>Workspace</span>
            <Icon name='chevron' size={14} />
            <span className='breadcrumb-current'>Settings</span>
          </div>
          <div className='topbar-actions'>
            <button type='button' className='icon-button' aria-label='Search'>
              <Icon name='search' size={18} />
            </button>
            <button type='button' className='icon-button notification-button' aria-label='Notifications'>
              <Icon name='bell' size={18} />
              <span className='notification-dot' />
            </button>
            <span className='topbar-divider' />
            <button type='button' className='topbar-profile'>
              <span className='topbar-avatar'>JM</span>
              <span className='topbar-profile-name'>Jordan Miller</span>
              <Icon name='chevron' size={14} />
            </button>
          </div>
        </header>

        <div className='page-content'>
          <div className='title-row'>
            <div className='title-copy'>
              <p className='eyebrow'>WORKSPACE SETTINGS</p>
              <h1>Settings</h1>
              <p>Make Notelet fit the way you capture and revisit ideas.</p>
            </div>
            <div className='title-actions'>
              <span className={`sync-status ${saved ? 'saved' : ''}`}><span className='status-dot' />{saved ? 'Saved just now' : 'Changes ready'}</span>
              <button type='button' className={`save-button ${saved ? 'saved' : ''}`} onClick={() => setSaved(true)}>
                <Icon name={saved ? 'check' : 'arrow'} size={16} />
                {saved ? 'Saved' : 'Save changes'}
              </button>
            </div>
          </div>

          <div className='tabs' role='tablist' aria-label='Settings sections'>
            {tabLabels.map((tab) => (
              <button
                type='button'
                role='tab'
                aria-selected={activeTab === tab}
                className={`tab-button ${activeTab === tab ? 'active' : ''}`}
                key={tab}
                onClick={() => setActiveTab(tab)}
              >
                {tab}
              </button>
            ))}
          </div>

          {renderTab()}
        </div>
      </main>
    </div>
  );
}

export default App;

