function Icon({ name, size = 18 }: { name: IconName; size?: number }) {
  return (
    <svg aria-hidden='true' className='icon' fill='none' height={size} viewBox='0 0 24 24' width={size} xmlns='http://www.w3.org/2000/svg'>
