function Toggle({
  icon,
  title,
  description,
  checked,
  onChange,
}: {
  icon: IconName;
  title: string;
  description: string;
  checked: boolean;
  onChange: () => void;
}) {
  return (
    <div className='setting-row'>
      <div className={`setting-icon setting-icon-${icon}`}><Icon name={icon} size={18} /></div>
      <div className='setting-copy'>
        <strong>{title}</strong>
        <p>{description}</p>
      </div>
      <button
        type='button'
        className={`switch ${checked ? 'is-on' : ''}`}
        role='switch'
        aria-checked={checked}
        aria-label={title}
        onClick={onChange}
      >
        <span />
      </button>
    </div>
  );
}

function SelectField({
  id,
  label,
  value,
  options,
  onChange,
}: {
  id: string;
  label: string;
  value: string;
  options: string[];
  onChange: (value: string) => void;
}) {
  return (
    <label className='field' htmlFor={id}>
      <span className='field-label'>{label}</span>
      <span className='select-wrap'>
        <select id={id} value={value} onChange={(event) => onChange(event.target.value)}>
          {options.map((option) => <option key={option} value={option}>{option}</option>)}
        </select>
        <Icon name='chevronDown' size={15} className='select-arrow' />
      </span>
    </label>
  );
}

function ThemePreview({ value }: { value: ThemeValue }) {
