.field-grid.single-field {
  grid-template-columns: minmax(0, 1fr);
}

.field-wide {
  grid-column: 1 / -1;
}

.field {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 7px;
  color: var(--text);
  font-size: 10px;
  font-weight: 650;
}

.field-label {
  color: var(--muted);
  font-size: 10px;
  font-weight: 650;
}

.field input,
.field select {
  width: 100%;
  height: 37px;
  padding: 0 11px;
  color: var(--text);
  border: 1px solid var(--border);
  border-radius: 8px;
  outline: 0;
  background: var(--field);
  font-size: 11px;
  transition: border-color 160ms ease, box-shadow 160ms ease;
}

.field input:hover,
.field select:hover {
  border-color: #ccd1dd;
}

.field input:focus,
.field select:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 14%, transparent);
}

.select-wrap {
  position: relative;
  display: block;
}

.field select {
  appearance: none;
  padding-right: 35px;
}

.select-arrow {
  position: absolute;
  top: 11px;
  right: 11px;
  color: var(--subtle);
  pointer-events: none;
}

.preference-list {
  display: flex;
  flex-direction: column;
}

.setting-row {
  min-width: 0;
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr) auto;
  align-items: center;
  gap: 11px;
  padding: 13px 0;
  border-top: 1px solid var(--border);
}

.setting-row:first-child {
  padding-top: 1px;
  border-top: 0;
}

.setting-row:last-child {
  padding-bottom: 1px;
}

.setting-icon {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  color: var(--accent);
  border-radius: 9px;
  background: var(--accent-soft);
}

.setting-icon-cloud {
  color: #5a9dd3;
  background: #eaf5fc;
}

.setting-icon-word {
  color: #9271cc;
  background: #f3edff;
}

.setting-icon-focus {
  color: #58a07e;
  background: #eaf7ef;
}

.setting-icon-sparkle {
  color: #d49250;
  background: #fff3e5;
}

.setting-icon-check {
  color: #5a9dd3;
  background: #eaf5fc;
}

.setting-icon-bell,
.setting-icon-mail {
  color: #d07069;
  background: #fff0ee;
}

.setting-icon-share {
  color: #7d78d9;
  background: #efeeff;
}

.setting-copy {
  min-width: 0;
}

.setting-copy strong {
  display: block;
  overflow: hidden;
  color: var(--text);
  font-size: 11px;
  font-weight: 650;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.setting-copy p {
  overflow: hidden;
  margin: 4px 0 0;
  color: var(--muted);
  font-size: 10px;
  line-height: 1.35;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.switch {
  position: relative;
  width: 40px;
  height: 23px;
  flex: 0 0 40px;
  padding: 2px;
  border-radius: 99px;
  background: #dfe3ea;
  transition: background 160ms ease;
}

.switch span {
  position: absolute;
  top: 3px;
  left: 3px;
  width: 17px;
  height: 17px;
  border-radius: 50%;
  background: #fff;
  box-shadow: 0 2px 5px rgba(30, 36, 52, 0.18);
  transition: transform 160ms ease;
}

.switch.is-on {
  background: var(--accent);
}

.switch.is-on span {
  transform: translateX(17px);
}

.theme-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 11px;
}

.theme-option {
  position: relative;
  min-width: 0;
  padding: 7px;
  color: var(--text);
  border: 1px solid var(--border);
  border-radius: 10px;
  background: var(--field);
  text-align: left;
}

.theme-option:hover {
  border-color: #cbd0dc;
}

.theme-option.is-selected {
  border-color: var(--accent);
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--accent) 13%, transparent);
}

.theme-preview {
  height: 76px;
  display: flex;
  overflow: hidden;
  gap: 5px;
  padding: 8px;
  border: 1px solid #e4e6ed;
  border-radius: 7px;
  background: #f9fafc;
}

.theme-preview-sidebar {
  width: 22%;
  display: block;
  border-radius: 3px;
  background: #e7e9f0;
}

.theme-preview-sidebar i {
  width: 60%;
  height: 4px;
  display: block;
  margin: 8px auto;
  border-radius: 3px;
  background: #cfd3df;
}

.theme-preview-window {
  min-width: 0;
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 5px;
  padding: 4px 5px;
  border-radius: 3px;
  background: #fff;
}

.preview-line,
.preview-block {
  display: block;
  border-radius: 3px;
}

.preview-line {
  height: 4px;
  background: #d3d7e1;
}

.preview-line-long {
  width: 75%;
}

.preview-line-short {
  width: 48%;
}

.preview-block {
  width: 100%;
  height: 24px;
  margin-top: 4px;
  background: #eef0f5;
}

.theme-preview-dark {
  border-color: #3d4352;
  background: #202530;
}

.theme-preview-dark .theme-preview-sidebar {
  background: #2d3340;
}

.theme-preview-dark .theme-preview-sidebar i {
  background: #565e70;
}

.theme-preview-dark .theme-preview-window {
  background: #303643;
}

.theme-preview-dark .preview-line {
  background: #697286;
}

.theme-preview-dark .preview-block {
  background: #3d4555;
}

.theme-preview-system {
  border-color: #cfd4df;
  background: linear-gradient(90deg, #f7f8fb 0%, #f7f8fb 50%, #252a36 50%, #252a36 100%);
}

.theme-preview-system .theme-preview-sidebar {
  background: linear-gradient(90deg, #e5e8ef 0%, #e5e8ef 50%, #373d4a 50%, #373d4a 100%);
}

.theme-preview-system .theme-preview-sidebar i {
  background: linear-gradient(90deg, #cdd2de 0%, #cdd2de 50%, #636c7e 50%, #636c7e 100%);
}

.theme-preview-system .theme-preview-window {
  background: linear-gradient(90deg, #fff 0%, #fff 50%, #323947 50%, #323947 100%);
}

.theme-preview-system .preview-line {
  background: linear-gradient(90deg, #d3d7e1 0%, #d3d7e1 50%, #687286 50%, #687286 100%);
}

.theme-preview-system .preview-block {
  background: linear-gradient(90deg, #eef0f5 0%, #eef0f5 50%, #414958 50%, #414958 100%);
}

.theme-option-meta {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 10px 3px 3px;
}

.theme-option-meta strong {
  display: flex;
  align-items: center;
  gap: 5px;
  color: var(--text);
  font-size: 10px;
  font-weight: 700;
}

.theme-option-meta strong .icon {
  color: var(--muted);
}

.theme-option-meta small {
  color: var(--subtle);
  font-size: 9px;
}

.selection-mark {
  position: absolute;
  top: 12px;
  right: 12px;
  width: 18px;
  height: 18px;
  display: grid;
  place-items: center;
  color: #fff;
  border-radius: 50%;
  background: var(--accent);
}

.accent-options {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.accent-option {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  height: 34px;
  padding: 0 10px 0 7px;
  color: var(--muted);
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--field);
  font-size: 10px;
  font-weight: 650;
}

.accent-option:hover {
  color: var(--text);
  border-color: #cbd0dc;
}

.accent-option.is-selected {
  color: var(--text);
  border-color: var(--accent);
  background: var(--accent-soft);
}

.accent-option.is-selected .icon {
  color: var(--accent);
}

.accent-swatch {
  width: 17px;
  height: 17px;
  border-radius: 50%;
  box-shadow: inset 0 0 0 2px rgba(255, 255, 255, 0.35);
}

.density-options {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.density-option {
  min-width: 0;
  position: relative;
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 11px;
  color: var(--text);
  border: 1px solid var(--border);
  border-radius: 9px;
  background: var(--field);
  text-align: left;
}

.density-option:hover {
  border-color: #cbd0dc;
}

.density-option.is-selected {
  border-color: var(--accent);
  background: var(--accent-soft);
}

.density-option > span:nth-child(2) {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.density-option strong {
  font-size: 10px;
  font-weight: 700;
}

.density-option small {
  color: var(--muted);
  font-size: 9px;
}

.density-option > .icon {
  margin-left: auto;
  color: var(--accent);
}

.density-visual {
  width: 34px;
  height: 34px;
  display: flex;
  flex: 0 0 34px;
  flex-direction: column;
  justify-content: center;
  gap: 4px;
  padding: 7px;
  border: 1px solid var(--border);
  border-radius: 7px;
  background: var(--surface);
}

.density-visual i {
  height: 3px;
  display: block;
  border-radius: 3px;
  background: var(--subtle);
}

.density-visual i:nth-child(2) {
  width: 72%;
}

.density-compact {
  gap: 2px;
}

.shortcut-list {
  display: flex;
  flex-direction: column;
}

.shortcut-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 39px;
  border-top: 1px solid var(--border);
  color: var(--muted);
  font-size: 10px;
}

.shortcut-row:first-child {
  border-top: 0;
}

.key-combo {
  display: inline-flex;
  gap: 4px;
}

.key-combo kbd {
  min-width: 21px;
  height: 21px;
  display: grid;
  place-items: center;
  padding: 0 5px;
  color: var(--text);
  border: 1px solid var(--border);
  border-bottom-width: 2px;
  border-radius: 5px;
  background: var(--surface-muted);
  font-family: inherit;
  font-size: 9px;
  font-weight: 650;
}

.info-callout {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 19px;
  padding: 10px 11px;
