  border: 1px solid color-mix(in srgb, var(--accent) 13%, var(--border));
  border-radius: 8px;
  background: color-mix(in srgb, var(--accent-soft) 48%, var(--surface));
  font-size: 10px;
}

.info-callout .icon {
  flex: 0 0 auto;
  color: var(--accent);
}

@media (max-width: 1080px) {
  .topbar {
    padding: 0 32px;
  }

  .page-content {
    padding-right: 32px;
    padding-left: 32px;
  }

  .settings-layout {
    gap: 24px;
  }
}

@media (max-width: 860px) {
  .app-shell {
    grid-template-columns: 76px minmax(0, 1fr);
  }

  .sidebar {
    padding-right: 10px;
    padding-left: 10px;
  }

  .brand-row {
    justify-content: center;
    padding: 0;
  }

  .brand-name,
  .brand-version,
  .workspace-switcher-copy,
  .workspace-switcher > .icon,
  .nav-item > span:not(.nav-icon):not(.nav-count),
  .help-link > span:not(.nav-icon),
  .account-copy,
  .account-chip > .icon {
    display: none;
  }

  .workspace-switcher {
    justify-content: center;
    padding: 8px;
  }

  .nav-label {
    padding-right: 0;
    padding-left: 0;
    text-align: center;
    font-size: 8px;
  }

  .nav-item,
  .help-link {
    justify-content: center;
    padding: 0;
  }

  .nav-count {
    position: absolute;
    margin: -19px 0 0 22px;
    min-width: 14px;
    padding: 1px 3px;
    font-size: 8px;
  }

  .account-chip {
    justify-content: center;
    padding-right: 0;
    padding-left: 0;
  }

  .settings-layout {
    grid-template-columns: 175px minmax(0, 1fr);
  }

  .section-nav-copy small {
    display: none;
  }
}

@media (max-width: 700px) {
  .app-shell {
    display: block;
  }

  .sidebar {
    display: none;
  }

  .topbar {
    height: 62px;
    padding: 0 19px;
  }

  .command-button span,
  .command-button kbd {
    display: none;
  }

  .command-button {
    width: 32px;
    justify-content: center;
    padding: 0;
  }

  .page-content {
    padding: 31px 19px 55px;
  }

  .page-heading {
    align-items: flex-start;
    flex-direction: column;
    gap: 22px;
    margin-bottom: 29px;
  }

  .heading-actions {
    width: 100%;
    flex-wrap: wrap;
  }

  .save-state {
    width: 100%;
    order: -1;
    margin: 0 0 1px;
  }

  .settings-layout {
    display: block;
  }

  .section-menu {
    position: static;
    margin-bottom: 24px;
  }

  .section-menu-title {
    display: none;
  }

  .section-tabs {
    overflow-x: auto;
    flex-direction: row;
    gap: 7px;
    padding: 2px;
    scrollbar-width: none;
  }

  .section-tabs::-webkit-scrollbar {
    display: none;
  }

  .section-tab {
    width: auto;
    min-width: max-content;
    min-height: 38px;
    padding: 5px 9px 5px 6px;
  }

  .section-nav-icon {
    width: 26px;
    height: 26px;
    flex-basis: 26px;
  }

  .section-nav-copy small,
  .section-nav-arrow,
  .tip-card {
    display: none;
  }

  .section-nav-copy strong {
    font-size: 10px;
  }

  .card {
    padding: 20px 18px;
  }

  .profile-card {
    flex-wrap: wrap;
    padding: 16px;
  }

  .profile-card .ghost-button {
    width: 100%;
    margin-top: 4px;
  }
}

@media (max-width: 480px) {
  .topbar-actions {
    gap: 7px;
  }

  .breadcrumbs {
    font-size: 11px;
  }

  .page-heading h1 {
    font-size: 34px;
  }

  .heading-actions .secondary-button,
  .heading-actions .primary-button {
    flex: 1;
  }

  .field-grid,
  .theme-grid,
  .density-options {
    grid-template-columns: minmax(0, 1fr);
  }

  .field-wide {
    grid-column: auto;
  }

  .theme-preview {
    height: 86px;
  }
}

