type ToggleProps = {
  label: string;
  description: string;
  checked: boolean;
  onChange: (value: boolean) => void;
};

function Toggle({ label, description, checked, onChange }: ToggleProps) {
  return (
    <div className='setting-row'>
      <div className='setting-copy'>
        <strong className='setting-label'>{label}</strong>
        <span className='setting-description'>{description}</span>
      </div>
      <button
        className={`toggle ${checked ? 'is-on' : ''}`}
        type='button'
        aria-label={label}
        aria-pressed={checked}
        onClick={() => onChange(!checked)}
      >
        <span className='toggle-thumb' />
      </button>
    </div>
  );
}

type SelectControlProps = {
  label: string;
  value: string;
  options: string[];
  onChange: (value: string) => void;
};

function SelectControl({ label, value, options, onChange }: SelectControlProps) {
  const inputId = `select-${label.toLowerCase().replace(/[^a-z0-9]+/g, '-')}`;

  return (
    <label className='field-label' htmlFor={inputId}>
      <span>{label}</span>
      <span className='select-wrap'>
        <select id={inputId} value={value} onChange={(event) => onChange(event.target.value)}>
          {options.map((option) => (
            <option key={option} value={option}>
              {option}
            </option>
          ))}
        </select>
        <Icon name='chevron-down' size={15} />
      </span>
    </label>
  );
}

