  { label: 'Editor', description: 'Writing canvas', icon: 'type' },
  { label: 'Shortcuts', description: 'Keyboard map', icon: 'keyboard' },
];

const navItems: Array<{ label: string; icon: IconName; count?: string }> = [
  { label: 'All notes', icon: 'note' },
