];

export default function App() {
  const [activeTab, setActiveTab] = useState<SettingTab>('General');
  const [displayName, setDisplayName] = useState('Maya Chen');
  const [email, setEmail] = useState('maya@lumen.page');
  const [autoSave, setAutoSave] = useState(true);
  const [spellcheck, setSpellcheck] = useState(true);
  const [theme, setTheme] = useState<ThemeName>('Paper');
  const [darkMode, setDarkMode] = useState(false);
  const [compactMode, setCompactMode] = useState(false);
  const [editorFont, setEditorFont] = useState('System Sans');
  const [fontSize, setFontSize] = useState('Medium');
  const [focusMode, setFocusMode] = useState(false);
  const [showBreadcrumbs, setShowBreadcrumbs] = useState(true);
  const [saved, setSaved] = useState(false);

  const changeTheme = (nextTheme: ThemeName) => {
    setTheme(nextTheme);
    setDarkMode(nextTheme === 'Night');
    setSaved(false);
  };

  const activeContent = (() => {
    if (activeTab === 'General') {
      return (
        <GeneralSettings
          displayName={displayName}
          onDisplayNameChange={setDisplayName}
          email={email}
          onEmailChange={setEmail}
          autoSave={autoSave}
          onAutoSaveChange={setAutoSave}
          spellcheck={spellcheck}
          onSpellcheckChange={setSpellcheck}
        />
      );
    }

    if (activeTab === 'Appearance') {
      return (
        <AppearanceSettings
          theme={theme}
          onThemeChange={changeTheme}
          darkMode={darkMode}
          onDarkModeChange={setDarkMode}
          compactMode={compactMode}
          onCompactModeChange={setCompactMode}
        />
      );
    }

    if (activeTab === 'Editor') {
      return (
        <EditorSettings
          font={editorFont}
          onFontChange={setEditorFont}
          fontSize={fontSize}
          onFontSizeChange={setFontSize}
          focusMode={focusMode}
          onFocusModeChange={setFocusMode}
          showBreadcrumbs={showBreadcrumbs}
          onShowBreadcrumbsChange={setShowBreadcrumbs}
        />
      );
    }

    return <ShortcutsSettings />;
  })();

  return (
    <div className={`app-root ${darkMode ? 'theme-dark' : ''}`}>
      <span className='ambient ambient-one' />
      <span className='ambient ambient-two' />

      <div className='app-frame'>
        <aside className='side-rail'>
          <div className='brand'>
            <span className='brand-mark'><Icon name='sparkle' size={18} strokeWidth={1.7} /></span>
            <span className='brand-wordmark'><span className='brand-name'>lumen</span><span className='brand-dot'>.</span></span>
          </div>

          <button className='workspace-switcher' type='button'>
            <span className='workspace-symbol'><Icon name='note' size={15} /></span>
            <span className='workspace-switcher-copy'>
              <span className='workspace-name'>Maya&apos;s space</span>
              <span className='workspace-type'>Personal workspace</span>
            </span>
            <Icon name='chevron-down' size={15} />
          </button>

          <div className='sidebar-label'>Workspace</div>
          <nav className='sidebar-nav' aria-label='Workspace navigation'>
            {navItems.map((item) => (
              <button className='nav-item' type='button' key={item.label}>
                <span className='nav-icon'><Icon name={item.icon} size={17} /></span>
                <span className='nav-item-copy'>{item.label}</span>
                {item.count && <span className='nav-count'>{item.count}</span>}
              </button>
            ))}
          </nav>

          <div className='sidebar-bottom'>
            <div className='sidebar-divider' />
            <button className='nav-item is-active' type='button' aria-current='page'>
              <span className='nav-icon'><Icon name='settings' size={17} /></span>
              <span className='nav-item-copy'>Settings</span>
            </button>
            <div className='mini-profile'>
              <span className='sidebar-avatar'>MC</span>
              <span className='mini-profile-copy'>
                <strong className='mini-profile-name'>Maya Chen</strong>
                <span className='mini-profile-email'>Free plan</span>
              </span>
              <button className='sidebar-menu-button' type='button' aria-label='Account menu'>
                <Icon name='chevron-right' size={15} />
              </button>
            </div>
          </div>
        </aside>

        <section className='settings-pane'>
          <header className='topbar'>
            <button className='back-link' type='button'>
              <Icon name='arrow-left' size={16} />
              <span>Back to notes</span>
            </button>
            <div className='topbar-tools'>
              <span className='sync-state'><span className='status-dot' />Synced just now</span>
              <button className='topbar-icon-button' type='button' aria-label='Search notes'>
                <Icon name='search' size={17} />
              </button>
              <button className='topbar-icon-button' type='button' aria-label='Notifications'>
                <Icon name='bell' size={17} />
              </button>
              <button className='account-button' type='button'>
                <span className='account-avatar'>MC</span>
                <span className='account-name'>Maya</span>
                <Icon name='chevron-down' size={14} />
              </button>
            </div>
          </header>

          <main className='settings-main'>
            <div className='main-inner'>
              <div className='settings-heading'>
                <div className='heading-copy'>
                  <span className='eyebrow'>Workspace settings</span>
                  <h1>Settings</h1>
                  <p>Shape the way your notes look, feel, and move.</p>
                </div>
                <div className='heading-aside'>
                  <span className='plan-pill'>FREE</span>
                  <span className='heading-aside-label'>Personal workspace</span>
                </div>
              </div>

              <div className='settings-layout'>
                <nav className='section-nav' aria-label='Settings sections'>
                  <span className='section-nav-label'>Manage</span>
                  {settingsTabs.map((tab) => (
                    <button
                      className={`section-tab ${activeTab === tab.label ? 'is-active' : ''}`}
                      type='button'
                      key={tab.label}
                      aria-current={activeTab === tab.label ? 'page' : undefined}
                      onClick={() => {
                        setActiveTab(tab.label);
                        setSaved(false);
                      }}
                    >
                      <span className='tab-icon'><Icon name={tab.icon} size={16} /></span>
                      <span className='tab-text'>
                        <strong className='tab-title'>{tab.label}</strong>
                        <small className='tab-description'>{tab.description}</small>
                      </span>
                      {activeTab === tab.label && <span className='active-dot' />}
                    </button>
                  ))}

                  <div className='help-card'>
                    <span className='help-icon'><Icon name='help' size={16} /></span>
                    <strong className='help-card-title'>Need a hand?</strong>
                    <p>Find quick answers in the Lumen help center.</p>
                    <button className='help-link' type='button'>
                      Open help center <Icon name='external' size={13} />
                    </button>
                  </div>
                </nav>

                <div className='content-column'>
                  {activeContent}
                  <div className='content-actions'>
                    <span className='save-note'><Icon name='lock' size={14} />Private to this workspace</span>
                    <button
                      className={`save-button ${saved ? 'is-saved' : ''}`}
                      type='button'
                      onClick={() => setSaved(true)}
                    >
                      <Icon name={saved ? 'check' : 'check-circle'} size={16} />
                      {saved ? 'Saved' : 'Save changes'}
                    </button>
                  </div>
                </div>
              </div>
            </div>
          </main>
        </section>
      </div>
    </div>
  );
}

