  --ink: #ebf2ed;
  --muted: #98aaa0;
  --faint: #687b70;
  --line: #35433b;
  --soft: #202a25;
  --accent: #79bd9b;
  --accent-strong: #a4d7bc;
  --accent-soft: #294b3d;
  --accent-wash: #20362c;
  --warning: #d5a264;
  --shadow: 0 24px 70px rgba(0, 0, 0, 0.34), 0 3px 12px rgba(0, 0, 0, 0.18);
  color-scheme: dark;
  background: radial-gradient(circle at 13% 20%, rgba(121, 91, 55, 0.22), transparent 28%), radial-gradient(circle at 86% 78%, rgba(53, 103, 76, 0.28), transparent 30%), #111714;
}

.ambient {
  position: absolute;
  pointer-events: none;
  border-radius: 999px;
  filter: blur(1px);
}

.ambient-one {
  top: -160px;
  left: -100px;
  width: 360px;
  height: 360px;
  border: 1px solid rgba(255, 255, 255, 0.44);
}

.ambient-two {
  right: -80px;
  bottom: -160px;
  width: 390px;
  height: 390px;
  border: 1px solid rgba(255, 255, 255, 0.34);
}

.app-frame {
  position: relative;
  z-index: 1;
  display: grid;
  width: min(1190px, 100%);
  height: min(780px, calc(100vh - 64px));
  min-height: 700px;
  overflow: hidden;
  grid-template-columns: 226px minmax(0, 1fr);
  border: 1px solid rgba(41, 70, 55, 0.1);
  border-radius: 26px;
  background: var(--panel);
  box-shadow: var(--shadow);
}

.app-root.theme-dark .app-frame {
  border-color: rgba(217, 242, 226, 0.08);
}

.side-rail {
  display: flex;
  min-width: 0;
  flex-direction: column;
  padding: 25px 13px 16px;
  border-right: 1px solid var(--line);
  background: var(--rail);
}

.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 0 10px 27px;
}

.brand-mark {
  display: grid;
  width: 34px;
  height: 34px;
  place-items: center;
  border-radius: 11px;
  color: #f5fbf5;
  background: linear-gradient(145deg, #378462, #1d5a43);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.24), 0 6px 12px rgba(29, 88, 63, 0.18);
}

.brand-wordmark {
  display: inline-flex;
  align-items: baseline;
  letter-spacing: -0.035em;
}

.brand-name {
  font-size: 19px;
  font-weight: 700;
}

.brand-dot {
  color: var(--accent);
  font-size: 21px;
  font-weight: 700;
}

.workspace-switcher {
  display: flex;
  width: 100%;
  align-items: center;
  gap: 9px;
  padding: 9px 9px;
  border: 1px solid var(--line);
  border-radius: 13px;
  color: var(--ink);
  text-align: left;
  background: var(--card);
  box-shadow: 0 2px 4px rgba(32, 57, 43, 0.03);
}

.workspace-switcher:hover,
.workspace-switcher:focus-visible {
  border-color: var(--accent);
}

.workspace-symbol {
  display: grid;
  width: 29px;
  height: 29px;
  flex: 0 0 29px;
  place-items: center;
  border-radius: 9px;
  color: var(--accent);
  background: var(--accent-soft);
}

.workspace-switcher-copy {
  display: grid;
  min-width: 0;
  flex: 1;
  gap: 2px;
}

.workspace-name,
.workspace-type {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.workspace-name {
  font-size: 12px;
  font-weight: 700;
}

.workspace-type {
  color: var(--muted);
  font-size: 10px;
}

.sidebar-label {
  margin: 27px 10px 8px;
  color: var(--faint);
  font-size: 10px;
  font-weight: 750;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.sidebar-nav {
  display: grid;
  gap: 4px;
}

.nav-item {
  position: relative;
  display: flex;
  width: 100%;
  align-items: center;
  gap: 10px;
  min-height: 40px;
  padding: 5px 9px;
  border: 0;
  border-radius: 11px;
  color: var(--muted);
  text-align: left;
  background: transparent;
  transition: color 160ms ease, background 160ms ease, transform 160ms ease;
}

.nav-item:hover {
  color: var(--ink);
  background: rgba(255, 255, 255, 0.56);
}

.theme-dark .nav-item:hover {
  background: rgba(255, 255, 255, 0.05);
}

.nav-item.is-active {
  color: var(--accent-strong);
  background: var(--card);
  box-shadow: 0 4px 12px rgba(32, 58, 44, 0.05);
}

.nav-item.is-active::before {
  position: absolute;
  top: 10px;
  bottom: 10px;
  left: -13px;
  width: 3px;
  border-radius: 0 5px 5px 0;
  content: '';
  background: var(--accent);
}

.nav-icon {
  display: grid;
  width: 29px;
  height: 29px;
  flex: 0 0 29px;
  place-items: center;
  border-radius: 9px;
  color: currentColor;
}

.nav-item-copy {
  overflow: hidden;
  flex: 1;
  font-size: 12px;
  font-weight: 600;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.nav-count {
  display: grid;
  min-width: 20px;
  height: 20px;
  padding: 0 5px;
  place-items: center;
  border-radius: 7px;
  color: var(--accent-strong);
  font-size: 10px;
  font-weight: 750;
  background: var(--accent-soft);
}

.sidebar-bottom {
  display: grid;
  gap: 6px;
  margin-top: auto;
}

.sidebar-divider {
  height: 1px;
  margin: 0 9px 8px;
  background: var(--line);
}

.mini-profile {
  display: flex;
  align-items: center;
  gap: 9px;
  margin: 9px 3px 0;
  padding: 8px 7px;
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.38);
}

.theme-dark .mini-profile {
  background: rgba(255, 255, 255, 0.04);
}

.sidebar-avatar,
.account-avatar {
  display: grid;
  place-items: center;
  border-radius: 50%;
  color: #f5fbf5;
  font-weight: 750;
  background: linear-gradient(145deg, #d49b72, #a96756);
}

.sidebar-avatar {
  width: 28px;
  height: 28px;
  flex: 0 0 28px;
  font-size: 9px;
}

.mini-profile-copy {
  display: grid;
  min-width: 0;
  flex: 1;
  gap: 2px;
}

.mini-profile-name {
  overflow: hidden;
  font-size: 11px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mini-profile-email {
  color: var(--muted);
  font-size: 10px;
}

.sidebar-menu-button {
  display: grid;
  width: 24px;
  height: 24px;
  padding: 0;
  place-items: center;
  border: 0;
  color: var(--muted);
  background: transparent;
}

.settings-pane {
  display: flex;
  min-width: 0;
  min-height: 0;
  flex-direction: column;
  background: var(--canvas);
}

.topbar {
  display: flex;
  min-height: 72px;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 0 34px;
  border-bottom: 1px solid var(--line);
}

.back-link,
.topbar-icon-button,
.account-button {
  border: 0;
  color: var(--muted);
  background: transparent;
}

.back-link {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 7px 0;
  font-size: 11px;
  font-weight: 650;
}

.back-link:hover {
  color: var(--accent-strong);
}

.topbar-tools {
  display: flex;
  align-items: center;
  gap: 8px;
}

.sync-state {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  margin-right: 9px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 600;
}

.status-dot,
.preview-status span,
.connected-badge span {
  display: inline-block;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #4ca274;
  box-shadow: 0 0 0 3px rgba(76, 162, 116, 0.12);
}

.topbar-icon-button {
  display: grid;
  width: 31px;
  height: 31px;
  place-items: center;
  border-radius: 9px;
}

.topbar-icon-button:hover {
  color: var(--ink);
  background: var(--soft);
}

.account-button {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  margin-left: 3px;
  padding: 3px 3px 3px 5px;
  border-radius: 10px;
  color: var(--ink);
}

.account-button:hover {
  background: var(--soft);
}

.account-avatar {
  width: 27px;
  height: 27px;
  font-size: 9px;
}

.account-name {
  font-size: 11px;
  font-weight: 700;
}

.settings-main {
  min-height: 0;
  overflow: auto;
  padding: 40px 48px 45px;
  scrollbar-color: var(--line) transparent;
  scrollbar-width: thin;
}

.main-inner {
  width: min(960px, 100%);
  margin: 0 auto;
}

.settings-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
}

.heading-copy {
  min-width: 0;
}

.eyebrow {
  display: block;
  margin-bottom: 11px;
  color: var(--accent);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.heading-copy h1 {
  margin: 0;
  color: var(--ink);
  font-size: 39px;
  font-weight: 720;
  letter-spacing: -0.055em;
  line-height: 0.98;
}

.heading-copy p {
  margin: 12px 0 0;
  color: var(--muted);
  font-size: 13px;
}

.heading-aside {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  padding: 7px 10px 7px 7px;
  border: 1px solid var(--line);
  border-radius: 11px;
  background: var(--card);
}

.plan-pill {
  padding: 4px 7px;
  border-radius: 6px;
  color: var(--accent-strong);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.08em;
  background: var(--accent-soft);
}

.heading-aside-label {
  color: var(--muted);
  font-size: 10px;
  font-weight: 650;
}

.settings-layout {
  display: grid;
  grid-template-columns: 164px minmax(0, 1fr);
  align-items: start;
  gap: 43px;
  margin-top: 39px;
}

.section-nav {
  min-width: 0;
}

.section-nav-label {
  display: block;
  margin: 0 10px 9px;
  color: var(--faint);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.section-tab {
  display: grid;
  width: 100%;
  grid-template-columns: 29px minmax(0, 1fr) 4px;
  align-items: center;
  gap: 9px;
  padding: 8px 8px;
  border: 1px solid transparent;
  border-radius: 12px;
  color: var(--muted);
  text-align: left;
  background: transparent;
  transition: color 160ms ease, background 160ms ease, border-color 160ms ease;
}

.section-tab:hover {
  color: var(--ink);
  background: var(--soft);
}

.section-tab.is-active {
  border-color: rgba(40, 108, 82, 0.1);
  color: var(--accent-strong);
  background: var(--accent-wash);
}

.tab-icon {
  display: grid;
  width: 29px;
  height: 29px;
  place-items: center;
  border-radius: 9px;
  background: rgba(255, 255, 255, 0.56);
}

.theme-dark .tab-icon {
  background: rgba(255, 255, 255, 0.05);
}

.section-tab.is-active .tab-icon {
  background: var(--accent-soft);
}

.tab-text {
  display: grid;
  min-width: 0;
  gap: 3px;
}

.tab-title {
  overflow: hidden;
  font-size: 11px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tab-description {
  overflow: hidden;
  color: var(--muted);
  font-size: 9px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.section-tab.is-active .tab-description {
  color: var(--accent);
}

.active-dot {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--accent);
}

.help-card {
  margin-top: 27px;
  padding: 14px 13px 13px;
  border: 1px solid rgba(40, 108, 82, 0.12);
  border-radius: 15px;
  background: linear-gradient(150deg, var(--accent-wash), var(--card));
}

.help-icon {
  display: grid;
  width: 28px;
  height: 28px;
  margin-bottom: 11px;
  place-items: center;
  border-radius: 9px;
  color: var(--accent);
  background: var(--accent-soft);
}

.help-card-title {
  display: block;
  font-size: 11px;
}

.help-card p {
  margin: 6px 0 10px;
  color: var(--muted);
  font-size: 10px;
  line-height: 1.45;
}

.help-link {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 0;
  border: 0;
  color: var(--accent-strong);
  font-size: 10px;
  font-weight: 750;
  background: transparent;
}

.help-link:hover {
  color: var(--accent);
}

.content-column {
  min-width: 0;
}

.settings-section {
  min-width: 0;
}

.content-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 16px;
}

.content-header h2 {
  margin: 0;
  color: var(--ink);
  font-size: 21px;
  font-weight: 720;
  letter-spacing: -0.035em;
}

.content-header p {
  max-width: 450px;
  margin: 6px 0 0;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.5;
}

.card-stack {
  display: grid;
  gap: 14px;
}

.setting-card {
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: var(--card);
  box-shadow: 0 4px 13px rgba(35, 58, 44, 0.025);
}

.card-title {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding: 19px 21px 0;
}

.card-title h3 {
  margin: 0;
  color: var(--ink);
  font-size: 13px;
  font-weight: 750;
  letter-spacing: -0.01em;
}

.card-title p {
  margin: 5px 0 0;
  color: var(--muted);
  font-size: 10px;
  line-height: 1.4;
}

.card-symbol {
  display: grid;
  width: 29px;
  height: 29px;
  flex: 0 0 29px;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 9px;
  color: var(--muted);
  background: var(--soft);
}

.profile-summary {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 18px 21px 0;
}

.avatar-large {
  display: grid;
  width: 43px;
  height: 43px;
  flex: 0 0 43px;
  place-items: center;
  border: 3px solid var(--card);
  border-radius: 14px;
  color: #fff8f1;
  font-size: 12px;
  font-weight: 800;
  background: linear-gradient(145deg, #dcaa7d, #a96958);
  box-shadow: 0 4px 10px rgba(145, 87, 66, 0.16);
}

.profile-summary-copy {
  display: grid;
  min-width: 0;
  flex: 1;
  gap: 4px;
}

.profile-name {
  overflow: hidden;
  color: var(--ink);
  font-size: 12px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.profile-role {
  color: var(--muted);
  font-size: 10px;
}

.subtle-button {
  padding: 7px 10px;
  border: 1px solid var(--line);
  border-radius: 8px;
  color: var(--accent-strong);
  font-size: 10px;
  font-weight: 700;
  background: var(--card);
}

.subtle-button:hover {
  border-color: var(--accent);
  background: var(--accent-wash);
}

.profile-fields,
.editor-fields {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 13px;
  padding: 19px 21px 21px;
}

.field-label {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 0;
  color: var(--muted);
  font-size: 10px;
  font-weight: 750;
}

.field-label > span:first-child {
  margin-bottom: 7px;
}

.text-input,
.select-wrap select {
  width: 100%;
  min-width: 0;
  height: 37px;
  padding: 0 11px;
  border: 1px solid var(--line);
  border-radius: 9px;
  outline: 0;
  color: var(--ink);
  font-size: 11px;
  font-weight: 600;
  background: var(--panel);
  transition: border-color 160ms ease, box-shadow 160ms ease;
}

.text-input:focus,
.select-wrap select:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(40, 108, 82, 0.11);
}

.input-with-icon {
  position: relative;
  display: block;
}

.input-with-icon > svg {
  position: absolute;
  top: 11px;
  left: 12px;
  z-index: 1;
  color: var(--faint);
}

.input-with-icon .text-input {
  padding-left: 35px;
}

.select-wrap {
  position: relative;
  display: block;
}

.select-wrap select {
  appearance: none;
  padding-right: 30px;
}

.select-wrap > svg {
  position: absolute;
  top: 11px;
  right: 10px;
  pointer-events: none;
  color: var(--muted);
}

.workspace-row {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 15px 21px 18px;
  border-top: 1px solid var(--line);
}

.workspace-icon {
  display: grid;
  width: 31px;
  height: 31px;
  flex: 0 0 31px;
  place-items: center;
  border-radius: 9px;
  color: var(--accent);
  background: var(--accent-soft);
}

.workspace-row-copy {
  display: grid;
  min-width: 0;
  flex: 1;
  gap: 3px;
}

.workspace-row-copy strong {
  font-size: 11px;
}

.workspace-row-copy span {
  overflow: hidden;
  color: var(--muted);
  font-size: 10px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.connected-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--accent-strong);
  font-size: 10px;
  font-weight: 750;
}

.connected-badge span {
  width: 5px;
  height: 5px;
  box-shadow: none;
}

.setting-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  padding: 15px 21px;
}

.card-title + .setting-row {
  margin-top: 13px;
}

.setting-row + .setting-row {
  border-top: 1px solid var(--line);
}

.setting-copy {
  display: grid;
  min-width: 0;
  gap: 4px;
}

.setting-label {
  color: var(--ink);
  font-size: 11px;
}

.setting-description {
  color: var(--muted);
  font-size: 10px;
  line-height: 1.4;
}

.toggle {
  position: relative;
  width: 41px;
  height: 24px;
  flex: 0 0 41px;
  padding: 2px;
  border: 0;
  border-radius: 999px;
  background: #d9e0da;
  transition: background 160ms ease, box-shadow 160ms ease;
}

.toggle:hover {
  box-shadow: 0 0 0 3px rgba(40, 108, 82, 0.08);
}

.toggle.is-on {
  background: var(--accent);
}

.toggle-thumb {
  display: block;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: #ffffff;
  box-shadow: 0 2px 4px rgba(20, 40, 29, 0.16);
  transition: transform 160ms ease;
}

.toggle.is-on .toggle-thumb {
  transform: translateX(17px);
}

.theme-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
  padding: 19px 21px 21px;
}

.theme-option {
  min-width: 0;
  padding: 7px;
  border: 1px solid var(--line);
  border-radius: 12px;
  color: var(--ink);
  text-align: left;
  background: var(--card);
  transition: border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
}

.theme-option:hover {
  transform: translateY(-1px);
  border-color: var(--accent);
}

.theme-option.is-selected {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(40, 108, 82, 0.1);
}

.theme-preview {
  display: grid;
  min-height: 65px;
  grid-template-columns: 29% 1fr;
  gap: 6px;
  padding: 7px;
  overflow: hidden;
  border: 1px solid rgba(35, 55, 43, 0.1);
  border-radius: 8px;
}

.preview-sidebar {
  border-radius: 4px;
}

.preview-body {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 4px 2px;
}

.preview-bar,
.preview-line {
  display: block;
  height: 4px;
  border-radius: 5px;
}

.preview-bar {
  width: 58%;
  margin-bottom: 4px;
}

.preview-line {
  width: 88%;
}

.preview-line-short {
  width: 67%;
}

.preview-line-small {
  width: 47%;
}

.theme-paper {
  background: #f8f5ee;
}

.theme-paper .preview-sidebar {
  background: #e6e0d3;
}

.theme-paper .preview-bar {
  background: #5f8b71;
}

.theme-paper .preview-line {
  background: #d6d0c5;
}

.theme-mist {
  background: #edf3f0;
}

.theme-mist .preview-sidebar {
  background: #cfe1d9;
}

.theme-mist .preview-bar {
  background: #4e8c75;
}

.theme-mist .preview-line {
  background: #c7d8d0;
}

.theme-night {
  background: #202823;
}

.theme-night .preview-sidebar {
  background: #304339;
}

.theme-night .preview-bar {
  background: #81c39d;
}

.theme-night .preview-line {
  background: #51655a;
}

.theme-option-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  padding: 8px 2px 1px;
  color: var(--ink);
  font-size: 10px;
  font-weight: 700;
}

.radio-mark {
  display: grid;
  width: 14px;
  height: 14px;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 50%;
}

.radio-mark span {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: transparent;
}

.theme-option.is-selected .radio-mark {
  border-color: var(--accent);
}

.theme-option.is-selected .radio-mark span {
  background: var(--accent);
}

.editor-preview {
  margin: 0 21px 21px;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: 11px;
  background: var(--soft);
}

.editor-preview-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 9px;
  color: var(--muted);
  font-size: 9px;
  font-weight: 750;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.preview-status {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--accent);
  letter-spacing: 0;
  text-transform: none;
}

.preview-status span {
  width: 5px;
  height: 5px;
  box-shadow: none;
}

.editor-sheet {
  padding: 18px 20px 19px;
  border: 1px solid rgba(44, 68, 53, 0.08);
  border-radius: 8px;
  background: var(--card);
}

.editor-sheet-kicker {
  color: var(--faint);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.editor-sheet h4 {
  margin: 12px 0 7px;
  color: var(--ink);
  font-size: 19px;
  font-weight: 650;
  letter-spacing: -0.04em;
}

.editor-sheet p {
  margin: 0;
  color: var(--muted);
  font-size: 11px;
}

.shortcut-list {
  padding: 10px 0 4px;
}

.shortcut-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 13px 21px;
  border-top: 1px solid var(--line);
}

.shortcut-row:first-child {
  border-top: 0;
}

.shortcut-action {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 10px;
}

.shortcut-icon {
  display: grid;
  width: 29px;
  height: 29px;
  flex: 0 0 29px;
  place-items: center;
  border-radius: 9px;
  color: var(--muted);
  background: var(--soft);
}

.shortcut-action > span:last-child {
  display: grid;
  min-width: 0;
  gap: 3px;
}

.shortcut-action strong {
  overflow: hidden;
  color: var(--ink);
  font-size: 11px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.shortcut-action small {
  overflow: hidden;
  color: var(--muted);
  font-size: 10px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.shortcut-keys {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  gap: 4px;
}

.keycap {
  display: grid;
  min-width: 24px;
  height: 24px;
  padding: 0 6px;
  place-items: center;
  border: 1px solid var(--line);
  border-bottom-width: 2px;
  border-radius: 6px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 750;
  background: var(--panel);
}

.shortcut-note {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 1px 3px;
  color: var(--muted);
  font-size: 10px;
}

.content-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 15px;
  margin-top: 17px;
}

.save-note {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-right: 2px;
  color: var(--muted);
  font-size: 10px;
}

.save-button {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  min-height: 36px;
  padding: 0 14px;
  border: 1px solid var(--accent);
  border-radius: 9px;
  color: #f6fcf7;
  font-size: 11px;
  font-weight: 750;
  background: var(--accent);
  box-shadow: 0 4px 9px rgba(40, 108, 82, 0.17);
  transition: background 160ms ease, transform 160ms ease, box-shadow 160ms ease;
}

.save-button:hover {
  transform: translateY(-1px);
  background: var(--accent-strong);
  box-shadow: 0 6px 13px rgba(40, 108, 82, 0.22);
}

.save-button.is-saved {
  border-color: #4ca274;
  background: #4ca274;
}

button:focus-visible,
input:focus-visible,
select:focus-visible {
  outline: 3px solid rgba(40, 108, 82, 0.24);
  outline-offset: 2px;
}

@media (max-width: 1050px) {
  .app-root {
    padding: 20px;
  }

  .settings-main {
    padding-right: 35px;
    padding-left: 35px;
  }

  .settings-layout {
    grid-template-columns: 150px minmax(0, 1fr);
    gap: 29px;
  }
}

@media (max-width: 780px) {
  .app-root {
    align-items: stretch;
    padding: 0;
  }

  .app-frame {
    width: 100%;
    height: auto;
    min-height: 100vh;
    grid-template-columns: 1fr;
    border-radius: 0;
  }

  .side-rail {
    display: none;
  }

  .settings-main {
    overflow: visible;
    padding: 31px 24px 36px;
  }

  .topbar {
    padding: 0 24px;
  }

  .settings-layout {
    grid-template-columns: 1fr;
    gap: 27px;
    margin-top: 31px;
  }

  .section-nav {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 6px;
  }

  .section-nav-label,
  .section-tab small,
  .help-card {
    display: none;
  }

  .section-tab {
    grid-template-columns: 1fr;
    justify-items: center;
    gap: 5px;
    padding: 9px 5px;
    text-align: center;
  }

  .section-tab .active-dot {
    display: none;
  }

  .tab-title {
    font-size: 10px;
  }
}

@media (max-width: 520px) {
  .settings-main {
    padding: 27px 16px 30px;
  }

  .topbar {
    padding: 0 16px;
  }

  .sync-state,
  .account-name {
    display: none;
  }

  .topbar-tools {
    gap: 4px;
  }

  .settings-heading {
    display: block;
  }

  .heading-aside {
    margin-top: 15px;
  }

  .heading-copy h1 {
    font-size: 35px;
  }

  .settings-layout {
    margin-top: 27px;
  }

  .profile-fields,
  .editor-fields {
    grid-template-columns: 1fr;
  }

  .theme-grid {
    grid-template-columns: 1fr;
  }

  .theme-option {
    display: flex;
    align-items: center;
    gap: 12px;
  }

  .theme-preview {
    width: 118px;
    min-height: 58px;
    flex: 0 0 118px;
  }

  .theme-option-meta {
    width: 100%;
    padding: 0;
  }

  .content-actions {
    align-items: stretch;
    flex-direction: column;
    gap: 11px;
  }

  .save-note {
    justify-content: center;
    order: 2;
  }

  .save-button {
    justify-content: center;
    order: 1;
  }

  .profile-summary {
    flex-wrap: wrap;
  }

  .subtle-button {
    margin-left: 54px;
  }

  .shortcut-row {
    align-items: flex-start;
  }
}
